INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ilenburg1993/chatgpt-docker-puppeteer/rag-mcp-lsp-ops', 'rag-mcp-lsp-ops', 'Ilenburg1993', 'chatgpt-docker-puppeteer', 'community', 'rag-mcp-lsp-ops Ilenburg1993 chatgpt-docker-puppeteer community rag-mcp-lsp-ops是一个基于Puppeteer的自主AI代理，用于浏览器自动化，具有域驱动任务处理、自适应验证和实时监控功能 rag-mcp-lsp-opsはPuppeteerを基盤とする自律型AIエージェントであり、ブラウザ自動化を実現し、ドメイン駆動タスク処理、適応型バリデーション、リアルタイムモニタリング機能を備えている rag-mcp-lsp-ops는 Puppeteer 기반의 자율형 AI 에이전트로서 브라우저 자동화를 구현하고 도메인 주도 작업 처리, 적응형 검증, 실시간 모니터링 기능을 제공 El agente AI rag-mcp-lsp-ops es un sistema de automatización de navegador con Puppeteer que ofrece procesamiento de tareas con validación adaptativa y monitoreo en tiempo real L''agent IA rag-mcp-lsp-ops est un système d''automatisation de navigateur avec Puppeteer qui propose un traitement de tâches avec validation adaptative et surveillance en temps réel Der KI-Agent rag-mcp-lsp-ops ist ein System für die Browser-Automatisierung mit Puppeteer, das eine Aufgabenverarbeitung mit adaptiver Validierung und Echtzeit-Überwachung bietet O rag-mcp-lsp-ops é um agente AI autônomo para automação de navegador com Puppeteer, processamento de tarefas orientado a domínio e validação adaptativa ИИ агент rag-mcp-lsp-ops для автоматизации браузера с Puppeteer, доменно-ориентированной обработки задач и адаптивной валидации وكيل الذكاء الاصطناعي rag-mcp-lsp-ops للتحكم في المتصفح مع Puppeteer وعمليات المهام الموجهة بالمحتوى والتحقق التكيفي 🤖 Autonomous AI agent for browser automation with Puppeteer - Domain-driven task processing with adaptive validation and real-time monitoring AI智能代理 浏览器自动化 Puppeteer 如何使用rag-mcp-lsp-ops rag-mcp-lsp-ops安装 rag-mcp-lsp-ops设置指南 浏览器自动化工具 AI工具 🤖 Autonomous AI agent for browser automation with Puppeteer - Domain-driven task processing with adaptive validation and real-time monitoring');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('curiositech/some_claude_skills/team-builder', 'community', 'curiositech', 'some_claude_skills', 'curiositech/some_claude_skills', 'team-builder', 46, 7, 44, '2026-03-05T09:53:16Z', '2026-03-06T06:36:14.642Z', '83c23039861e24b6b0c2aae636192e2c3c0a640e2abfa835b89d597e0c7c166a', '{"id":"curiositech/some_claude_skills/team-builder","name":"team-builder","description":{"en":"The team-builder skill specializes in building high-performing teams with complementary personalities and skills, leveraging organizational psychology and team dynamics expertise to drive exceptional results for developers and managers","zh":"团队建设工具是专门为打造高效团队而设计的AI工具，支持团队动态、组织心理学和管理科学。","ja":"チームビルダーは、高効率のチームを構築するための専用AIエージェントです。チーム動態、組織心理学、管理科学をサポートします。","ko":"팀 빌더는 효율적인 팀 구성을 위한 전문 AI 도구로, 팀 동력학, 조직 심리학, 관리 과학을 지원합니다.","es":"El constructor de equipos de AI es una herramienta que utiliza la psicología organizacional y la ciencia de la gestión para construir equipos de alto rendimiento","fr":"L''outil de construction d''équipe est un outil qui utilise la psychologie organisationnelle et la science de la gestion pour construire des équipes de haute performance","de":"Das Team-Builder-AI-Tool ist ein Instrument, das die Organisationspsychologie und die Managementwissenschaft nutzt, um High-Performance-Teams aufzubauen","pt":"O Team-Builder é uma habilidade que ajuda a criar equipes de alto desempenho com personalidades e habilidades complementares. Ele se integra com outras habilidades como Orchestrator e Research-Analyst.","ru":"Team-Builder - это навык, который помогает создавать высокопроизводительные команды с дополняющими личностями и навыками. Он интегрируется с другими навыками, такими как Orchestrator и Research-Analyst.","ar":"الفريق-بيلدر هو مهارة تساعد على إنشاء فرق عالية الأداء مع شخصيات ومهارات متكاملة. وهو يدمج مع مهارات أخرى مث