INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('curiositech/some_claude_skills/team-builder', 'team-builder', 'curiositech', 'some_claude_skills', 'community', 'team-builder curiositech some_claude_skills community The team-builder skill specializes in building high-performing teams with complementary personalities and skills, leveraging organizational psychology and team dynamics expertise to drive exceptional results for developers and managers 团队建设工具是专门为打造高效团队而设计的AI工具，支持团队动态、组织心理学和管理科学。 チームビルダーは、高効率のチームを構築するための専用AIエージェントです。チーム動態、組織心理学、管理科学をサポートします。 팀 빌더는 효율적인 팀 구성을 위한 전문 AI 도구로, 팀 동력학, 조직 심리학, 관리 과학을 지원합니다. El constructor de equipos de AI es una herramienta que utiliza la psicología organizacional y la ciencia de la gestión para construir equipos de alto rendimiento L''outil de construction d''équipe est un outil qui utilise la psychologie organisationnelle et la science de la gestion pour construire des équipes de haute performance Das Team-Builder-AI-Tool ist ein Instrument, das die Organisationspsychologie und die Managementwissenschaft nutzt, um High-Performance-Teams aufzubauen O Team-Builder é uma habilidade que ajuda a criar equipes de alto desempenho com personalidades e habilidades complementares. Ele se integra com outras habilidades como Orchestrator e Research-Analyst. Team-Builder - это навык, который помогает создавать высокопроизводительные команды с дополняющими личностями и навыками. Он интегрируется с другими навыками, такими как Orchestrator и Research-Analyst. الفريق-بيلدر هو مهارة تساعد على إنشاء فرق عالية الأداء مع شخصيات ومهارات متكاملة. وهو يدمج مع مهارات أخرى مثل Orchestrator و Research-Analyst. how to use team-builder team-builder alternative team-builder setup guide what is team-builder team-builder vs orchestrator team-builder install for AI agents team-builder and research-analyst integration team composition with team-builder team-builder for developers team-builder and project management 团队建设工具 AI工具 团队动态 组织心理学 管理科学 orchestrator research-analyst 团队构建 协作支持 Works with orchestrator to streamline team management Integrates with research-analyst for data-driven team composition Supports project-management-guru-adhd for tailored project planning Collaborates with skill-coach to develop team members'' skills Responds to team building, team composition, and organizational psychology triggers team-builder is an AI agent skill that specializes in building high-performing teams with complementary personalities and skills, using expertise in organizational psychology, team dynamics, and management science');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('f/prompts.chat/widget-generator', 'community', 'f', 'prompts.chat', 'f/prompts.chat', 'widget-generator', 149619, 19672, 43, '2026-03-02T13:04:57Z', '2026-03-06T02:31:53.647Z', 'efc37f2fc7345b6a79558613f4ead2c44df8a13525cb8d7bc69a332d9241b442', '{"id":"f/prompts.chat/widget-generator","name":"widget-generator","description":{"en":"The widget-generator skill guides developers in creating widget plugins for prompts.chat. It enables the injection of promotional content, sponsor cards, or custom interactive components into AI prompt feeds, benefiting developers working with LLMs like GPT-4 and Claude.","zh":"widget-generator 是一个开源技能，指导开发者创建可注入 prompts.chat 信息流的小部件插件。这些插件可用于展示推广内容、赞助商卡片或自定义交互式组件，支持标准样式和完全自定义的 React 组件两种渲染模式。","ja":"widget-generator は、開発者が prompts.chat のフィードに注入可能なウィジェットプラグインを作成するためのオープンソーススキルです。プロモーションコンテンツ、スポンサーカード、またはカスタムインタラクティブコンポーネントの表示に利用でき、標準スタイルと完全カスタムの React コンポーネントの2つのレンダリングモードをサポートします。","ko":"widget-generator는 개발자가 prompts.chat 피드에 주입할 수 있는 위젯 플러그인을 생성하도록 안내하는 오픈 소스 스킬입니다. 프로모션 콘텐츠, 스폰서 카드 또는 사용자 정의 인터랙티브 컴포넌트를 표시하는 데 사용되며, 표준 스타일과 완전한 커스텀 React 컴포넌트라는 두 가지 렌더링 모드를 지원합니다.","es":"Widget Generator es una skill para desarrollar plugins de widgets para prompts.chat. Permite crear componentes promocionales o interactivos usando React y TypeScript, con soporte para dos modos de renderizado.","fr":"Widget Generator est une compétence pour développer des plugins de widgets pour prompts.chat. Il permet de créer des composants promotionnels ou interactifs en utilisant React et TypeScript, avec deux modes de rendu.","de":"Widget Generator ist eine Skill zur Entwicklung von Widget-Plugins für prompts.chat. Ermöglicht die Erstellung von Werbe- oder interaktiven Komponenten mit React und TypeScript und unterstützt zwei Rendering-Modi.","pt":"O widget-generator é uma skill de código aberto que permite a criação de plugins para a plataforma prompts.chat. Desenvolvedores podem construir componentes promocionais ou interativos que são injetados diretamente nos feeds de prompts, utilizando Next.js e TypeScript.","ru":"widget-generator — это опенсорс навык для создания плагинов под платформу prompts.chat. Разработчики могут строить промо- или интерактивные компоненты, внедряемые прямо в ленты промптов, с использованием Next.js и TypeScript.","ar":"widget-generator هو مهارة مفتوحة المصدر تتيح إنشاء إضافات لمنصة prompts.chat. يمكن للمطورين بناء مكونات ترويجية أو تفاعلية يتم حقنها مباشرة في خلاصات النماذج، باستخدام Next.js و TypeScript."},"seo":{"title":{"en":"widget-generator: Build Custom Prompt Widgets for LLMs | ...","zh":"widget-generator 设置指南：为 prompts.chat 创建自定义 AI 代理组件","ja":"widget-generator セットアップガイド：prompts.chat 用カスタム AIエージェントウィジ...","ko":"widget-generator 설정 가이드: prompts.chat용 커스텀 AI 에이전트 위젯 생성","es":"Widget Generator: Guía de Desarrollo para Agentes IA","fr":"Widget Generator : Guide de Développement pour Outils IA","de":"Widget Generator: Entwicklungsleitfaden für KI-Agenten","pt":"Widget Generator: Guia de Setup para Agentes de IA em Nex...","ru":"Генератор Виджетов: Руководство по настройке для ИИ Агентов","ar":"دليل إعداد مولد الودجات لأدوات الذكاء الاصطناعي في Next.js"},"description":{"en":"Learn to build and inject custom widgets into prompt feeds for ChatGPT, Claude, and Gemini. This open-source Next.js skill supports both standard PromptCard ...","zh":"学习使用 widget-generator 为 prompts.chat 创建自定义提示组件。支持标准 PromptCard 样式和完全自定义的 React 组件，专为 AI 代理和提示工程设计。开源且支持自托管。","ja":"widget-generator を使用して、prompts.chat 用のカスタムプロンプトコンポーネントを作成する方法。標準の PromptCard スタイルと完全なカスタム React コンポーネントをサポート。AIエージェントとプロンプトエンジニアリングに最適。オープンソースでセルフホスト可能。","ko":"widget-generator를 사용하여 prompts.chat용 커스텀 프롬프트 컴포넌트를 생성하는 방법을 알아보세요. 표준 PromptCard 스타일과 완전한 커스텀 React 컴포넌트를 지원합니다. AI 에이전트와 프롬프트 엔지니어링에 적합하며, 오픈 소스 및 셀프 호스팅이 ...","es":"Aprende a crear widgets para prompts.chat con React y TypeScript. Incluye componentes personalizados, estilos PromptCard y es open-source. Ideal para desarro...","fr":"Apprenez à créer des widgets pour prompts.chat avec React et TypeScript. Comprend des composants personnalisés, styles PromptCard et est open-source. Pour dé...","de":"Erfahren Sie, wie Sie Widgets für prompts.chat mit React und TypeScript erstellen. Beinhaltet benutzerdefinierte Komponenten, PromptCard-Stile und ist Open-S...","pt":"Aprenda a criar widgets personalizados para prompts.chat com React e TypeScript. Guia para desenvolvedores sobre modos de renderização padrão e customizados ...","ru":"Создавайте пользовательские виджеты для prompts.chat с помощью React и TypeScript. Руководство для разработчиков по стандартному и кастомному рендерингу для ...","ar":"تعلم كيفية إنشاء ودجات مخصصة لـ prompts.chat باستخدام React و TypeScript. دليل للمطورين حول أوضاع التصيير القياسية والمخصصة لأدوات الذكاء الاصطناعي."},"definition":{"en":"widget-generator is an open-source AI agent skill for creating widget plugins that are injected into prompt feeds on prompts.chat. It supports two rendering modes: standard prompt widgets using default PromptCard styling and custom render widgets built as full React components.","zh":"widget-generator 是一个用于 prompts.chat 平台的开发工具，它使开发者能够构建小部件插件。这些插件可以集成到提示信息流中，以显示赞助内容或创建独特的交互元素，支持使用标准 UI 或自定义 React 代码。","ja":"widget-generator は、prompts.chat プラットフォーム向けの開発ツールで、開発者がウィジェットプラグインを構築できるようにします。これらのプラグインはプロンプトフィードに統合され、スポンサーコンテンツの表示や独自のインタラクティブ要素の作成に使用され、標準 UI またはカスタム React コードをサポートします。","ko":"widget-generator는 prompts.chat 플랫폼을 위한 개발 도구로, 개발자가 위젯 플러그인을构建할 수 있게 합니다. 이러한 플러그인은 프롬프트 피드에 통합되어 스폰서 콘텐츠를 표시하거나 고유한 인터랙티브 요소를 생성하는 데 사용되며, 표준 UI 또는 커스텀 React 코드를 지원합니다.","es":"Widget Generator es una herramienta de desarrollo open-source para crear widgets insertables en feeds de prompts.chat. Estos widgets muestran contenido promocional, tarjetas de patrocinadores o componentes interactivos personalizados usando React y TypeScript.","fr":"Widget Generator est un outil de développement open-source pour créer des widgets intégrables dans les flux de prompts.chat. Ces widgets affichent du contenu promotionnel, des cartes de sponsors ou des composants interactifs personnalisés utilisant React et TypeScript.","de":"Widget Generator ist ein Open-Source-Entwicklungstool zum Erstellen von einbettbaren Widgets in prompts.chat-Feeds. Diese Widgets zeigen Werbeinhalte, Sponsor-Karten oder benutzerdefinierte interaktive Komponenten mit React und TypeScript an.","pt":"Widget Generator é uma skill para desenvolvedores que desejam criar e injetar widgets personalizados no feeds de prompts do prompts.chat. Suporta dois modos de renderização: um padrão que usa o estilo PromptCard e um customizado com componentes React completos.","ru":"Генератор Виджетов — это навык для разработчиков, желающих создавать и внедрять кастомные виджеты в ленты промптов на prompts.chat. Поддерживает два режима рендеринга: стандартный со стилями PromptCard и кастомный с полными React-компонентами.","ar":"مولد الودجات هو مهارة للمطورين الراغبين في إنشاء وحقن ودجات مخصصة في خلاصات النماذج على prompts.chat. يدعم وضعي تصيير: قياسي باستخدام نمط PromptCard ومخصص بمكونات React كاملة."},"features":{"en":["Supports two rendering modes: Standard prompt widget and Custom render widget","Generates widgets using default PromptCard styling (e.g., coderabbit.ts)","Enables creation of full custom React components (e.g., book.tsx)","Injects widgets into prompt feeds for displaying promotional content or sponsor cards","Built with Next.js and TypeScript for type-safe development"],"zh":["支持两种渲染模式：标准 PromptCard 样式和完全自定义的 React 组件","专为集成到 prompts.chat 的提示信息流中而设计","能够创建展示推广内容和赞助商卡片的组件","支持构建自定义的交互式组件","基于 Next.js 和 TypeScript 技术栈","开源且支持完全隐私的自托管部署"],"ja":["2つのレンダリングモードをサポート：標準 PromptCard スタイルと完全カスタム React コンポーネント","prompts.chat のプロンプトフィードへの統合に特化","プロモーションコンテンツやスポンサーカードを表示するコンポーネントの作成が可能","カスタムインタラクティブコンポーネントの構築をサポート","Next.js と TypeScript の技術スタックを基盤","オープンソースで完全なプライバシーを備えたセルフホスティングに対応"],"ko":["두 가지 렌더링 모드 지원: 표준 PromptCard 스타일과 완전한 커스텀 React 컴포넌트","prompts.chat의 프롬프트 피드에 통합되도록 설계됨","프로모션 콘텐츠 및 스폰서 카드를 표시하는 컴포넌트 생성 가능","사용자 정의 인터랙티브 컴포넌트 구축 지원","Next.js 및 TypeScript 기술 스택 기반","오픈 소스이며 완전한 프라이버시를 위한 셀프 호스팅 지원"],"es":["Dos modos de renderizado: Standard PromptCard y componentes React personalizados","Desarrollo con TypeScript para type safety","Integración con plataforma Next.js de prompts.chat","Creación de widgets promocionales e interactivos","Soporte para componentes de tarjetas de patrocinio","Open-source y auto-hospedaje para privacidad"],"fr":["Deux modes de rendu : Standard PromptCard et composants React personnalisés","Développement avec TypeScript pour la sécurité des types","Intégration avec la plateforme Next.js de prompts.chat","Création de widgets promotionnels et interactifs","Prise en charge des composants de cartes de sponsors","Open-source et auto-hébergement pour la confidentialité"],"de":["Zwei Rendering-Modi: Standard PromptCard und benutzerdefinierte React-Komponenten","Entwicklung mit TypeScript für Type Safety","Integration mit der Next.js-Plattform von prompts.chat","Erstellung von Werbe- und interaktiven Widgets","Unterstützung für Sponsor-Karten-Komponenten","Open-Source und Selbsthosting für Privatsphäre"],"pt":["Injeção de widgets em feeds de prompts do prompts.chat","Modo de renderização padrão com estilização PromptCard (ex: coderabbit.ts)","Modo de renderização customizado com componentes React completos (ex: book.tsx)","Desenvolvimento com TypeScript para type safety","Framework Next.js para renderização e roteamento","Código aberto e auto-hospedagem para privacidade total"],"ru":["Внедрение виджетов в ленты промптов на prompts.chat","Стандартный режим рендеринга со стилизацией PromptCard (напр., coderabbit.ts)","Кастомный режим рендеринга с полными React-компонентами (напр., book.tsx)","Разработка на TypeScript для типобезопасности","Фреймворк Next.js для рендеринга и маршрутизации","Опенсорс и самохостинг для полной конфиденциальности"],"ar":["حقن الودجات في خلاصات النماذج على prompts.chat","وضع التصيير القياسي مع تصميم PromptCard (مثل: coderabbit.ts)","وضع التصيير المخصص بمكونات React كاملة (مثل: book.tsx)","التطوير باستخدام TypeScript لسلامة الأنواع","إطار عمل Next.js للتصيير والتوجيه","مفتوح المصدر والاستضافة الذاتية للخصوصية الكاملة"]},"keywords":{"en":["how to create prompts.chat widget","widget-generator vs custom prompt development","widget-generator setup guide","Next.js prompt widget tutorial","build custom React component for AI prompts","what is widget-generator skill","open-source prompt engineering tools","inject promotional content into LLM feeds"],"zh":["widget-generator 教程","prompts.chat 小部件开发","AI 代理提示组件","自定义 React 提示小部件","开源提示工程工具","Next.js TypeScript 小部件","自托管 AI 工具","提示信息流集成"],"ja":["widget-generator チュートリアル","prompts.chat ウィジェット開発","AIエージェント プロンプトコンポーネント","カスタム React プロンプトウィジェット","オープンソース プロンプトエンジニアリングツール","Next.js TypeScript ウィジェット","セルフホスト AIツール","プロンプトフィード統合"],"ko":["widget-generator 튜토리얼","prompts.chat 위젯 개발","AI 에이전트 프롬프트 컴포넌트","커스텀 React 프롬프트 위젯","오픈 소스 프롬프트 엔지니어링 도구","Next.js TypeScript 위젯","셀프 호스팅 AI 도구","프롬프트 피드 통합"],"es":["desarrollar widgets prompts.chat","React TypeScript widget generator","componentes personalizados prompts chat","open source widget AI","modo renderizado PromptCard","self-host widget generator","prompt engineering widgets","crear plugins prompts comunidad"],"fr":["développer widgets prompts.chat","React TypeScript widget generator","composants personnalisés prompts chat","open source widget IA","mode rendu PromptCard","self-host widget generator","ingénierie de prompts widgets","créer plugins prompts communauté"],"de":["Widgets entwickeln prompts.chat","React TypeScript Widget Generator","benutzerdefinierte Komponenten prompts chat","open source widget KI","Rendering-Modus PromptCard","self-host widget generator","Prompt Engineering Widgets","Plugins erstellen prompts Gemeinschaft"],"pt":["criar widget prompts.chat","plugin prompt engineering","nextjs typescript widget","renderização customizada react","open source ai agents","self-host prompts chat","componente promotional llm"],"ru":["создать виджет prompts.chat","плагин prompt engineering","nextjs typescript виджет","кастомный рендеринг react","опенсорс ИИ агенты","самохостинг prompts chat","промо компонент llm"],"ar":["إنشاء ودجت prompts.chat","إضافة prompt engineering","nextjs typescript ودجت","تصيير مخصص react","مفتوح المصدر أدوات الذكاء الاصطناعي","استضافة ذاتية prompts chat","مكون ترويجي llm"]}},"owner":"f","repo":"prompts.chat","repoPath":"f/prompts.chat","stars":149619,"forks":19672,"updatedAt":"2026-03-02T13:04:57Z","topics":["ai","artificial-intelligence","awesome-list","chatgpt","chatgpt-prompts","claude","gemini","gpt","gpt-4","llm","machine-learning","nextjs","open-source","openai","prompt-engineering","prompts","prompts-chat","typescript"],"category":"community","skillMd":{"name":"widget-generator","description":"Generate customizable widget plugins for the prompts.chat feed system","bodyPreview":"# Widget Generator Skill\n\nThis skill guides creation of widget plugins for **prompts.chat**. Widgets are injected into prompt feeds to display promotional content, sponsor cards, or custom interactive components.\n\n## Overview\n\nWidgets support two rendering modes:\n1. **Standard prompt widget** - Uses default `PromptCard` styling (like `coderabbit.ts`)\n2. **Custom render widget** - Full custom React component (like `book.tsx`)\n\n## Prerequisites\n\nBefore creating a widget, gather from the user:\n\n| P","body":"# Widget Generator Skill\n\nThis skill guides creation of widget plugins for **prompts.chat**. Widgets are injected into prompt feeds to display promotional content, sponsor cards, or custom interactive components.\n\n## Overview\n\nWidgets support two rendering modes:\n1. **Standard prompt widget** - Uses default `PromptCard` styling (like `coderabbit.ts`)\n2. **Custom render widget** - Full custom React component (like `book.tsx`)\n\n## Prerequisites\n\nBefore creating a widget, gather from the user:\n\n| Parameter | Required | Description |\n|-----------|----------|-------------|\n| Widget ID | ✅ | Unique identifier (kebab-case, e.g., `my-sponsor`) |\n| Widget Name | ✅ | Display name for the plugin |\n| Rendering Mode | ✅ | `standard` or `custom` |\n| Sponsor Info | ❌ | Name, logo, logoDark, URL (for sponsored widgets) |\n\n## Step 1: Gather Widget Configuration\n\nAsk the user for the following configuration options:\n\n### Basic Info\n```\n- id: string (unique, kebab-case)\n- name: string (display name)\n- slug: string (URL-friendly identifier)\n- title: string (card title)\n- description: string (card description)\n```\n\n### Content (for standard mode)\n```\n- content: string (prompt content, can be multi-line markdown)\n- type: \"TEXT\" | \"STRUCTURED\"\n- structuredFormat?: \"json\" | \"yaml\" (if type is STRUCTURED)\n```\n\n### Categorization\n```\n- tags?: string[] (e.g., [\"AI\", \"Development\"])\n- category?: string (e.g., \"Development\", \"Writing\")\n```\n\n### Action Button\n```\n- actionUrl?: string (CTA link)\n- actionLabel?: string (CTA button text)\n```\n\n### Sponsor (optional)\n```\n- sponsor?: {\n    name: string\n    logo: string (path to light mode logo)\n    logoDark?: string (path to dark mode logo)\n    url: string (sponsor website)\n  }\n```\n\n### Positioning Strategy\n```\n- positioning: {\n    position: number (0-indexed start position, default: 2)\n    mode: \"once\" | \"repeat\" (default: \"once\")\n    repeatEvery?: number (for repeat mode, e.g., 30)\n    maxCount?: number (max occurrences, default: 1 for once, unlimited for repeat)\n  }\n```\n\n### Injection Logic\n```\n- shouldInject?: (context) => boolean\n  Context contains:\n  - filters.q: search query\n  - filters.category: category name\n  - filters.categorySlug: category slug\n  - filters.tag: tag filter\n  - filters.sort: sort option\n  - itemCount: total items in feed\n```\n\n## Step 2: Create Widget File\n\n### Standard Widget (TypeScript only)\n\nCreate file: `src/lib/plugins/widgets/{widget-id}.ts`\n\n```typescript\nimport type { WidgetPlugin } from \"./types\";\n\nexport const {widgetId}Widget: WidgetPlugin = {\n  id: \"{widget-id}\",\n  name: \"{Widget Name}\",\n  prompts: [\n    {\n      id: \"{prompt-id}\",\n      slug: \"{prompt-slug}\",\n      title: \"{Title}\",\n      description: \"{Description}\",\n      content: `{Multi-line content here}`,\n      type: \"TEXT\",\n      // Optional sponsor\n      sponsor: {\n        name: \"{Sponsor Name}\",\n        logo: \"/sponsors/{sponsor}.svg\",\n        logoDark: \"/sponsors/{sponsor}-dark.svg\",\n        url: \"{sponsor-url}\",\n      },\n      tags: [\"{Tag1}\", \"{Tag2}\"],\n      category: \"{Category}\",\n      actionUrl: \"{action-url}\",\n      actionLabel: \"{Action Label}\",\n      positioning: {\n        position: 2,\n        mode: \"repeat\",\n        repeatEvery: 50,\n        maxCount: 3,\n      },\n      shouldInject: (context) => {\n        const { filters } = context;\n        \n        // Always show when no filters active\n        if (!filters?.q && !filters?.category && !filters?.tag) {\n          return true;\n        }\n        \n        // Add custom filter logic here\n        return false;\n      },\n    },\n  ],\n};\n```\n\n### Custom Render Widget (TSX with React)\n\nCreate file: `src/lib/plugins/widgets/{widget-id}.tsx`\n\n```tsx\nimport Link from \"next/link\";\nimport Image from \"next/image\";\nimport { Button } from \"@/components/ui/button\";\nimport type { WidgetPlugin } from \"./types\";\n\nfunction {WidgetName}Widget() {\n  return (\n    <div className=\"group border rounded-[var(--radius)] overflow-hidden hover:border-foreground/20 transition-colors bg-gradient-to-br from-primary/5 via-background to-primary/10 p-5\">\n      {/* Custom widget content */}\n      <div className=\"flex flex-col items-center gap-4\">\n        {/* Image/visual element */}\n        <div className=\"relative w-full aspect-video\">\n          <Image\n            src=\"/path/to/image.jpg\"\n            alt=\"{Alt text}\"\n            fill\n            className=\"object-cover rounded-lg\"\n          />\n        </div>\n        \n        {/* Content */}\n        <div className=\"w-full text-center\">\n          <h3 className=\"font-semibold text-base mb-1.5\">{Title}</h3>\n          <p className=\"text-xs text-muted-foreground mb-4\">{Description}</p>\n          <Button asChild size=\"sm\" className=\"w-full\">\n            <Link href=\"{action-url}\">{Action Label}</Link>\n          </Button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport const {widgetId}Widget: WidgetPlugin = {\n  id: \"{widget-id}\",\n  name: \"{Widget Name}\",\n  prompts: [\n    {\n      id: \"{prompt-id}\",\n      slug: \"{prompt-slug}\",\n      title: \"{Title}\",\n      description: \"{Description}\",\n      content: \"\",\n      type: \"TEXT\",\n      tags: [\"{Tag1}\", \"{Tag2}\"],\n      category: \"{Category}\",\n      actionUrl: \"{action-url}\",\n      actionLabel: \"{Action Label}\",\n      positioning: {\n        position: 10,\n        mode: \"repeat\",\n        repeatEvery: 60,\n        maxCount: 4,\n      },\n      shouldInject: () => true,\n      render: () => <{WidgetName}Widget />,\n    },\n  ],\n};\n```\n\n## Step 3: Register Widget\n\nEdit `src/lib/plugins/widgets/index.ts`:\n\n1. Add import at top:\n```typescript\nimport { {widgetId}Widget } from \"./{widget-id}\";\n```\n\n2. Add to `widgetPlugins` array:\n```typescript\nconst widgetPlugins: WidgetPlugin[] = [\n  coderabbitWidget,\n  bookWidget,\n  {widgetId}Widget, // Add new widget\n];\n```\n\n## Step 4: Add Sponsor Assets (if applicable)\n\nIf the widget has a sponsor:\n1. Add light logo: `public/sponsors/{sponsor}.svg`\n2. Add dark logo (optional): `public/sponsors/{sponsor}-dark.svg`\n\n## Positioning Examples\n\n### Show once at position 5\n```typescript\npositioning: {\n  position: 5,\n  mode: \"once\",\n}\n```\n\n### Repeat every 30 items, max 5 times\n```typescript\npositioning: {\n  position: 3,\n  mode: \"repeat\",\n  repeatEvery: 30,\n  maxCount: 5,\n}\n```\n\n### Unlimited repeating\n```typescript\npositioning: {\n  position: 2,\n  mode: \"repeat\",\n  repeatEvery: 25,\n  // No maxCount = unlimited\n}\n```\n\n## shouldInject Examples\n\n### Always show\n```typescript\nshouldInject: () => true,\n```\n\n### Only when no filters active\n```typescript\nshouldInject: (context) => {\n  const { filters } = context;\n  return !filters?.q && !filters?.category && !filters?.tag;\n},\n```\n\n### Show for specific categories\n```typescript\nshouldInject: (context) => {\n  const slug = context.filters?.categorySlug?.toLowerCase();\n  return slug?.includes(\"development\") || slug?.includes(\"coding\");\n},\n```\n\n### Show when search matches keywords\n```typescript\nshouldInject: (context) => {\n  const query = context.filters?.q?.toLowerCase() || \"\";\n  return [\"ai\", \"automation\", \"workflow\"].some(kw => query.includes(kw));\n},\n```\n\n### Show only when enough items\n```typescript\nshouldInject: (context) => {\n  return (context.itemCount ?? 0) >= 10;\n},\n```\n\n## Custom Render Patterns\n\n### Card with gradient background\n```tsx\n<div className=\"border rounded-[var(--radius)] overflow-hidden bg-gradient-to-br from-primary/5 via-background to-primary/10 p-5\">\n```\n\n### Sponsor badge\n```tsx\n<div className=\"flex items-center gap-2 mb-2\">\n  <span className=\"text-xs font-medium text-primary\">Sponsored</span>\n</div>\n```\n\n### Responsive image\n```tsx\n<div className=\"relative w-full aspect-video\">\n  <Image src=\"/image.jpg\" alt=\"...\" fill className=\"object-cover\" />\n</div>\n```\n\n### CTA button\n```tsx\n<Button asChild size=\"sm\" className=\"w-full\">\n  <Link href=\"https://example.com\">\n    Learn More\n    <ArrowRight className=\"ml-2 h-3.5 w-3.5\" />\n  </Link>\n</Button>\n```\n\n## Verification\n\n1. Run type check:\n   ```bash\n   npx tsc --noEmit\n   ```\n\n2. Start dev server:\n   ```bash\n   npm run dev\n   ```\n\n3. Navigate to `/discover` or `/feed` to verify widget appears at configured positions\n\n## Type Reference\n\n```typescript\ninterface WidgetPrompt {\n  id: string;\n  slug: string;\n  title: string;\n  description: string;\n  content: string;\n  type: \"TEXT\" | \"STRUCTURED\";\n  structuredFormat?: \"json\" | \"yaml\";\n  sponsor?: {\n    name: string;\n    logo: string;\n    logoDark?: string;\n    url: string;\n  };\n  tags?: string[];\n  category?: string;\n  actionUrl?: string;\n  actionLabel?: string;\n  positioning?: {\n    position?: number;      // Default: 2\n    mode?: \"once\" | \"repeat\"; // Default: \"once\"\n    repeatEvery?: number;   // For repeat mode\n    maxCount?: number;      // Max occurrences\n  };\n  shouldInject?: (context: WidgetContext) => boolean;\n  render?: () => ReactNode; // For custom rendering\n}\n\ninterface WidgetPlugin {\n  id: string;\n  name: string;\n  prompts: WidgetPrompt[];\n}\n```\n\n## Common Issues\n\n| Issue | Solution |\n|-------|----------|\n| Widget not showing | Check `shouldInject` logic, verify registration in `index.ts` |\n| TypeScript errors | Ensure imports from `./types`, check sponsor object shape |\n| Styling issues | Use Tailwind classes, match existing widget patterns |\n| Position wrong | Remember positions are 0-indexed, check `repeatEvery` value |\n"},"lastSynced":"2026-03-06T02:31:53.647Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent developers building custom interactive components for LLM prompt interfaces like GPT-4 and Claude.","zh":"非常适合为LLM提示界面（如GPT-4和Claude）构建自定义交互组件的AI Agent开发者。","ja":"GPT-4やClaudeなどのLLMプロンプトインターフェース用のカスタムインタラクティブコンポーネントを構築するAI Agent開発者に最適です。","ko":"GPT-4 및 Claude와 같은 LLM 프롬프트 인터페이스를 위한 사용자 정의 인터랙티브 컴포넌트를 구축하는 AI Agent 개발자에게 이상적입니다.","es":"Ideal para desarrolladores de Agent de IA que construyen componentes interactivos personalizados para interfaces de prompt de LLM como GPT-4 y Claude.","fr":"Idéal pour les développeurs d''Agent IA qui créent des composants interactifs personnalisés pour les interfaces de prompt LLM comme GPT-4 et Claude.","de":"Ideal für AI Agent-Entwickler, die benutzerdefinierte interaktive Komponenten für LLM-Prompt-Schnittstellen wie GPT-4 und Claude erstellen.","pt":"Ideal para desenvolvedores de Agentes de IA que constroem componentes interativos personalizados para interfaces de prompt de LLM como GPT-4 e Claude.","ru":"Идеально подходит для разработчиков AI Agent, создающих пользовательские интерактивные компоненты для интерфейсов подсказок LLM, таких как GPT-4 и Claude.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يقومون ببناء مكونات تفاعلية مخصصة لواجهات مطالبات نماذج اللغة الكبيرة (LLM) مثل GPT-4 وClaude."},"recommendation":{"en":"Enables injection of promotional content, sponsor cards, and custom interactive components into AI prompt feeds using React components. Supports both standard PromptCard styling and full custom React rendering modes for flexible widget implementation.","zh":"支持使用React组件将促销内容、赞助商卡片和自定义交互组件注入到AI提示信息流中。支持标准的PromptCard样式和完全自定义的React渲染模式，以实现灵活的小部件实施。","ja":"Reactコンポーネントを使用して、プロモーションコンテンツ、スポンサーカード、およびカスタムインタラクティブコンポーネントをAIプロンプトフィードに注入することを可能にします。標準的なPromptCardスタイリングと完全なカスタムReactレンダリングモードの両方をサポートし、柔軟なウィジェット実装を提供します。","ko":"React 컴포넌트를 사용하여 프로모션 콘텐츠, 스폰서 카드 및 사용자 정의 인터랙티브 컴포넌트를 AI 프롬프트 피드에 주입할 수 있도록 합니다. 표준 PromptCard 스타일링과 완전한 사용자 정의 React 렌더링 모드를 모두 지원하여 유연한 위젯 구현이 가능합니다.","es":"Permite la inyección de contenido promocional, tarjetas de patrocinador y componentes interactivos personalizados en los feeds de prompt de IA utilizando componentes React. Es compatible con los estilos estándar de PromptCard y los modos de renderizado personalizado completo de React para una implementación flexible de widgets.","fr":"Permet l''injection de contenu promotionnel, de cartes de sponsor et de composants interactifs personnalisés dans les flux de prompt IA en utilisant des composants React. Prend en charge à la fois le style standard PromptCard et les modes de rendu React personnalisés complets pour une implémentation flexible de widgets.","de":"Ermöglicht die Injektion von Werbeinhalten, Sponsor-Cards und benutzerdefinierten interaktiven Komponenten in AI-Prompt-Feeds unter Verwendung von React-Komponenten. Unterstützt sowohl das standardmäßige PromptCard-Styling als auch vollständige benutzerdefinierte React-Rendering-Modi für eine flexible Widget-Implementierung.","pt":"Permite a injeção de conteúdo promocional, cartões de patrocinador e componentes interativos personalizados nos feeds de prompt de IA usando componentes React. Suporta tanto o estilo padrão PromptCard quanto modos de renderização React personalizados completos para uma implementação flexível de widgets.","ru":"Позволяет внедрять рекламный контент, спонсорские карточки и пользовательские интерактивные компоненты в ленты подсказок ИИ с использованием компонентов React. Поддерживает как стандартный стиль PromptCard, так и режимы полной пользовательской React-визуализации для гибкой реализации виджетов.","ar":"يتيح حقن المحتوى الترويجي وبطاقات الرعاة والمكونات التفاعلية المخصصة في خلاصات مطالبات الذكاء الاصطناعي باستخدام مكونات React. يدعم كلًا من نمط التصميم القياسي PromptCard ووضعات عرض React المخصصة بالكامل لتنفيذ مرن للعناصر البرمجية (widgets)."},"useCases":{"en":["Creating promotional content widgets for prompt feeds","Developing sponsor card components for AI interfaces","Building custom interactive React components for LLM platforms"],"zh":["为提示信息流创建促销内容小部件","为AI界面开发赞助商卡片组件","为LLM平台构建自定义交互式React组件"],"ja":["プロンプトフィード用のプロモーションコンテンツウィジェットの作成","AIインターフェース用のスポンサーカードコンポーネントの開発","LLMプラットフォーム用のカスタムインタラクティブReactコンポーネントの構築"],"ko":["프롬프트 피드를 위한 프로모션 콘텐츠 위젯 생성","AI 인터페이스를 위한 스폰서 카드 컴포넌트 개발","LLM 플랫폼을 위한 사용자 정의 인터랙티브 React 컴포넌트 구축"],"es":["Creación de widgets de contenido promocional para feeds de prompt","Desarrollo de componentes de tarjetas de patrocinador para interfaces de IA","Construcción de componentes interactivos personalizados de React para plataformas LLM"],"fr":["Création de widgets de contenu promotionnel pour les flux de prompt","Développement de composants de cartes de sponsor pour les interfaces IA","Construction de composants React interactifs personnalisés pour les plateformes LLM"],"de":["Erstellung von Werbecontent-Widgets für Prompt-Feeds","Entwicklung von Sponsor-Card-Komponenten für KI-Schnittstellen","Erstellung benutzerdefinierter interaktiver React-Komponenten für LLM-Plattformen"],"pt":["Criando widgets de conteúdo promocional para feeds de prompt","Desenvolvendo componentes de cartão de patrocinador para interfaces de IA","Construindo componentes React interativos personalizados para plataformas LLM"],"ru":["Создание виджетов рекламного контента для лент подсказок","Разработка компонентов спонсорских карточек для интерфейсов ИИ","Создание пользовательских интерактивных React-компонентов для платформ LLM"],"ar":["إنشاء عناصر برمجية (widgets) للمحتوى الترويجي لخلاصات المطالبات","تطوير مكونات بطاقات الرعاة لواجهات الذكاء الاصطناعي","بناء مكونات React تفاعلية مخصصة لمنصات نماذج اللغة الكبيرة (LLM)"]},"limitations":{"en":["Requires React component development knowledge","Limited to prompts.chat platform integration","Needs user-provided content and styling parameters"],"zh":["需要具备React组件开发知识","仅限于与prompts.chat平台集成","需要用户提供的内容和样式参数"],"ja":["Reactコンポーネント開発の知識が必要","prompts.chatプラットフォームとの統合に限定される","ユーザー提供のコンテンツとスタイリングパラメータが必要"],"ko":["React 컴포넌트 개발 지식 필요","prompts.chat 플랫폼 통합으로 제한됨","사용자가 제공한 콘텐츠 및 스타일링 매개변수가 필요함"],"es":["Requiere conocimientos de desarrollo de componentes React","Limitado a la integración con la plataforma prompts.chat","Necesita contenido proporcionado por el usuario y parámetros de estilo"],"fr":["Nécessite des connaissances en développement de composants React","Limité à l''intégration avec la plateforme prompts.chat","Nécessite un contenu et des paramètres de style fournis par l''u