INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('artsy/eigen/bump-ios-version', 'bump-ios-version', 'artsy', 'eigen', 'community', 'bump-ios-version artsy eigen community android app app-store art ios objective-c react-native swift The bump-ios-version skill helps developers update their iOS and Xcode versions in Eigen, supporting React-Native, Objective-C, and Swift. It benefits mobile app developers working with Artsy''s mobile app or similar projects. bump-ios-version AIエージェント帮助您升级iOS和Xcode版本，并支持CircleCI和React Native bump-ios-version AIエージェントは、iOSとXcodeのバージョンをアップグレードし、CircleCIとReact Nativeをサポートします bump-ios-version AI 도구는 iOS와 Xcode 버전을 업그레이드하고 CircleCI와 React Native를 지원하는 데 도움이 됩니다 Esta habilidad te guía a través del proceso de aumento de la versión de iOS y Xcode en Eigen Cette compétence vous guide à travers le processus de mise à jour de la version d''iOS et Xcode dans Eigen Diese Fähigkeit führt Sie durch den Prozess der Aktualisierung der iOS- und Xcode-Version in Eigen O bump-ios-version é uma habilidade que ajuda a atualizar a versão do iOS e Xcode. Verifique a compatibilidade antes de fazer alterações. ИИ Агент bump-ios-version помогает обновить версию iOS и Xcode. Проверьте совместимость перед внесением изменений. أداة الذكاء الاصطناعي bump-ios-version تساعد في تحديث إصدار آي أو إس و إكس كود. تحقق من التوافق قبل إجراء التغييرات. how to use bump-ios-version bump-ios-version setup guide bump-ios-version alternative bump-ios-version vs Xcode version manager bump-ios-version install what is bump-ios-version bump-ios-version for React-Native bump-ios-version for iOS development bump-ios-version and CircleCI integration iOS版本升级 Xcode版本升级 CircleCI React Native AIエージェント iOS开发 Xcode开发 自动化版本升级 Prompts users for target iOS and Xcode versions Verifies version support with CircleCI Supports multiple iPhone models for simulators Works with React-Native, Objective-C, and Swift Checks supported Xcode versions at CircleCI developer portal Guides through bumping iOS and Xcode versions in Eigen bump-ios-version is a skill that guides users through updating their iOS and Xcode versions, verifying version support and compatibility with CircleCI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andfanilo/streamlit-echarts/building-streamlit-multipage-apps', 'community', 'andfanilo', 'streamlit-echarts', 'andfanilo/streamlit-echarts', 'building-streamlit-multipage-apps', 589, 71, 43, '2026-03-04T19:16:48Z', '2026-03-06T06:27:29.196Z', '801d8abcd2652bf3c213de7a914a5ccb5897bc3eca6ad6843d908161bcff39a5', '{"id":"andfanilo/streamlit-echarts/building-streamlit-multipage-apps","name":"building-streamlit-multipage-apps","description":{"en":"The building-streamlit-multipage-apps skill enables developers to create Streamlit apps with multiple pages, using a specific directory structure and navigation. It benefits developers working with Streamlit and ECharts.","zh":"Streamlit 多页应用构建指南，介绍如何使用 ECharts 渲染组件，实现多页应用的结构和导航","ja":"Streamlit マルチページアプリケーションの構築ガイド。ECharts を使用してレンダリングコンポーネントを作成し、複数ページアプリの構造とナビゲーションを実現します","ko":"Streamlit 멀티페이지 앱 구축 가이드. ECharts를 사용하여 렌더링 컴포넌트를 생성하고 멀티페이지 앱의 구조 및 내비게이션을 구현합니다","es":"Streamlit es un componente que renderiza ECharts. Aprende a crear aplicaciones multi-página con Streamlit","fr":"Streamlit est un composant qui rend ECharts. Découvrez comment créer des applications multi-pages avec Streamlit","de":"Streamlit ist ein Komponente, der ECharts renderiert. Erfahren Sie, wie Sie Mehrseiten-Apps mit Streamlit erstellen","pt":"Streamlit é uma biblioteca Python que permite criar aplicações web interativas. O building-streamlit-multipage-apps é um componente que renderiza ECharts em aplicações Streamlit.","ru":"Streamlit - это библиотека Python для создания интерактивных веб-приложений. Building-streamlit-multipage-apps - это компонент, который отображает ECharts в приложениях Streamlit с помощью ИИ Агентов","ar":"Streamlit هي مكتبة بايثون لإنشاء تطبيقات ويب تفاعلية. building-streamlit-multipage-apps هو مكون يعرض ECharts في تطبيقات Streamlit باستخدام وكلاء الذكاء الاصطناعي"},"seo":