INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('andfanilo/streamlit-echarts/building-streamlit-multipage-apps', 'building-streamlit-multipage-apps', 'andfanilo', 'streamlit-echarts', 'community', 'building-streamlit-multipage-apps andfanilo streamlit-echarts community echarts pyecharts streamlit The building-streamlit-multipage-apps skill enables developers to create Streamlit apps with multiple pages, using a specific directory structure and navigation. It benefits developers working with Streamlit and ECharts. Streamlit 多页应用构建指南，介绍如何使用 ECharts 渲染组件，实现多页应用的结构和导航 Streamlit マルチページアプリケーションの構築ガイド。ECharts を使用してレンダリングコンポーネントを作成し、複数ページアプリの構造とナビゲーションを実現します Streamlit 멀티페이지 앱 구축 가이드. ECharts를 사용하여 렌더링 컴포넌트를 생성하고 멀티페이지 앱의 구조 및 내비게이션을 구현합니다 Streamlit es un componente que renderiza ECharts. Aprende a crear aplicaciones multi-página con Streamlit Streamlit est un composant qui rend ECharts. Découvrez comment créer des applications multi-pages avec Streamlit Streamlit ist ein Komponente, der ECharts renderiert. Erfahren Sie, wie Sie Mehrseiten-Apps mit Streamlit erstellen Streamlit é uma biblioteca Python que permite criar aplicações web interativas. O building-streamlit-multipage-apps é um componente que renderiza ECharts em aplicações Streamlit. Streamlit - это библиотека Python для создания интерактивных веб-приложений. Building-streamlit-multipage-apps - это компонент, который отображает ECharts в приложениях Streamlit с помощью ИИ Агентов Streamlit هي مكتبة بايثون لإنشاء تطبيقات ويب تفاعلية. building-streamlit-multipage-apps هو مكون يعرض ECharts في تطبيقات Streamlit باستخدام وكلاء الذكاء الاصطناعي how to use building-streamlit-multipage-apps building-streamlit-multipage-apps setup guide streamlit multi-page apps tutorial building-streamlit-multipage-apps vs streamlit single-page apps building-streamlit-multipage-apps install what is building-streamlit-multipage-apps streamlit echarts integration building-streamlit-multipage-apps alternative Streamlit 多页应用 ECharts 渲染 PyECharts Streamlit 构建 多页应用结构 AIエージェント Streamlit AI ECharts AI Supports Streamlit multi-page apps with a specific directory structure Uses a main entry point file named streamlit_app.py Requires a pages directory named app_pages/ to avoid conflicts with Streamlit''s auto-discovery API Initializes global state shared across pages using streamlit as st Allows for rendering ECharts using pyecharts building-streamlit-multipage-apps is a Streamlit component for rendering ECharts, allowing developers to structure and navigate multi-page apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hyperlane-xyz/hyperlane-warp-ui-template/commit', 'community', 'hyperlane-xyz', 'hyperlane-warp-ui-template', 'hyperlane-xyz/hyperlane-warp-ui-template', 'commit', 184, 206, 43, '2026-02-24T22:03:59Z', '2026-03-06T06:29:04.413Z', '3151de25bc6b438850b2b47d4abe31719a88141694d8eca7179869e7fd053d9a', '{"id":"hyperlane-xyz/hyperlane-warp-ui-template/commit","name":"commit","description":{"en":"The Commit skill helps developers ensure quality and correctness when committing changes, using tools like pnpm and TypeScript. It benefits developers working on Hyperlane Warp Route UIs.","zh":"Commit 技术是用于构建 Hyperlane Warp Route UIs 的 web 应用模板，确保代码质量和正确性","ja":"Commit は Hyperlane Warp Route UIs を構築するための web アプリテンプレートで、コードの品質と正確性を確保する","ko":"Commit은 Hyperlane Warp Route UIs를 구축하기 위한 웹 애플리케이션 템플릿으로 코드 품질 및 정확성을 보장합니다","es":"El commit es una herramienta esencial para garantizar la calidad y corrección de los cambios en Hyperlane Warp Route UIs. Utiliza pnpm prettier, pnpm lint y pnpm typecheck para asegurarte de que tus cambios sean correctos","fr":"Le commit est un outil essentiel pour garantir la qualité et la correction des modifications apportées aux interfaces utilisateur Hyperlane Warp Route. Utilisez pnpm prettier, pnpm lint et pnpm typecheck pour vous assurer que vos modifications soient correctes","de":"Der Commit ist ein wichtiges Tool, um die Qualität und Richtigkeit von Änderungen in Hyperlane Warp Route Benutzeroberflächen zu gewährleisten. Verwenden Sie pnpm prettier, pnpm lint und pnpm typecheck, um sicherzustellen, dass Ihre Änderungen korrekt sind","pt":"O Commit é uma ferramenta para garantir a qualidade e correção do código em projetos Hyperlane Warp Route UIs. Ele executa uma lista de verificação antes do commit.","ru":"Commit - это инструмент для обеспечения качества и правильности кода в проектах Hyperlane Warp Route UIs. Он выполняет проверку перед коммитом.","ar":"Commit هو أداة لضمان جودة وضبط الرمز في مشاريع واجهات المستخدم Hyperlane Warp Route. يقوم بتشغيل قائمة مراجعة قبل الالتزام"},"seo":{"title":{"en":"Commit: Pre-Commit Checklist Setup Guide | AI Agent Skill","zh":"Commit Setup Guide: Hyperlane Warp Route UIs","ja":"Commit ベストプラクティス: Hyperlane Warp Route UIs を構築する","ko":"Commit 설정 가이드: Hyperlane Warp Route UIs","es":"Configuración del commit: Mejores prácticas para Hyperlan...","fr":"Mise en place du commit: Guide pour les interfaces utilis...","de":"Commit-Einrichtung: Best Practices für Hyperlane Warp Rou...","pt":"Commit Setup Guide: Melhorias para Hyperlane Warp Route UIs","ru":"ИИ Агент Commit: Настройка для Hyperlane Warp Route UIs","ar":"إعداد Commit: دليل لإنشاء واجهات مستخدم Hyperlane Warp Route"},"description":{"en":"Learn how to ensure code quality with Commit''s pre-commit checklist, featuring pnpm prettier, lint, and typecheck. Get started now!","zh":"使用 Commit 技术构建 Hyperlane Warp Route UIs，确保代码质量和正确性","ja":"Commit を使用して Hyperlane Warp Route UIs を構築し、コードの品質と正確性を確保する","ko":"Commit을 사용하여 Hyperlane Warp Route UIs를 구축하고 코드 품질 및 정확성을 보장합니다","es":"Aprende a configurar el commit para Hyperlane Warp Route UIs con nuestra guía paso a paso y asegúrate de que tus cambios sean de alta calidad","fr":"Découvrez comment configurer le commit pour les interfaces utilisateur Hyperlane Warp Route avec notre guide étape par étape et assurez-vous que vos modifica...","de":"Erfahren Sie, wie Sie den Commit für Hyperlane Warp Route Benutzeroberflächen einrichten, mit unserer Schritt-für-Schritt-Anleitung und stellen Sie sicher, d...","pt":"Aprenda a configurar o Commit para melhorar a qualidade e correção do seu código em projetos Hyperlane Warp Route UIs","ru":"Узнайте, как настроить Commit для обеспечения качества и правильности кода в проектах Hyperlane Warp Route UIs с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد Commit لتحسين جودة وضبط رمزك في مشاريع واجهات ا