INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hyperlane-xyz/hyperlane-warp-ui-template/commit', 'commit', 'hyperlane-xyz', 'hyperlane-warp-ui-template', 'community', 'commit hyperlane-xyz hyperlane-warp-ui-template community hyperlane interchain route template warp The Commit skill helps developers ensure quality and correctness when committing changes, using tools like pnpm and TypeScript. It benefits developers working on Hyperlane Warp Route UIs. Commit 技术是用于构建 Hyperlane Warp Route UIs 的 web 应用模板，确保代码质量和正确性 Commit は Hyperlane Warp Route UIs を構築するための web アプリテンプレートで、コードの品質と正確性を確保する Commit은 Hyperlane Warp Route UIs를 구축하기 위한 웹 애플리케이션 템플릿으로 코드 품질 및 정확성을 보장합니다 El commit es una herramienta esencial para garantizar la calidad y corrección de los cambios en Hyperlane Warp Route UIs. Utiliza pnpm prettier, pnpm lint y pnpm typecheck para asegurarte de que tus cambios sean correctos Le commit est un outil essentiel pour garantir la qualité et la correction des modifications apportées aux interfaces utilisateur Hyperlane Warp Route. Utilisez pnpm prettier, pnpm lint et pnpm typecheck pour vous assurer que vos modifications soient correctes Der Commit ist ein wichtiges Tool, um die Qualität und Richtigkeit von Änderungen in Hyperlane Warp Route Benutzeroberflächen zu gewährleisten. Verwenden Sie pnpm prettier, pnpm lint und pnpm typecheck, um sicherzustellen, dass Ihre Änderungen korrekt sind O Commit é uma ferramenta para garantir a qualidade e correção do código em projetos Hyperlane Warp Route UIs. Ele executa uma lista de verificação antes do commit. Commit - это инструмент для обеспечения качества и правильности кода в проектах Hyperlane Warp Route UIs. Он выполняет проверку перед коммитом. Commit هو أداة لضمان جودة وضبط الرمز في مشاريع واجهات المستخدم Hyperlane Warp Route. يقوم بتشغيل قائمة مراجعة قبل الالتزام how to use commit commit setup guide hyperlane warp route ui template pnpm prettier tutorial commit vs git hook commit install guide what is commit skill commit alternative tools commit best practices Commit 技术 Hyperlane Warp Route UIs web 应用模板 代码质量 代码正确性 pnpm prettier pnpm lint pnpm typecheck pnpm build Runs pnpm prettier for source file formatting Checks for ESLint errors using pnpm lint Verifies TypeScript compilation with pnpm typecheck Ensures production build success with pnpm build Stages only files related to the current task Commit is a web app template for building Hyperlane Warp Route UIs, providing a pre-commit checklist for code quality and correctness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('decentpaste/decentpaste/github-release', 'community', 'decentpaste', 'decentpaste', 'decentpaste/decentpaste', 'github-release', 156, 7, 43, '2026-02-26T09:31:34Z', '2026-03-06T06:29:26.850Z', 'fe9b4eaa33c45d94a94941f33b76a50d5442fad5efdc21e02b2ff452d2927344', '{"id":"decentpaste/decentpaste/github-release","name":"github-release","description":{"en":"The github-release skill automates GitHub release creation with formatted notes from commits since the last tag, benefiting developers and repository maintainers.","zh":"GitHub Release 是一个创建 GitHub 发布的工具，支持格式化的发布说明和版本更新","ja":"GitHub Release は、フォーマットされたリリース ノートとバージョン更新をサポートする GitHub リリースを作成するツールです","ko":"GitHub Release는 형식화된 릴리스 노트 및 버전 업데이트를 지원하는 GitHub 릴리스를 생성하는 도구입니다","es":"github-release es una herramienta para crear versiones de GitHub con notas formateadas desde los commits. Utiliza git y gh para la autenticación.","fr":"github-release est un outil pour créer des versions GitHub avec des notes formatées depuis les commits. Il utilise git et gh pour l''authentification.","de":"github-release ist ein Tool, um GitHub-Veröffentlichungen mit formatierten Notizen von Commits zu erstellen. Es verwendet git und gh für die Authentifizierung.","pt":"O GitHub Release é uma ferramenta para criar lançamentos no GitHub com notas formatadas a partir de commits desde a última tag, utilizando tecnologias como Rust e Tauri.","ru":"GitHub Release - это инструмент для создания релизов на GitHub с помощью ИИ Агентов и технологий zoals libp2p и end-to-end-encryption.","ar":"إصدار GitHub هو أداة لإنشاء إصدارات على GitHub مع ملاحظات مصفوفة من التعديلات منذ العلامة الأخيرة، باستخدام تكنولوجيا مثل AES-256 و P2P."},"seo":{"title":{"en":"github-release: Automated Release Management for AI Agent...","zh":"GitHub Release Setup Guide - AIエージェント工具","ja":"GitHub Release ベストプラクティス - AIエージェント","ko":"GitHub Release 설정 가이드 - AI 에이전트 도구","es":"Guía de configuración de github-release para desarrolladores","fr":"Paramétrer github-release : Guide pour les développeurs","de":"github-release Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do GitHub Release","ru":"Настройка GitHub Release: ИИ Агенты для автоматизации","ar":"دليل إعداد إصدار GitHub باستخدام أدوات ذكاء اصطناعي"},"description":{"en":"Streamline your GitHub release process with github-release. Learn how to automate release notes and version bumping with this AI agent skill.","zh":"使用 GitHub Release AI 工具创建格式化的发布说明，从而简化开发流程","ja":"GitHub Release AI エージェントを使用して、開発プロセスを効率化する","ko":"GitHub Release AI 에이전트를 사용하여 개발 프로세스를 최적화합니다","es":"Aprende a crear versiones de GitHub con notas formateadas desde los commits desde la última etiqueta con github-release","fr":"Découvrez comment créer des versions GitHub avec des notes formatées depuis les commits depuis le dernier tag avec github-release","de":"Erfahren Sie, wie Sie GitHub-Veröffentlichungen mit formatierten Notizen von Commits seit dem letzten Tag erstellen können","pt":"Aprenda a criar lançamentos no GitHub com notas formatadas a partir de commits desde a última tag, utilizando tecnologias como Rust e Tauri","ru":"Автоматизируйте создание релизов на GitHub с помощью ИИ Агентов и технологий seperti libp2p и end-to-end-encryption","ar":"تعلم كيفية إنشاء إصدارات على GitHub مع ملاحظات مصفوفة من التعديلات منذ العلامة الأخيرة، باستخدام تكنولوجيا مثل AES-256 و P2P"},"definition":{"en":"github-release is a skill that automates the creation of GitHub releases with formatted notes from commits since the last tag.","zh":"GitHub Release 是一个用于创建和管理 GitHub 发布的工具","ja":"GitHub Release は、GitHub リリースを作成および管理するツールです","ko":"GitHub Release는 GitHub 릴리스를 생성 및 관리하는 도구입니다","es":"github-release es una herramienta que crea versiones de GitHub con notas formateadas desde los commits desde la última etiqueta","fr":"github-release est un outil qui crée des versions GitHub avec des notes formatées depuis les commits depuis le dernier tag","de":"github-release ist ein Tool, das GitHub-Veröffentlichungen mit formatierten Notizen von Commits seit dem letzten Tag erstellt","pt":"O que é GitHub Release? É uma ferramenta para automatizar a criação de lançamentos no GitHub.","ru":"Что такое GitHub Release? Это инструмент для автоматизации создания релизов на GitHub.","ar":"ما هو إصدار GitHub? هو أداة لتحسين عملية إنشاء الإصدارات على GitHub."},"features":{"en":["Generates release notes from commits since the last tag using `git log` commands","Supports version bumping using `git tag`","Utilizes `gh` authentication for secure release creation","Formats release notes with commit hashes and messages using `--pretty=format`","Runs on multiple platforms, including Android, iOS, Linux, macOS, and Windows"],"zh":["使用 Git 标签创建发布说明","支持 AES-256 加密","跨平台支持，包括 Android、iOS、Linux、macOS 和 Windows","使用 Libp2p 实现点对点文件共享","支持 Tauri 框架","使用 Rust 编写"],"ja":["Git タグを使用してリリース ノートを作成","AES-256 暗号化をサポート","クロスプラットフォーム対応：Android、iOS、Linux、macOS、Windows","Libp2p を使用した P2P ファイル共有","Tauri フレームワークをサポート","Rust で書かれています"],"ko":["Git 태그를 사용하여 릴리스 노트 생성","AES-256 암호화를 지원","크로스 플랫폼 지원: 안드로이드, iOS, 리눅스, macOS, 윈도우","Libp2p를 사용한 P2P 파일 공유","Tauri 프레임워크 지원","Rust로 작성됨"],"es":["Crea versiones de GitHub con notas formateadas desde los commits","Utiliza git y gh para la autenticación","Obtiene los commits desde la última etiqueta","Formatea las notas de los commits","Soporta la creación de versiones con notas personalizadas"],"fr":["Crée des versions GitHub avec des notes formatées depuis les commits","Utilise git et gh pour l''authentification","Obtient les commits depuis le dernier tag","Formate les notes des commits","Prend en charge la création de versions avec des notes personnalisées"],"de":["Erstellt GitHub-Veröffentlichungen mit formatierten Notizen von Commits","Verwendet git und gh für die Authentifizierung","Ruft die Commits seit dem letzten Tag ab","Formatiert die Notizen der Commits","Unterstützt die Erstellung von Veröffentlichungen mit benutzerdefinierten Notizen"],"pt":["Criação de lançamentos no GitHub com notas formatadas","Utilização de tecnologias como Rust e Tauri","Suporte a end-to-end-encryption com AES-256","Integração com libp2p para compartilhamento de arquivos","Compatibilidade com plataformas como Android, iOS, Linux, macOS e Windows"],"ru":["Создание релизов на GitHub с помощью ИИ Агентов","Использование технологий zoals libp2p и end-to-end-encryption","Поддержка шифрования AES-256","Интеграция с Rust и Tauri","Совместимость с платформами như Android, iOS, Linux, macOS и Windows"],"ar":["إنشاء إصدارات على GitHub مع ملاحظات مصفوفة","استخدام تكنولوجيا مثل AES-256 و P2P","دعم التشفير من الطرف إلى الطرف","تكامل مع Rust و Tauri","متوافق مع منصات مثل Android و iOS و Linux و macOS و Windows"]},"keywords":{"en":["how to use github-release","github-release alternative","github-release setup guide","automated release management","github-release vs gitflow","github-release install","what is github-release","github-release tutorial","github-release best practices"],"zh":["GitHub Release","AIエージェント工具","Git 标签","AES-256 加密","跨平台支持","Libp2p","Tauri","Rust"],"ja":["GitHub Release","AIエージェント","Git タグ","AES-256 暗号化","クロスプラットフォーム","Libp2p","Tauri","Rust"],"ko":["GitHub Release","AI 에이전트","Git 태그","AES-256 암호화","크로스 플랫폼","Libp2p","Tauri","Rust"],"es":["github-release","herramientas de github","versiones de github","commits de git","autenticación con gh","creación de versiones","notas formateadas"],"fr":["github-release","outils github","versions github","commits git","authentification avec gh","création de versions","notes formatées"],"de":["github-release","github-tools","github-veröffentlichungen","git-commits","authentifizierung mit gh","erstellung von veröffentlichungen","formatierte notizen"],"pt":["github release","criar lançamento github","automatizar lançamento github","rust","tauri","end-to-end-encryption","aes-256","libp2p","compartilhamento de arquivos"],"ru":["github release","создание релиза на github","автоматизация релиза на github","ии агенты","libp2p","end-to-end-encryption","aes-256","rust","tauri"],"ar":["إصدار github","إنشاء إصدار على github","تحسين إصدار github","أدوات ذكاء اصطناعي","aes-256","p2p","تشفير من الطرف إلى الطرف","rust","tauri"]}},"owner":"decentpaste","repo":"decentpaste","repoPath":"decentpaste/decentpaste","stars":156,"forks":7,"updatedAt":"2026-02-26T09:31:34Z","topics":["aes-256","android","clipboard","cross-platform","decentralized","desktop-app","encryption","end-to-end-encryption","file-sharing","ios","libp2p","linux","macos","mobile-app","p2p","privacy","rust","tauri","universal-clipboard","windows"],"category":"community","skillMd":{"name":"github-release","description":"Create a GitHub release with auto-generated release notes from commits since the last tag. Uses conventional commits to categorize changes into Features, Bug Fixes, and maintenance sections.","bodyPreview":"# GitHub Release\n\nCreate GitHub release with formatted notes from commits since last tag.\n\n**Prereqs**: `gh` authenticated, existing tags in repo\n\n## Workflow\n\n1. **Get commits** since latest tag (run as separate commands):\n   ```bash\n   # First: get latest tag\n   git tag --sort=-v:refname | head -1\n   ```\n   ```bash\n   # Then: get commits since that tag (replace <TAG> with result above)\n   git log <TAG>..HEAD --pretty=format:\"%h %s%n%b---\" --no-merges\n   ```\n\n2. **Bump version** if needed:\n   -","body":"# GitHub Release\n\nCreate GitHub release with formatted notes from commits since last tag.\n\n**Prereqs**: `gh` authenticated, existing tags in repo\n\n## Workflow\n\n1. **Get commits** since latest tag (run as separate commands):\n   ```bash\n   # First: get latest tag\n   git tag --sort=-v:refname | head -1\n   ```\n   ```bash\n   # Then: get commits since that tag (replace <TAG> with result above)\n   git log <TAG>..HEAD --pretty=format:\"%h %s%n%b---\" --no-merges\n   ```\n\n2. **Bump version** if needed:\n   - Check if version in `decentpaste-app/src-tauri/tauri.conf.json` matches latest tag\n   - If yes, run `/bump-version` skill first\n   - If already bumped, continue\n\n3. **Categorize** by conventional commit prefix:\n\n   | Prefix | Section |\n   |--------|---------|\n   | `feat:` | Features & Improvements |\n   | `fix:` | Bug Fixes |\n   | `chore:`, `docs:`, `refactor:`, `perf:`, `style:`, `test:` | Under the Hood |\n\n4. **Generate notes** (omit empty sections):\n   ```markdown\n   ## What''s New in vX.X.X\n\n   [1-2 sentence summary]\n\n   ### Features & Improvements\n   - **Feature** - Description\n\n   ### Bug Fixes\n   - **Fix** - Description\n\n   ### Under the Hood\n   - **Change** - Description\n\n   ### Downloads\n\n   | Platform | Download |\n   |----------|----------|\n   | Windows | `DecentPaste_X.X.X_x64-setup.exe` |\n   | macOS (Intel) | `DecentPaste_X.X.X_x64.dmg` |\n   | macOS (Apple Silicon) | `DecentPaste_X.X.X_aarch64.dmg` |\n   | Linux (Debian/Ubuntu) | `DecentPaste_X.X.X_amd64.deb` |\n   | Linux (AppImage) | `DecentPaste_X.X.X_amd64.AppImage` |\n   | Android | `DecentPaste_X.X.X.apk` |\n\n   ---\n   **Full Changelog**: https://github.com/decentpaste/decentpaste/compare/<prev-tag>...v<version>\n   ```\n\n5. **Confirm** with user: show version, tag, commit count, notes preview\n\n6. **Commit and push version bump** (CRITICAL - must happen before creating release!):\n   ```bash\n   git add -A && git commit -m \"chore: bump version to X.X.X\"\n   git push\n   ```\n   ⚠️ CI/CD builds from the pushed code. If you create the release before pushing, CI will build the old version!\n\n7. **Create release**:\n   ```bash\n   gh release create vX.X.X --title \"DecentPaste vX.X.X\" --notes \"$(cat <<''EOF''\n   <notes>\n   EOF\n   )\"\n   ```\n\n8. **Done**: Show release URL, CI will automatically build and upload artifacts\n"},"lastSynced":"2026-03-06T06:29:26.850Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing automated GitHub release management with formatted commit notes.","zh":"适合需要自动化 GitHub 发布管理和格式化提交说明的版本控制代理。","ja":"GitHub リリース管理とフォーマットされたコミット ノートが必要なバージョン管理エージェントに最適です。","ko":"自動화된 GitHub 릴리스 관리 및 형식화된 커밋 노트가 필요한 버전 제어 에이전트에 적합합니다.","es":"Ideal para agentes de Control de Versiones que necesitan una gestión de lanzamiento de GitHub automatizada con notas de confirmación formateadas.","fr":"Idéal pour les agents de contrôle de version nécessitant une gestion de version GitHub automatisée avec des notes de validation formatées.","de":"Ideal für Version Control Agents, die eine automatisierte GitHub-Release-Verwaltung mit formatierten Commit-Hinweisen benötigen.","pt":"Ideal para Agentes de Controle de Versão que necessitam de gerenciamento de lançamento do GitHub automatizado com notas de commit formatadas.","ru":"Идеально подходит для агентов контроля версий, которым требуется автоматизированное управление выпусками GitHub с отформатированными заметками о коммитах.","ar":"مثالي لعميل التحكم في الإصدار الذي يحتاج إلى إدارة الإصدار التلقائي لجيت هاب مع ملاحظات التعديل المنسقة."},"recommendation":{"en":"Empowers agents to create GitHub releases with formatted notes from commits since the last tag, utilizing `git` and `gh` commands for seamless integration with existing repository tags and commits.","zh":"赋予代理创建 GitHub 发布的权限，使用 `git` 和 `gh` 命令从上一个标签以来提交的内容创建格式化的发布说明，以实现与现有存储库标签和提交的无缝集成。","ja":"エージェントに GitHub リリースを作成する権限を与え、最後のタグ以降のコミットからフォーマットされたリリース ノートを作成するために `git` と `gh` コマンドを使用し、既存のリポジトリ タグおよびコミットとのシームレスな統合を実現します。","ko":"에이전트가 GitHub 릴리스를 생성할 수 있도록 하고, `git` 및 `gh` 명령을 사용하여 마지막 태그 이후의 커밋에서 형식화된 릴리스 노트를 생성하여 기존 저장소 태그 및 커밋과无缝한 통합을 구현합니다.","es":"Permite a los agentes crear lanzamientos de GitHub con notas formateadas desde los commits desde la última etiqueta, utilizando los comandos `git` y `gh` para una integración transparente con las etiquetas y commits de repositorio existentes.","fr":"Permet aux agents de créer des versions GitHub avec des notes formatées à partir des validations depuis le dernier tag, en utilisant les commandes `git` et `gh` pour une intégration transparente avec les tags et les commits de dépôt existants.","de":"Ermöglicht es Agenten, GitHub-Release mit formatierten Notizen aus Commits seit dem letzten Tag zu erstellen, indem es die Befehle `git` und `gh` für eine nahtlose Integration mit bestehenden Repository-Tags und -Commits verwendet.","pt":"Permite que os agentes criem lançamentos do GitHub com notas formatadas a partir de commits desde a última tag, utilizando comandos `git` e `gh` para integração transparente com tags e commits de repositório existentes.","ru":"Позволяет агентам создавать выпуски GitHub с отформатированными заметками из коммитов с момента последнего тега, используя команды `git` и `gh` для бесшовной интеграции с существующими тегами и коммитами репозитория.","ar":"يمنح الوكلاء khảية إنشاء إصدارات جيت هاب مع ملاحظات منسقة من التعديلات منذ العلامة الأخيرة، باستخدام أوامر `git` و `gh` من أجل التكامل السلس مع علامات و تعديلات مستودع موجودة."},"useCases":{"en":["Automating GitHub release creation","Generating formatted release notes from commits","Streamlining repository maintenance with version tagging"],"zh":["自动化 GitHub 发布创建","从提交中生成格式化的发布说明","使用版本标签简化存储库维护"],"ja":["GitHub リリースの自動化","コミットからフォーマットされたリリース ノートの生成","バージョン タグを使用したリポジトリ メンテナンスの簡素化"],"ko":["GitHub 릴리스 자동화","커밋에서 형식화된 릴리스 노트 생성","버전 태그를 사용한 저장소 유지 보수简化"],"es":["Automatización de la creación de lanzamientos de GitHub","Generación de notas de lanzamiento formateadas desde los commits","Optimización del mantenimiento del repositorio con etiquetado de versión"],"fr":["Automatisation de la création de versions GitHub","Génération de notes de version formatées à partir des validations","Optimisation de la maintenance du dépôt avec un étiquetage de version"],"de":["Automatisierung der Erstellung von GitHub-Release","Erzeugung von formatierten Release-Hinweisen aus Commits","Optimierung der Repository-Wartung mit Versionsetiketten"],"pt":["Automatizar a criação de lançamento do GitHub","Gerar notas de lançamento formatadas a partir de commits","Otimizar a manutenção do repositório com marcação de versão"],"ru":["Автоматизация создания выпусков GitHub","Генерация отформатированных заметок о выпуске из коммитов","Оптимизация обслуживания репозитория с помощью тегирования версий"],"ar":["تأشير إنشاء إصدار جيت هاب تلقائي","генерация ملاحظات الإصدار المنسقة من التعديلات","تحسين صيانة المستودع بالعلامات الإصدار"]},"limitations":{"en":["Requires `gh` authentication","Existing tags in repository necessary","Limited to GitHub repositories"],"zh":["需要 `gh` 身份验证","存储库中需要现有的标签","仅限 GitHub 存储库"],"ja":["`gh` 認証が必要","リポジトリ内に既存のタグが必要","GitHub リポジトリのみ"],"ko":["`gh` 인증 필요","저장소 내에 기존 태그가 필요","GitHub 저장소만 해당"],"es":["Requiere autenticación `gh`","Etiquetas existentes en el repositorio necesarias","Limitado a los repositorios de GitHub"],"fr":["Nécessite une authentification `gh`","Des tags existants dans le dépôt sont nécessaires","Limité aux dépôts GitHub"],"de":["Erfordert `gh`-Authentifizierung","Bestehende Tags im Repository erforderlich","Begrenzt auf GitHub-Repositorys"],"pt":["Requer autenticação `gh`","Necessário ter tags existentes no repositório","Limitado a repositórios do GitHub"],"ru":["Требуется аутентификация `gh`","Необходимо наличие существующих тегов в репозитории","Ограничен выпусками GitHub"],"ar":["يتطلب المصادقة `gh`","يجب وجود علامات موجودة في المستودع","محدود بمستودعات جيت هاب"]},"version":4},"contentHash":"fe9b4eaa33c45d94a94941f33b76a50d5442fad5efdc21e02b2ff452d2927344","qualityScore":43}');
