INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('decentpaste/decentpaste/github-release', 'github-release', 'decentpaste', 'decentpaste', 'community', 'github-release decentpaste decentpaste community aes-256 android clipboard cross-platform decentralized desktop-app encryption end-to-end-encryption file-sharing ios libp2p linux macos mobile-app p2p privacy rust tauri universal-clipboard windows The github-release skill automates GitHub release creation with formatted notes from commits since the last tag, benefiting developers and repository maintainers. GitHub Release 是一个创建 GitHub 发布的工具，支持格式化的发布说明和版本更新 GitHub Release は、フォーマットされたリリース ノートとバージョン更新をサポートする GitHub リリースを作成するツールです GitHub Release는 형식화된 릴리스 노트 및 버전 업데이트를 지원하는 GitHub 릴리스를 생성하는 도구입니다 github-release es una herramienta para crear versiones de GitHub con notas formateadas desde los commits. Utiliza git y gh para la autenticación. github-release est un outil pour créer des versions GitHub avec des notes formatées depuis les commits. Il utilise git et gh pour l''authentification. github-release ist ein Tool, um GitHub-Veröffentlichungen mit formatierten Notizen von Commits zu erstellen. Es verwendet git und gh für die Authentifizierung. O GitHub Release é uma ferramenta para criar lançamentos no GitHub com notas formatadas a partir de commits desde a última tag, utilizando tecnologias como Rust e Tauri. GitHub Release - это инструмент для создания релизов на GitHub с помощью ИИ Агентов и технологий zoals libp2p и end-to-end-encryption. إصدار GitHub هو أداة لإنشاء إصدارات على GitHub مع ملاحظات مصفوفة من التعديلات منذ العلامة الأخيرة، باستخدام تكنولوجيا مثل AES-256 و P2P. how to use github-release github-release alternative github-release setup guide automated release management github-release vs gitflow github-release install what is github-release github-release tutorial github-release best practices GitHub Release AIエージェント工具 Git 标签 AES-256 加密 跨平台支持 Libp2p Tauri Rust Generates release notes from commits since the last tag using `git log` commands Supports version bumping using `git tag` Utilizes `gh` authentication for secure release creation Formats release notes with commit hashes and messages using `--pretty=format` Runs on multiple platforms, including Android, iOS, Linux, macOS, and Windows github-release is a skill that automates the creation of GitHub releases with formatted notes from commits since the last tag.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('samurmaykrr/zqlz/generate-component-story', 'community', 'samurmaykrr', 'zqlz', 'samurmaykrr/zqlz', 'generate-component-story', 92, 5, 43, '2026-02-24T02:16:56Z', '2026-03-07T01:50:00.790Z', 'e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa', '{"id":"samurmaykrr/zqlz/generate-component-story","name":"generate-component-story","description":{"en":"The generate-component-story skill helps developers create detailed component stories, following existing patterns and including comprehensive coverage of options and variants.","zh":"生成组件故事的AI工具帮助开发者创建高质量的组件故事，通过遵循现有模式和使用sections来组织内容","ja":"コンポーネントストーリー生成のAIエージェントは、開発者が高品質のコンポーネントストーリーを作成することを助けます。既存のパターンに従い、セクションを使用してコンテンツを整理します","ko":"컴포넌트 스토리 생성 AI 도구는 개발자가 고급 컴포넌트 스토리를 생성하도록 도와줍니다. 기존 패턴을 따르고 섹션을 사용하여 콘텐츠를 조직합니다","es":"Generate-component-story es una herramienta para crear historias de componentes siguiendo patrones existentes y utilizando secciones organizadas","fr":"Generate-component-story est un outil pour créer des histoires de composants en suivant des modèles existants et en utilisant des sections organisées","de":"Generate-component-story ist ein Tool zum Erstellen von Komponenten-Geschichten unter Verwendung bestehender Muster und organisierter Abschnitte","pt":"O generate-component-story é uma ferramenta para criar histórias de componentes, seguindo padrões existentes e incluindo todas as opções e variantes","ru":"Generate-component-story - это инструмент для создания историй компонентов, основанный на существующих шаблонах и включающий все опции и варианты","ar":"generate-component-story هو أداة لإنشاء قصص مكونات، يتبع نماذج موجودة ويشمل جميع الخيارات والطرز"},"seo":{"title":{"en":"generate-component-story: Comprehensive Story Creation Gu...","zh":"生成组件故事的AI工具：最佳实践","ja":"コンポーネントストーリー生成のAIエージェント：セットアップガイド","ko":"컴포넌트 스토리 생성 AI 도구: 