INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Andrej1601/HTMLSignage/websocket-engineer', 'websocket-engineer', 'Andrej1601', 'HTMLSignage', 'community', 'websocket-engineer Andrej1601 HTMLSignage community The websocket-engineer skill enables senior real-time systems engineers to design and implement scalable messaging architectures supporting millions of concurrent connections. It specializes in Socket.IO, native WebSockets, and low-latency messaging systems. WebSocket Engineer 是一名高级实时系统工程师，专门从事 WebSocket 基础设施的构建，具有 Socket.IO 和 Redis pub/sub 的专业知识 WebSocket エンジニアは、高度なリアルタイムシステムエンジニアです。WebSocket インフラストラクチャの構築に特化しており、Socket.IO と Redis pub/sub に精通しています WebSocket Engineer 는 고급 실시간 시스템 엔지니어로 WebSocket 인프라 구축에 특화되어 있으며 Socket.IO 및 Redis pub/sub 에 대한 전문 지식을 보유하고 있습니다 WebSocket Engineer es un experto en comunicación en tiempo real con Socket.IO y arquitecturas de mensajería escalables. Diseña sistemas para millones de conexiones concurrentes con latencia inferior a 10ms WebSocket Engineer est un expert en communication en temps réel avec Socket.IO et des architectures de messagerie escalables. Il conçoit des systèmes pour des millions de connexions concurrentes avec une latence inférieure à 10ms WebSocket Engineer ist ein Experte für Echtzeit-Kommunikation mit Socket.IO und skalierbarer Messaging-Architektur. Er entwirft Systeme für Millionen von gleichzeitigen Verbindungen mit einer Latenz von unter 10ms O WebSocket Engineer é um especialista em comunicação bidirecional em tempo real, com expertise em Socket.IO e arquiteturas de mensagens escaláveis. WebSocket Engineer - это специалист по реальному времени двусторонней связи, с опытом работы с Socket.IO и масштабируемыми архитектурами сообщений. مهندس WebSocket هو خبير في الاتصالات المزدوجة في الوقت الفعلي، مع خبرة في Socket.IO وهندسة الرسائل القابلة للتوسيع how to use websocket-engineer websocket-engineer setup guide websocket-engineer vs Socket.IO websocket-engineer install what is websocket-engineer websocket-engineer alternative websocket-engineer tutorial real-time messaging with websocket-engineer scalable WebSocket infrastructure websocket-engineer documentation WebSocket Engineer Socket.IO native WebSockets Redis pub/sub 实时双向通信 低延迟消息系统 水平扩展 并发连接 Designs sub-10ms p99 latency with 99.99% uptime messaging systems Implements horizontal scaling with Redis pub/sub Specializes in Socket.IO and native WebSockets Supports millions of concurrent connections Builds low-latency messaging systems Utilizes real-time bidirectional communication protocols websocket-engineer is a senior WebSocket specialist with expertise in real-time bidirectional communication, Socket.IO, and scalable messaging architectures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qwibitai/nanoclaw/pdf-reader', 'community', 'qwibitai', 'nanoclaw', 'qwibitai/nanoclaw', 'pdf-reader', 19919, 3256, 43, '2026-03-07T12:39:29Z', '2026-03-07T12:47:49.563Z', '0046569626c967941f095c38b030951a7fc0523a3c66070f72229c39d93867f9', '{"id":"qwibitai/nanoclaw/pdf-reader","name":"pdf-reader","description":{"en":"The pdf-reader skill extracts text from PDFs, preserving tables and columns, and integrates with messaging apps like WhatsApp and Telegram, benefiting AI agent developers.","zh":"PDF Reader 是一个轻量级的 PDF 解析工具，支持从 PDF 中提取文本、保留布局和连接到流行的消息应用程序","ja":"PDF Reader は、PDF からテキストを抽出し、レイアウトを保存し、人気のメッセージアプリに接続する軽量な PDF 解析ツールです","ko":"PDF Reader는 PDF에서 텍스트를 추출하고 레이아웃을 유지하며 인기 메시지 앱에 연결하는 경량 PDF 파싱 도구입니다","es":"pdf-reader es una herramienta ligera que extrae texto de archivos PDF y se ejecuta en contenedores para mejorar la seguridad","fr":"pdf-reader est un outil léger qui extrait du texte de fichiers PDF et s''exécute dans des conteneurs pour améliorer la sécurité","de":"pdf-reader ist ein leichtes Tool, das Text aus PDF-Dateien extrahiert und in Containern ausgeführt wird, um die Sicherheit zu verbessern","pt":"O pdf-reader é uma ferramenta leve para extrair texto de PDFs, com suporte a layouts e metadados, que roda em contêineres para garantir a segurança","ru":"pdf-reader - это легкий инструмент для извлечения текста из PDF, с поддержкой макетов и метаданных, который работает в контейнерах для обеспечения безопасности, используя ИИ Агенты","ar":"pdf-reader هو أداة خفيفة لاستخراج النص من ملفات PDF، مع دعم للتنسيقات والميتادات، تعمل في حاويات لضمان الأمان"},"seo":{"title":{"en":"pdf-reader: Extract Text from PDFs for AI Agents | AI Age...","zh":"PDF Reader Setup Guide: 基于容器的安全轻量级解决方案","ja":"PDF Reader の設定方法: セキュアで軽量なコンテナベースの代替","ko":"PDF Reader 설정 가이드: 보안이 강화된 경량 컨테이너 솔루션","es":"Guía de configuración de pdf-reader para desarrolladores","fr":"Guide de mise en route de pdf-reader pour les développeurs","de":"Einrichtungsleitfaden für pdf-reader-Entwickler","pt":"Guia de Configuração do pdf-reader: Extraia Texto de PDFs...","ru":"Настройка pdf-reader: Извлечение текста из PDF с помощью ...","ar":"دليل إعداد pdf-reader: استخراج النص من ملفات PDF بسهولة"},"description":{"en":"Unlock PDF data with pdf-reader, a lightweight OpenClaw alternative. Learn how to extract text, preserve layouts, and integrate with messaging apps.","zh":"了解如何使用 PDF Reader 从 PDF 中提取文本、保留布局并连接到流行的消息应用程序","ja":"PDF Reader を使用して PDF からテキストを抽出してみましょう。レイアウトを保存し、人気のメッセージアプリに接続します","ko":"PDF Reader를 사용하여 PDF에서 텍스트를 추출하고 레이아웃을 유지하며 인기 메시지 앱에 연결하는 방법을 알아보세요","es":"Aprende a utilizar pdf-reader, una alternativa ligera a OpenClaw que se ejecuta en contenedores para mejorar la seguridad","fr":"Découvrez comment utiliser pdf-reader, une alternative légère à OpenClaw qui s''exécute dans des conteneurs pour améliorer la sécurité","de":"Erfahren Sie, wie Sie pdf-reader verwenden, eine leichte Alternative zu OpenClaw, die in Containern ausgeführt wird, um die Sicherheit zu verbessern","pt":"Aprenda a usar o pdf-reader para extrair texto de PDFs de forma rápida e segura, com suporte a layouts e metadados","ru":"Узнайте, как использовать pdf-reader для извлечения текста из PDF с поддержкой макетов и метаданных, используя ИИ Агенты","ar":"تعلم كيفية استخدام pdf-reader لاستخراج النص من ملفات PDF بسرعة وأمان، مع دعم للتنسيقات والميتادات"},"definition":{"en":"pdf-reader is a lightweight AI agent skill that extracts text from PDF files, providing metadata and layout preservation capabilities.","zh":"PDF Reader 是一个基于容器的安全轻量级 PDF 解析工具","ja":"PDF Reader は、セキュアで軽量なコンテナベースの PDF 解析ツールです","ko":"PDF Reader는 보안이 강화된 경량 컨테이너 기반 PDF 파싱 도구입니다","es":"pdf-reader es una herramienta de lectura de PDF que se ejecuta en contenedores","fr":"pdf-reader est un outil de lecture de PDF qui s''exécute dans des conteneurs","de":"pdf-reader ist ein PDF-Lese-Tool, das in Containern ausgeführt wird","pt":"O pdf-reader é uma ferramenta de código aberto para extrair texto de PDFs","ru":"pdf-reader - это открытый инструмент для извлечения текста из PDF","ar":"pdf-reader هو أداة مفتوحة المصدر لاستخراج النص من ملفات PDF"},"features":{"en":["Extracts text from PDF files using the `extract` command","Preserves tables and columns with the `--layout` option","Downloads and extracts PDFs from URLs with the `fetch` command","Displays metadata and size information with the `info` command","Lists all PDFs in a directory tree with the `list` command"],"zh":["支持从 PDF 中提取文本","保留 PDF 布局和表格","连接到 WhatsApp、Telegram、Slack、Discord 和 Gmail","支持调度任务和内存管理","直接运行在 Anthropic 的 Agents SDK 上"],"ja":["PDF からテキストを抽出する機能","PDF レイアウトと表を保存する機能","WhatsApp、Telegram、Slack、Discord、Gmail への接続","スケジュールジョブとメモリ管理のサポート","Anthropic の Agents SDK での直接実行"],"ko":["PDF에서 텍스트를 추출하는 기능","PDF 레이아웃과 표를 유지하는 기능","WhatsApp, Telegram, Slack, Discord, Gmail에 연결","스케줄링 작업과 메모리 관리 지원","Anthropic의 Agents SDK에서 직접 실행"],"es":["Extracción de texto de archivos PDF","Preservación de tablas y columnas","Descarga y extracción de PDF desde URL","Visualización de metadatos y tamaño de archivo","Compatibilidad con WhatsApp, Telegram, Slack, Discord y Gmail"],"fr":["Extraction de texte de fichiers PDF","Préservation de tableaux et de colonnes","Téléchargement et extraction de PDF à partir d''URL","Affichage de métadonnées et de taille de fichier","Compatibilité avec WhatsApp, Telegram, Slack, Discord et Gmail"],"de":["Textextraktion aus PDF-Dateien","Erhaltung von Tabellen und Spalten","Download und Extraktion von PDF von URL","Anzeige von Metadaten und Dateigröße","Kompatibilität mit WhatsApp, Telegram, Slack, Discord und Gmail"],"pt":["Extração de texto de PDFs com preservação de layouts","Suporte a metadados e informações de tamanho","Compatibilidade com contêineres para garantir a segurança","Integração com aplicativos de mensagens como WhatsApp e Telegram","Comandos CLI para extração e manipulação de PDFs"],"ru":["Извлечение текста из PDF с сохранением макетов","Поддержка метаданных и информации о размере","Совместимость с контейнерами для обеспечения безопасности, используя ИИ Агенты","Интеграция с приложениями для обмена сообщениями, такими как WhatsApp и Telegram","Команды CLI для извлечения и манипуляции PDF"],"ar":["استخراج النص من ملفات PDF مع الحفاظ على التنسيقات","دعم الميتادات والمعلومات عن الحجم","التعاون مع الحاويات لضمان الأمان","التكامل مع تطبيقات المراسلة مثل WhatsApp وTelegram","أوامر CLI لاستخراج وتنفيذ ملفات PDF"]},"keywords":{"en":["how to use pdf-reader","pdf-reader alternative to OpenClaw","pdf-reader extract text from PDF","pdf-reader setup guide for AI agents","pdf-reader vs OpenClaw","pdf-reader install for WhatsApp integration","what is pdf-reader","pdf-reader for Telegram bots","pdf-reader SDK documentation"],"zh":["PDF Reader","AIエージェント","PDF 解析","容器安全","轻量级解决方案","消息应用程序接口","Anthropic Agents SDK"],"ja":["PDF Reader","AIエージェント","PDF 解析","コンテナセキュリティ","軽量な解決策","メッセージアプリケーションインターフェース","Anthropic Agents SDK"],"ko":["PDF Reader","AI 에이전트","PDF 파싱","컨테이너 보안","경량 솔루션","메시지 애플리케이션 인터페이스","Anthropic Agents SDK"],"es":["pdf-reader","lectura de pdf","extracción de texto","seguridad en contenedores","alternativa a OpenClaw","desarrollo de aplicaciones","herramientas de AI","agentes de AI","integración con WhatsApp","integración con Telegram"],"fr":["pdf-reader","lecture de pdf","extraction de texte","sécurité dans les conteneurs","alternative à OpenClaw","développement d''applications","outils d''IA","agents d''IA","intégration avec WhatsApp","intégration avec Telegram"],"de":["pdf-reader","PDF-Lese-Tool","Textextraktion","Sicherheit in Containern","Alternative zu OpenClaw","Anwendungsentwicklung","AI-Tools","AI-Agents","Integration mit WhatsApp","Integration mit Telegram"],"pt":["pdf-reader","extração de texto de PDF","ferramenta de código aberto","contêineres de segurança","aplicativos de mensagens","comandos CLI","metadados de PDF","layout de PDF"],"ru":["pdf-reader","извлечение текста из PDF","открытый инструмент","контейнеры безопасности, ИИ Агенты","приложения для обмена сообщениями","команды CLI","метаданные PDF","макет PDF"],"ar":["pdf-reader","استخراج النص من ملفات PDF","أداة مفتوحة المصدر","حاويات الأمان","تطبيقات المراسلة","أوامر CLI","ميتادات PDF","تنسيق PDF"]}},"owner":"qwibitai","repo":"nanoclaw","repoPath":"qwibitai/nanoclaw","stars":19919,"forks":3256,"updatedAt":"2026-03-07T12:39:29Z","topics":["ai-agents","ai-assistant","claude-code","claude-skills","openclaw"],"category":"community","skillMd":{"name":"pdf-reader","description":"Read and extract text from PDF files — documents, reports, contracts, spreadsheets. Use whenever you need to read PDF content, not just when explicitly asked. Handles local files, URLs, and WhatsApp attachments.","bodyPreview":"# PDF Reader\n\n## Quick start\n\n```bash\npdf-reader extract report.pdf              # Extract all text\npdf-reader extract report.pdf --layout     # Preserve tables/columns\npdf-reader fetch https://example.com/doc.pdf  # Download and extract\npdf-reader info report.pdf                 # Show metadata + size\npdf-reader list                            # List all PDFs in directory tree\n```\n\n## Commands\n\n### extract — Extract text from PDF\n\n```bash\npdf-reader extract <file>                        # Full","body":"# PDF Reader\n\n## Quick start\n\n```bash\npdf-reader extract report.pdf              # Extract all text\npdf-reader extract report.pdf --layout     # Preserve tables/columns\npdf-reader fetch https://example.com/doc.pdf  # Download and extract\npdf-reader info report.pdf                 # Show metadata + size\npdf-reader list                            # List all PDFs in directory tree\n```\n\n## Commands\n\n### extract — Extract text from PDF\n\n```bash\npdf-reader extract <file>                        # Full text to stdout\npdf-reader extract <file> --layout               # Preserve layout (tables, columns)\npdf-reader extract <file> --pages 1-5            # Pages 1 through 5\npdf-reader extract <file> --pages 3-3            # Single page (page 3)\npdf-reader extract <file> --layout --pages 2-10  # Layout + page range\n```\n\nOptions:\n- `--layout` — Maintains spatial positioning. Essential for tables, spreadsheets, multi-column docs.\n- `--pages N-M` — Extract only pages N through M (1-based, inclusive).\n\n### fetch — Download and extract PDF from URL\n\n```bash\npdf-reader fetch <url>                    # Download, verify, extract with layout\npdf-reader fetch <url> report.pdf         # Also save a local copy\n```\n\nDownloads the PDF, verifies it has a valid `%PDF` header, then extracts text with layout preservation. Temporary files are cleaned up automatically.\n\n### info — PDF metadata and file size\n\n```bash\npdf-reader info <file>\n```\n\nShows title, author, page count, page size, PDF version, and file size on disk.\n\n### list — Find all PDFs in directory tree\n\n```bash\npdf-reader list\n```\n\nRecursively lists all `.pdf` files with page count and file size.\n\n## WhatsApp PDF attachments\n\nWhen a user sends a PDF on WhatsApp, it is automatically saved to the `attachments/` directory. The message will include a path hint like:\n\n> [PDF attached: attachments/document.pdf]\n\nTo read the attached PDF:\n\n```bash\npdf-reader extract attachments/document.pdf --layout\n```\n\n## Example workflows\n\n### Read a contract and summarize key terms\n\n```bash\npdf-reader info attachments/contract.pdf\npdf-reader extract attachments/contract.pdf --layout\n```\n\n### Extract specific pages from a long report\n\n```bash\npdf-reader info report.pdf                    # Check total pages\npdf-reader extract report.pdf --pages 1-3     # Executive summary\npdf-reader extract report.pdf --pages 15-20   # Financial tables\n```\n\n### Fetch and analyze a public document\n\n```bash\npdf-reader fetch https://example.com/annual-report.pdf report.pdf\npdf-reader info report.pdf\n```\n"},"lastSynced":"2026-03-07T12:47:49.563Z","agentAnalysis":{"suitability":{"en":"Ideal for Document Analysis Agents requiring precise text extraction from PDFs with layout preservation.","zh":"适用于需要从PDF中提取精确文本且保留布局的文档分析代理。","ja":"PDFからテキストを正確に抽出してレイアウトを保持する必要があるドキュメント分析エージェントに最適です。","ko":"PDF에서 레이아웃을 유지하면서 정확한 텍스트 추출이 필요한 문서 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Documentos que requieren extracción de texto precisa de PDF con preservación de diseño.","fr":"Idéal pour les Agents d''Analyse de Documents nécessitant une extraction de texte précise de PDF avec préservation de la mise en page.","de":"Ideal für Dokumentenanalyse-Agents, die eine präzise Textextraktion aus PDFs mit Layouterhaltung erfordern.","pt":"Ideal para Agentes de Análise de Documentos que exigem extração de texto precisa de PDFs com preservação de layout.","ru":"Идеально подходит для агентов анализа документов, требующих точной экстракции текста из PDF с сохранением макета.","ar":"مثالي لعميل تحليل الوثائق الذي يتطلب استخراج نص دقيق من ملفات PDF مع الحفاظ على تخطيط"},"recommendation":{"en":"Empowers agents to extract text from PDFs while preserving tables and columns, and integrates with messaging apps like WhatsApp and Telegram, utilizing protocols like HTTPS for seamless document fetching and analysis.","zh":"使得代理能够从PDF中提取文本同时保留表格和列，并与WhatsApp和Telegram等消息应用集成，利用HTTPS等协议实现无缝的文档获取和分析。","ja":"エージェントがPDFからテキストを抽出する同時に表と列を保持し、WhatsAppやTelegramなどのメッセージングアプリと統合し、HTTPSなどのプロトコルを使用してドキュメントの取得と分析をシームレスに行うことができます。","ko":"에이전트가 PDF에서 텍스트를 추출하는 동시에 표와 열을 유지하고 WhatsApp 및 Telegram과 같은 메시징 앱과 통합하여 HTTPS와 같은 프로토콜을 사용하여 문서 가져오기 및 분석을 무중단으로 수행할 수 있습니다.","es":"Habilita a los agentes a extraer texto de PDF mientras se preservan tablas y columnas, e integra con aplicaciones de mensajería como WhatsApp y Telegram, utilizando protocolos como HTTPS para una extracción y análisis de documentos sin problemas.","fr":"Permet aux agents d''extraire du texte à partir de PDF tout en préservant les tableaux et les colonnes, et s''intègre avec des applications de messagerie comme WhatsApp et Telegram, en utilisant des protocoles comme HTTPS pour une récupération et une analyse de documents sans problème.","de":"Ermöglicht es Agents, Text aus PDFs zu extrahieren, während Tabellen und Spalten erhalten bleiben, und integriert mit Messaging-Apps wie WhatsApp und Telegram, unter Verwendung von Protokollen wie HTTPS für eine nahtlose Dokumentenabfrage und -analyse.","pt":"Habilita os agentes a extrair texto de PDFs preservando tabelas e colunas, e se integra com aplicativos de mensagens como WhatsApp e Telegram, utilizando protocolos como HTTPS para busca e análise de documentos sem interrupção.","ru":"Наделяет агентов возможностью извлекать текст из PDF, сохраняя таблицы и столбцы, и интегрируется с приложениями для обмена сообщениями, такими как WhatsApp и Telegram, используя протоколы, такие как HTTPS, для бесшовной загрузки и анализа документов.","ar":"يمنح الوكلاء khảية استخراج النص من ملفات PDF مع الحفاظ على الجداول والأعمدة، ويتكامل مع تطبيقات الرسائل مثل WhatsApp و Telegram، باستخدام بروتوكولات مثل HTTPS لاسترجاع وتحليل المستندات دون انقطاع"},"useCases":{"en":["Extracting financial reports from PDFs","Preserving table structures in scientific articles","Fetching and analyzing PDF documents from remote URLs"],"zh":["从PDF中提取财务报告","在科学文章中保留表格结构","从远程URL获取和分析PDF文档"],"ja":["PDFから財務報告を抽出する","科学記事で表構造を保持する","リモートURLからPDFドキュメントを取得して分析する"],"ko":["PDF에서 재무 보고서 추출","과학 논문에서 표 구조 유지","원격 URL에서 PDF 문서 가져오기 및 분석"],"es":["Extracción de informes financieros de PDF","Preservación de estructuras de tabla en artículos científicos","Recuperación y análisis de documentos PDF desde URLs remotas"],"fr":["Extraction de rapports financiers à partir de PDF","Préservation de structures de tableaux dans les articles scientifiques","Récupération et analyse de documents PDF à partir d''URL distantes"],"de":["Extraktion von Finanzberichten aus PDF","Erhalt von Tabellenstrukturen in wissenschaftlichen Artikeln","Abruf und Analyse von PDF-Dokumenten von Remote-URLs"],"pt":["Extração de relatórios financeiros de PDFs","Preservação de estruturas de tabelas em artigos científicos","Recuperação e análise de documentos PDF de URLs remotos"],"ru":["Извлечение финансовых отчетов из PDF","Сохранение структуры таблиц в научных статьях","Получение и анализ документов PDF из удаленных URL"],"ar":["استخراج التقارير المالية من ملفات PDF","الحفاظ على هيكل الجداول في المقالات العلمية","استرجاع وتحليل مستندات PDF من عناوين URL عن بعد"]},"limitations":{"en":["Requires filesystem access for local PDF processing","Dependent on messaging app APIs for integration"],"zh":["需要文件系统访问权限以进行本地PDF处理","依赖于消息应用API以实现集成"],"ja":["ローカルPDF処理のためにファイルシステムへのアクセスが必要","統合のためにメッセージングアプリのAPIに依存する"],"ko":["로컬 PDF 처리를 위해 파일 시스템 액세스가 필요","통합을 위해 메시징 앱 API에 의존"],"es":["Requiere acceso al sistema de archivos para el procesamiento local de PDF","Dependiente de las APIs de aplicaciones de mensajería para la integración"],"fr":["Nécessite un accès au système de fichiers pour le traitement local de PDF","Dépendant des API d''applications de messagerie pour l''intégration"],"de":["Benötigt Dateisystemzugriff für lokale PDF-Verarbeitung","Abhängig von Messaging-App-APIs für die Integration"],"pt":["Exige acesso ao sistema de arquivos para processamento local de PDFs","Depende das APIs de aplicativos de mensagens para integração"],"ru":["Требует доступа к файловой системе для локальной обработки PDF","Зависит от API приложений для обмена сообщениями для интеграции"],"ar":["يتطلب الوصول إلى نظام الملفات لمعالجة ملفات PDF محليًا","يعتمد على واجهات برمجة التطبيقات لتطبيقات الرسائل للاستدماج"]},"version":4},"contentHash":"0046569626c967941f095c38b030951a7fc0523a3c66070f72229c39d93867f9","qualityScore":43}');
