INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('qwibitai/nanoclaw/pdf-reader', 'pdf-reader', 'qwibitai', 'nanoclaw', 'community', 'pdf-reader qwibitai nanoclaw community ai-agents ai-assistant claude-code claude-skills openclaw The pdf-reader skill extracts text from PDFs, preserving tables and columns, and integrates with messaging apps like WhatsApp and Telegram, benefiting AI agent developers. PDF Reader 是一个轻量级的 PDF 解析工具，支持从 PDF 中提取文本、保留布局和连接到流行的消息应用程序 PDF Reader は、PDF からテキストを抽出し、レイアウトを保存し、人気のメッセージアプリに接続する軽量な PDF 解析ツールです PDF Reader는 PDF에서 텍스트를 추출하고 레이아웃을 유지하며 인기 메시지 앱에 연결하는 경량 PDF 파싱 도구입니다 pdf-reader es una herramienta ligera que extrae texto de archivos PDF y se ejecuta en contenedores para mejorar la seguridad pdf-reader est un outil léger qui extrait du texte de fichiers PDF et s''exécute dans des conteneurs pour améliorer la sécurité pdf-reader ist ein leichtes Tool, das Text aus PDF-Dateien extrahiert und in Containern ausgeführt wird, um die Sicherheit zu verbessern O pdf-reader é uma ferramenta leve para extrair texto de PDFs, com suporte a layouts e metadados, que roda em contêineres para garantir a segurança pdf-reader - это легкий инструмент для извлечения текста из PDF, с поддержкой макетов и метаданных, который работает в контейнерах для обеспечения безопасности, используя ИИ Агенты pdf-reader هو أداة خفيفة لاستخراج النص من ملفات PDF، مع دعم للتنسيقات والميتادات، تعمل في حاويات لضمان الأمان how to use pdf-reader pdf-reader alternative to OpenClaw pdf-reader extract text from PDF pdf-reader setup guide for AI agents pdf-reader vs OpenClaw pdf-reader install for WhatsApp integration what is pdf-reader pdf-reader for Telegram bots pdf-reader SDK documentation PDF Reader AIエージェント PDF 解析 容器安全 轻量级解决方案 消息应用程序接口 Anthropic Agents SDK Extracts text from PDF files using the `extract` command Preserves tables and columns with the `--layout` option Downloads and extracts PDFs from URLs with the `fetch` command Displays metadata and size information with the `info` command Lists all PDFs in a directory tree with the `list` command pdf-reader is a lightweight AI agent skill that extracts text from PDF files, providing metadata and layout preservation capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('whtoo/How_to_implment_PL_in_Antlr4/vm-dev', 'community', 'whtoo', 'How_to_implment_PL_in_Antlr4', 'whtoo/How_to_implment_PL_in_Antlr4', 'vm-dev', 0, 0, 43, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:05.142Z', '26604f44adb1d109d674e50c1270fb12ea4c97036cc6667930bdb7572f376804', '{"id":"whtoo/How_to_implment_PL_in_Antlr4/vm-dev","name":"vm-dev","description":{"en":"The vm-dev skill enables developers to create a virtual machine with core capabilities such as bytecode execution, instruction sets, and memory management. It benefits developers looking to implement custom programming languages.","zh":"vm-dev 是一个虚拟机开发的技能，涵盖字节码设计、栈式虚拟机和寄存器虚拟机等核心能力","ja":"vm-dev は仮想マシン開発のスキルで、バイトコード設計、スタックベースの仮想マシン、レジスタベースの仮想マシンなどのコア機能を含みます","ko":"vm-dev는 가상머신 개발의 기술로 바이트코드 설계, 스택 기반 가상머신, 레지스터 기반 가상머신 등의 핵심 기능을 포함합니다","es":"vm-dev es un entorno de desarrollo de lenguajes de programación que incluye bytecode, pilas y registros","fr":"vm-dev est un environnement de développement de langages de programmation qui comprend du bytecode, des piles et des enregistreurs","de":"vm-dev ist eine Entwicklungsumgebung für Programmiersprachen, die Bytecode, Stack und Register umfasst","pt":"vm-dev é uma habilidade de desenvolvimento de máquina virtual que inclui design de bytecode, gerenciamento de memória e execução de instruções","ru":"vm-dev - это навык разработки виртуальных машин, который включает проектирование байтового кода, управление памятью и выполнение инструкций","ar":"vm-dev هو مهارة لتطوير آلة افتراضية تشمل تصميم بايت كود وإدارة الذاكرة وتنفيذ الإرشادات"},"seo":{"title":{"en":"vm-dev: Virtual Machine Development Setup Guide | AI Agen...","zh":"vm-dev 虚拟机开发设置指南","ja":"vm-dev による仮想マシン開発ベストプラクティス","ko":"vm-dev 가상머신 개발 환경설정 가이드","es":"Guía de configuración de vm-dev para desarrolladores","fr":"Guide de mise en place de vm-dev pour les développeurs","de":"Einrichtungsleitfaden für vm-dev-Entwickler","pt":"Guia de Configuração vm-dev: Desenvolvimento de Máquina V...","ru":"ИИ Агенты: Руководство по Настройке vm-dev для Разработки...","ar":"دليل تثبيت vm-dev: تطوير آلة افتراضية مع أدوات ИИ"},"description":{"en":"Discover how to implement a virtual machine with vm-dev, featuring bytecode design, stack and register-based architectures, and more. Get started with this c...","zh":"了解 vm-dev 虚拟机开发的核心能力，包括字节码设计、栈式虚拟机和寄存器虚拟机","ja":"vm-dev による仮想マシン開発のコア機能を学ぶ：バイトコード設計、スタックベースの仮想マシン、レジスタベースの仮想マシン","ko":"vm-dev 가상머신 개발의 핵심 기능을 익히세요: 바이트코드 설계, 스택 기반 가상머신, 레지스터 기반 가상머신","es":"Aprende a implementar vm-dev con capacidades de bytecode, pilas y registros para desarrollar lenguajes de programación","fr":"Découvrez comment mettre en œuvre vm-dev avec des fonctionnalités de bytecode, de piles et d''enregistreurs pour développer des langages de programmation","de":"Erfahren Sie, wie Sie vm-dev mit Bytecode-, Stack- und Registerfunktionen implementieren, um Programmiersprachen zu entwickeln","pt":"Aprenda a configurar e desenvolver máquinas virtuais com vm-dev, incluindo design de bytecode e gerenciamento de memória","ru":"Узнайте, как настроить и разработать виртуальные машины с помощью vm-dev, включая проектирование байтового кода и управление памятью","ar":"تعلم كيفية تثبيت وتطوير آلات افتراضية مع vm-dev، بما في ذلك تصميم بايت كود وإدارة الذاكرة"},"definition":{"en":"vm-dev is a virtual machine development skill that provides a comprehensive framework for designing and implementing custom programming languages, including bytecode definition and execution.","zh":"vm-dev 是一个虚拟机开发的技能，用于设计和实现虚拟机的核心能力","ja":"vm-dev は仮想マシン開発のスキルで、仮想マシンのコア機能を設計および実装するために使用されます","ko":"vm-dev는 가상머신 개발의 기술로 가상머신의 핵심 기능을 설계 및 구현하는 데 사용됩니다","es":"vm-dev es un entorno de desarrollo de lenguajes de programación que utiliza bytecode y pilas para la ejecución de código","fr":"vm-dev est un environnement de développement de langages de programmation qui utilise du bytecode et des piles pour l''exécution de code","de":"vm-dev ist eine Entwicklungsumgebung für Programmiersprachen, die Bytecode und Stack für die Codeausführung verwendet","pt":"vm-dev é uma habilidade de desenvolvimento de máquina virtual que permite criar máquinas virtuais personalizadas","ru":"vm-dev - это навык разработки виртуальных машин, который позволяет создавать пользовательские виртуальные машины","ar":"vm-dev هو مهارة لتطوير آلة افتراضية تمكن من إنشاء آلات افتراضية مخصصة"},"features":{"en":["Defines bytecode instructions such as IADD, ISUB, IMUL, and IDIV using BytecodeDefinition.java","Implements a stack-based virtual machine with a Last-In-First-Out (LIFO) operand stack","Supports register-based virtual machine architecture with core components like CymbolRegisterVM.java","Manages memory using stack frames with local variables, operand stacks, and return addresses","Executes instructions using a custom-designed instruction set"],"zh":["字节码设计：定义和实现字节码","栈式虚拟机：实现栈帧和操作数栈","寄存器虚拟机：实现寄存器和指令集","ANTLR 非官方参考","Cyson 语言的实现"],"ja":["バイトコード設計：バイトコードの定義と実装","スタックベースの仮想マシン：スタックフレームとオペランドスタックの実装","レジスタベースの仮想マシン：レジスタと命令セットの実装","ANTLR 非公式リファレンス","Cyson 言語の実装"],"ko":["바이트코드 설계: 바이트코드의 정의 및 구현","스택 기반 가상머신: 스택 프레임 및 오퍼랜드 스택의 구현","레지스터 기반 가상머신: 레지스터 및 명령어 세트의 구현","ANTLR 비공식 참조","Cyson 언어의 구현"],"es":["Diseño de bytecode con instrucciones como IADD, ISUB, IMUL, IDIV","Implementación de pilas y registros para la ejecución de código","Gestión de memoria y recolección de basura","Compatibilidad con lenguajes de programación como Cymbol"],"fr":["Conception de bytecode avec des instructions telles que IADD, ISUB, IMUL, IDIV","Mise en œuvre de piles et d''enregistreurs pour l''exécution de code","Gestion de la mémoire et récupération de garbage","Compatibilité avec des langages de programmation tels que Cymbol"],"de":["Bytecode-Design mit Anweisungen wie IADD, ISUB, IMUL, IDIV","Implementierung von Stack und Registern für die Codeausführung","Speicherverwaltung und Garbage Collection","Kompatibilität mit Programmiersprachen wie Cymbol"],"pt":["Design de bytecode personalizado","Gerenciamento de memória eficiente","Execução de instruções de máquina virtual","Suporte a registros e pilhas","Implementação de garbage collection"],"ru":["Проектирование байтового кода на заказ","Эффективное управление памятью","Выполнение инструкций виртуальной машины","Поддержка регистров и стеков","Реализация сборки мусора"],"ar":["تصميم بايت كود مخصص","إدارة ذاكرة فعالة","تنفيذ إرشادات آلة افتراضية","دعم السجلات والكومات","تنفيذ جمع القمامة"]},"keywords":{"en":["how to use vm-dev","vm-dev alternative","vm-dev setup guide","what is vm-dev","vm-dev vs antlr","vm-dev install","virtual machine development","custom programming language implementation","bytecode design"],"zh":["vm-dev","虚拟机开发","字节码设计","栈式虚拟机","寄存器虚拟机","ANTLR","Cyson 语言","AIエージェント","虚拟机实现"],"ja":["vm-dev","仮想マシン開発","バイトコード設計","スタックベースの仮想マシン","レジスタベースの仮想マシン","ANTLR","Cyson 言語","AIエージェント","仮想マシン実装"],"ko":["vm-dev","가상머신 개발","바이트코드 설계","스택 기반 가상머신","레지스터 기반 가상머신","ANTLR","Cyson 언어","AI 에이전트","가상머신 구현"],"es":["vm-dev","desarrollo de lenguajes de programación","bytecode","pilas","registros","gestión de memoria","recolección de basura","Cymbol"],"fr":["vm-dev","développement de langages de programmation","bytecode","piles","enregistreurs","gestion de la mémoire","récupération de garbage","Cymbol"],"de":["vm-dev","Entwicklung von Programmiersprachen","Bytecode","Stack","Register","Speicherverwaltung","Garbage Collection","Cymbol"],"pt":["desenvolvimento de máquina virtual","vm-dev","bytecode","gerenciamento de memória","execução de instruções","registros","pilhas","garbage collection"],"ru":["разработка виртуальных машин","vm-dev","байтовый код","управление памятью","выполнение инструкций","регистры","стеки","сборка мусора"],"ar":["تطوير آلة افتراضية","vm-dev","بايت كود","إدارة الذاكرة","تنفيذ الإرشادات","السجلات","الكومات","جمع القمامة"]}},"owner":"whtoo","repo":"How_to_implment_PL_in_Antlr4","repoPath":"whtoo/How_to_implment_PL_in_Antlr4","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"vm-dev","description":"虚拟机开发专家，专注于字节码、指令、栈帧、内存管理和垃圾回收。","version":"v1.0","tags":["vm","bytecode","execution","stack","memory","gc"],"bodyPreview":"# 虚拟机开发\n\n## 🎯 垂直职责\n**单一职责**: 虚拟机实现 - 字节码执行、指令集、栈帧、内存管理、垃圾回收\n\n## 📦 核心能力\n\n### 1. 字节码设计 (EP13-EP15)\n- **定义**: `BytecodeDefinition.java`\n- **指令集**: IADD, ISUB, IMUL, IDIV, LOAD, STORE, CALL, RET, JMP\n- **操作数栈**: 后进先出 (LIFO)\n\n### 2. 栈式虚拟机 (EP18)\n- **位置**: `ep18/src/main/java/org/teachfx/antlr4/ep18/stackvm/`\n- **核心**: `CymbolStackVM.java`\n- **栈帧**: `StackFrame.java` (局部变量 + 操作数栈 + 返回地址)\n\n### 3. 寄存器虚拟机 (EP18R)\n- **位置**: `ep18r/src/main/java/org/teachfx/antlr4/ep18r/regvm/`\n- **核心**: `CymbolRegisterV","body":"# 虚拟机开发\n\n## 🎯 垂直职责\n**单一职责**: 虚拟机实现 - 字节码执行、指令集、栈帧、内存管理、垃圾回收\n\n## 📦 核心能力\n\n### 1. 字节码设计 (EP13-EP15)\n- **定义**: `BytecodeDefinition.java`\n- **指令集**: IADD, ISUB, IMUL, IDIV, LOAD, STORE, CALL, RET, JMP\n- **操作数栈**: 后进先出 (LIFO)\n\n### 2. 栈式虚拟机 (EP18)\n- **位置**: `ep18/src/main/java/org/teachfx/antlr4/ep18/stackvm/`\n- **核心**: `CymbolStackVM.java`\n- **栈帧**: `StackFrame.java` (局部变量 + 操作数栈 + 返回地址)\n\n### 3. 寄存器虚拟机 (EP18R)\n- **位置**: `ep18r/src/main/java/org/teachfx/antlr4/ep18r/regvm/`\n- **核心**: `CymbolRegisterVM.java`\n- **寄存器分配**: 基于ABI约定的寄存器使用\n\n### 4. 内存管理 (EP18/EP18R)\n- **堆内存**: `HeapMemory.java`\n- **GC**: 标记-清除算法\n- **对象布局**: 类型信息 + 字段数据\n\n## 🔗 关系图\n→ **ep-navigator** (识别EP范围)\n→ **compiler-dev** (IR → 字节码)\n\n## 🚀 快速开始\n\n### 添加新指令\n```bash\n# 1. 定义操作码\nvim ep18/src/main/java/.../BytecodeDefinition.java\n// enum OpCode { ..., NEW_OP(0x20); }\n\n# 2. 实现指令类\nvim ep18/src/main/java/.../instruction/NewOpInstruction.java\npublic class NewOpInstruction extends Instruction {\n    @Override\n    public void execute(ExecutionContext ctx) {\n        // 实现逻辑\n    }\n}\n\n# 3. 注册指令\nvim ep18/src/main/java/.../InstructionFactory.java\n\n# 4. 测试\nmvn test -pl ep18 -Dtest=\"*NewOpInstruction*\"\n```\n\n### 实现垃圾回收\n```bash\n# 1. 定义对象头\nclass ObjectHeader {\n    Type type;\n    boolean marked;\n    int size;\n}\n\n# 2. 实现标记阶段\nvoid mark(VarSlot root) {\n    Object obj = heap.get(root);\n    if (obj != null && !obj.header.marked) {\n        obj.header.marked = true;\n        for (VarSlot field : obj.getReferences()) {\n            mark(field);\n        }\n    }\n}\n\n# 3. 实现清除阶段\nvoid sweep() {\n    heap.removeIf(obj -> !obj.header.marked);\n}\n```\n\n## 📊 栈帧结构\n\n```\n┌─────────────────────────────────┐\n│     返回地址 (Return Address)    │\n├─────────────────────────────────┤\n│     局部变量区 (Locals)          │\n│     [0] [1] [2] [3] ...         │\n├─────────────────────────────────┤\n│     操作数栈 (Operand Stack)     │\n│     [...] [...] [...]           │\n└─────────────────────────────────┘\n```\n\n## 🛠️ 常用命令\n\n```bash\n# 虚拟机相关\nmvn compile -pl ep18                         # 编译EP18\nmvn test -pl ep18 -Dtest=\"*Instruction*\"     # 测试指令\nmvn test -pl ep18 -Dtest=\"*VM*\"              # 测试VM\nmvn test -pl ep18 -Dtest=\"*GC*\"              # 测试GC\n\n# 运行程序\nmvn exec:java -pl ep18 -Dexec.args=\"program.cx\"\n```\n\n## 📐 指令格式速查\n\n| 指令 | 操作码 | 操作数 | 栈效果 | 描述 |\n|------|--------|--------|--------|------|\n| ICONST | 0x01 | value | → value | 加载整数常量 |\n| IADD | 0x10 | - | a,b → a+b | 整数加法 |\n| ISUB | 0x11 | - | a,b → a-b | 整数减法 |\n| LOAD | 0x20 | index | → value | 加载局部变量 |\n| STORE | 0x21 | index | value → | 存储局部变量 |\n| CALL | 0x30 | addr | args... → | 调用函数 |\n| RET | 0x31 | - | value → | 返回函数 |\n| JMP | 0x40 | offset | → | 无条件跳转 |\n| CONDJMP | 0x41 | offset | cond → | 条件跳转 |\n\n## ⚠️ 常见问题\n\n| 问题 | 原因 | 解决方案 |\n|------|------|----------|\n| 栈溢出 | 操作数栈超限 | 检查指令栈平衡 |\n| 栈下溢 | 弹出空栈 | 验证指令前置条件 |\n| 类型错误 | 操作数类型不匹配 | 添加类型检查 |\n| 内存泄漏 | GC未正确标记 | 检查根集完整性 |\n\n---\n*版本: v1.0 | 垂直职责: 虚拟机实现 | 2025-12-23*\n"},"lastSynced":"2026-03-08T02:01:05.142Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Model Agents requiring custom bytecode execution and instruction set implementation.","zh":"适用于需要自定义字节码执行和指令集实现的语言模型代理。","ja":"カスタムバイトコードの実行と命令セットの実装を必要とする言語モデルエージェントに最適。","ko":"자바 바이트코드 실행 및 명령어 집합 구현을 필요로 하는 언어 모델 에이전트에 적합합니다.","es":"Ideal para Agentes de Modelo de Lenguaje que requieren ejecución de bytecode personalizada e implementación de conjunto de instrucciones.","fr":"Idéal pour les agents de modèle de langage nécessitant une exécution de bytecode personnalisée et une implémentation de jeu d''instructions.","de":"Ideal für Language-Model-Agents, die eine benutzerdefinierte Bytecode-Ausführung und eine Implementierung des Befehlssatzes erfordern.","pt":"Ideal para Agentes de Modelo de Linguagem que exigem execução de bytecode personalizado e implementação de conjunto de instruções.","ru":"Идеально для Агентов Модели Языка, требующих пользовательской выполнения байт-кода и реализации набора инструкций.","ar":"مثالي لعميل نموذج اللغة الذي يتطلب تنفيذ بايت كود مخصص وتنفيذ مجموعة من الإرشادات."},"recommendation":{"en":"Empowers agents to create virtual machines with core capabilities such as bytecode execution, instruction sets, and memory management, utilizing Java-based implementations like BytecodeDefinition.java and CymbolStackVM.java.","zh":"赋予代理创建具有字节码执行、指令集和内存管理等核心能力的虚拟机的能力，利用基于Java的实现，如BytecodeDefinition.java和CymbolStackVM.java。","ja":"エージェントが、BytecodeDefinition.javaやCymbolStackVM.javaなどのJavaベースの実装を利用して、バイトコードの実行、命令セット、メモリ管理などのコア機能を持つ仮想マシンを作成できるようにします。","ko":"BytecodeDefinition.java 및 CymbolStackVM.java와 같은 Java 기반 구현을 사용하여 바이트코드 실행, 명령어 집합 및 메모리 관리와 같은 핵심 기능을 가진 가상 머신을 만들 수 있는 에이전트를 제공합니다.","es":"Permite a los agentes crear máquinas virtuales con capacidades básicas como ejecución de bytecode, conjuntos de instrucciones y gestión de memoria, utilizando implementaciones basadas en Java como BytecodeDefinition.java y CymbolStackVM.java.","fr":"Permet aux agents de créer des machines virtuelles avec des capacités de base telles que l''exécution de bytecode, les jeux d''instructions et la gestion de la mémoire, en utilisant des implementations basées sur Java comme BytecodeDefinition.java et CymbolStackVM.java.","de":"Ermöglicht es den Agents, virtuelle Maschinen mit grundlegenden Fähigkeiten wie Bytecode-Ausführung, Befehlssätzen und Speicherverwaltung zu erstellen, unter Verwendung von Java-basierten Implementierungen wie BytecodeDefinition.java und CymbolStackVM.java.","pt":"Habilita os agentes a criar máquinas virtuais com capacidades principais, como execução de bytecode, conjuntos de instruções e gerenciamento de memória, utilizando implementações baseadas em Java, como BytecodeDefinition.java e CymbolStackVM.java.","ru":"Наделяет агентов возможностью создавать виртуальные машины с основными возможностями, такими как выполнение байт-кода, наборы инструкций и управление памятью, используя реализации на основе Java, такие как BytecodeDefinition.java и CymbolStackVM.java.","ar":"تمكين الوكلاء من إنشاء أجهزة افتراضية مع القدرات الأساسية مثل تنفيذ بايت كود و مجموعات الإرشادات وإدارة الذاكرة، باستخدام التنفيذ القائم على Java مثل BytecodeDefinition.java و CymbolStackVM.java."},"useCases":{"en":["Implementing custom programming languages","Developing stack-based virtual machines","Designing instruction sets for specific use cases"],"zh":["实现自定义编程语言","开发基于堆栈的虚拟机","为特定用例设计指令集"],"ja":["カスタムプログラミング言語の実装","スタックベースの仮想マシンの開発","特定のユースケース向けの命令セットの設計"],"ko":["사용자 정의 프로그래밍 언어 구현","스택 기반 가상 머신 개발","특정 사용 사례를 위한 명령어 집합 설계"],"es":["Implementación de lenguajes de programación personalizados","Desarrollo de máquinas virtuales basadas en pilas","Diseño de conjuntos de instrucciones para casos de uso específicos"],"fr":["Mise en œuvre de langages de programmation personnalisés","Développement de machines virtuelles basées sur des piles","Conception de jeux d''instructions pour des cas d''utilisation spécifiques"],"de":["Implementierung von benutzerdefinierten Programmiersprachen","Entwicklung von stapelbasierten virtuellen Maschinen","Entwurf von Befehlssätzen für spezifische Anwendungsfälle"],"pt":["Implementação de linguagens de programação personalizadas","Desenvolvimento de máquinas virtuais baseadas em pilha","Projeto de conjuntos de instruções para casos de uso específicos"],"ru":["Реализация пользовательских языков программирования","Разработка виртуальных машин на основе стека","Проектирование наборов инструкций для конкретных случаев использования"],"ar":["تنفيذ لغات البرمجة المخصصة","تطوير أجهزة افتراضية قائمة على المكدس","تصميم مجموعات الإرشادات لケースات استخدام محددة"]},"limitations":{"en":["Requires Java development environment","Focuses on stack-based and register-based virtual machine architectures"],"zh":["需要Java开发环境","注重基于堆栈和寄存器的虚拟机架构"],"ja":["Java開発環境が必要","スタックベースとレジスタベースの仮想マシンアーキテクチャに焦点を当てている"],"ko":["Java 개발 환경이 필요합니다.","스택 기반 및 레지스터 기반 가상 머신 아키텍처에 중점을 둡니다."],"es":["Requiere un entorno de desarrollo Java","Se centra en arquitecturas de máquinas virtuales basadas en pilas y registros"],"fr":["Nécessite un environnement de développement Java","Se concentre sur les architectures de machines virtuelles basées sur des piles et des registres"],"de":["Benötigt eine Java-Entwicklungsumgebung","Konzentriert sich auf stapelbasierte und registerbasierte virtuelle Maschinen-Architekturen"],"pt":["Exige ambiente de desenvolvimento Java","Concentra-se em arquiteturas de máquina virtual baseadas em pilha e registradores"],"ru":["Требует среды разработки Java","Сосредоточен на архитектурах виртуальных машин на основе стека и регистров"],"ar":["يتطلب بيئة تطوير Java","يركز على هندسة أجهزة افتراضية قائمة على المكدس والسجلات"]},"version":4},"contentHash":"26604f44adb1d109d674e50c1270fb12ea4c97036cc6667930bdb7572f376804","qualityScore":43}');
