INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WeWriteApp/WeWrite/remotion-best-practices', 'remotion-best-practices', 'WeWriteApp', 'WeWrite', 'community', 'remotion-best-practices WeWriteApp WeWrite community remotion-best-practices provides domain-specific knowledge for Remotion development, covering 3D content, animations, and asset management. It benefits developers working with Remotion code. Remotion最佳实践提供了有关Three.js和React Three Fiber的详细指导，帮助开发者创建高质量的3D内容和动画 Remotionベストプラクティスでは、Three.jsとReact Three Fiberの詳細なガイドを提供し、開発者が高品質の3Dコンテンツとアニメーションを作成できるようにします Remotion最佳实践은 Three.js 및 React Three Fiber에 대한详细한 가이드를 제공하여 개발자가 고품질의 3D 콘텐츠와 애니메이션을 생성할 수 있도록합니다 Remotion es una herramienta para crear contenido 3D con Three.js y React Three Fiber. Nuestras mejores prácticas te ayudarán a aprovechar al máximo sus capacidades. Remotion est un outil pour créer du contenu 3D avec Three.js et React Three Fiber. Nos meilleures pratiques vous aideront à optimiser ses capacités. Remotion ist ein Tool für die Erstellung von 3D-Inhalten mit Three.js und React Three Fiber. Unsere Best-Practices helfen Ihnen, seine Fähigkeiten optimal zu nutzen. Remotion é uma ferramenta poderosa para criar conteúdo de vídeo personalizado. Aprenda as melhores práticas para trabalhar com Remotion Remotion - это мощный инструмент для создания персонализированного видеоконтента. Узнайте лучшие практики работы с Remotion Remotion هو أداة قوية لإنشاء محتوى فيديو مخصص. تعرف على أفضل الممارسات لاستخدام Remotion how to use remotion-best-practices remotion-best-practices tutorial remotion development best practices three.js remotion integration react three fiber remotion remotion-best-practices setup guide remotion-best-practices install remotion-best-practices alternative Remotion最佳实践 Three.js React Three Fiber 3D内容创建 动画技能 Remotion规则 AIエージェント Remotion代码 Provides detailed explanations and code examples for 3D content in Remotion using Three.js and React Three Fiber Offers fundamental animation skills for Remotion Supports importing images, videos, audio, and fonts into Remotion Includes rules for audio management in Remotion Covers best practices for Remotion development remotion-best-practices is a skill that provides guidelines and best practices for developing with Remotion, utilizing technologies like Three.js and React Three Fiber.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yanix2445/git-config-ultimate/git-expert-guidelines', 'community', 'yanix2445', 'git-config-ultimate', 'yanix2445/git-config-ultimate', 'git-expert-guidelines', 0, 0, 43, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:26.011Z', '6ea20fceededabeb3c278cf4e4a00c1c737cb03e0b3031cf68c1f62bcd304ab7', '{"id":"yanix2445/git-config-ultimate/git-expert-guidelines","name":"git-expert-guidelines","description":{"en":"The git-expert-guidelines skill provides standards for version control management, prioritizing security, workflow, recovery, and configuration for solo developers and AI agents.","zh":"Git Expert Guidelines 是一种配置 Git 的指南，提供安全高效的 Git 工作流，适用于开发者","ja":"Git Expert Guidelines は、AIエージェントのための Git の設定とセキュリティに関するガイドラインです","ko":"Git Expert Guidelines는 개발자를 위한 보안 및 최적화된 Git 워크플로우 설정 가이드입니다","es":"Configuración Git segura y optimizada para desarrolladores. Estándares de gestión de versiones para agents y desarrolladores","fr":"Configuration Git ultime pour développeurs solo. Standards de gestion de version pour agents et développeurs","de":"Sichere und optimale Git-Konfiguration für Entwickler. Gestion de version-Verfahren für Agents und Entwickler","pt":"O guia de configuração Git para desenvolvedores solo oferece diretrizes para uma gestão de versão segura e otimizada","ru":"Экспертные рекомендации по настройке Git для разработчиков обеспечивают безопасную и оптимизированную систему контроля версий","ar":"دليل إعداد جيت للطورين يقدم إرشادات لضبط نظام إدارة الإصدارات بشكل آمن ومثالي"},"seo":{"title":{"en":"git-expert-guidelines: Git Configuration Setup Guide for ...","zh":"Git Expert Guidelines 配置指南：安全高效的 Git 工作流","ja":"Git Expert Guidelines セットアップガイド：AIエージェントのための Git ベストプラクティス","ko":"Git Expert Guidelines 설정 가이드: 보안 및 최적화된 Git 워크플로우","es":"Guía de configuración Git para desarrolladores: Mejores p...","fr":"Guide d