INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yanix2445/git-config-ultimate/git-expert-guidelines', 'git-expert-guidelines', 'yanix2445', 'git-config-ultimate', 'community', 'git-expert-guidelines yanix2445 git-config-ultimate community The git-expert-guidelines skill provides standards for version control management, prioritizing security, workflow, recovery, and configuration for solo developers and AI agents. Git Expert Guidelines 是一种配置 Git 的指南，提供安全高效的 Git 工作流，适用于开发者 Git Expert Guidelines は、AIエージェントのための Git の設定とセキュリティに関するガイドラインです Git Expert Guidelines는 개발자를 위한 보안 및 최적화된 Git 워크플로우 설정 가이드입니다 Configuración Git segura y optimizada para desarrolladores. Estándares de gestión de versiones para agents y desarrolladores Configuration Git ultime pour développeurs solo. Standards de gestion de version pour agents et développeurs Sichere und optimale Git-Konfiguration für Entwickler. Gestion de version-Verfahren für Agents und Entwickler O guia de configuração Git para desenvolvedores solo oferece diretrizes para uma gestão de versão segura e otimizada Экспертные рекомендации по настройке Git для разработчиков обеспечивают безопасную и оптимизированную систему контроля версий دليل إعداد جيت للطورين يقدم إرشادات لضبط نظام إدارة الإصدارات بشكل آمن ومثالي git-expert-guidelines setup guide git configuration best practices how to use git-expert-guidelines git-expert-guidelines vs gitflow git-expert-guidelines install git security guidelines git workflow optimization git recovery techniques git configuration management Git Expert Guidelines Git 配置 安全高效的 Git 工作流 AI 工具 Git 最佳实践 配置 Git Git 优化 Prioritizes security with CRITICAL impact and `security-` prefix Optimizes workflow with HIGH impact and `workflow-` prefix Supports recovery with HIGH impact and `recovery-` prefix Configures Git with MEDIUM impact and `config-` prefix Provides quick reference for Git operations like commit, push, and checkout git-expert-guidelines is a set of expert guidelines for configuring and managing Git, focusing on security, workflow, and recovery best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blesstosam/trpc-fastify-starter/fastify-best-practices', 'community', 'blesstosam', 'trpc-fastify-starter', 'blesstosam/trpc-fastify-starter', 'fastify-best-practices', 0, 0, 43, '2026-03-08T01:57:15.341Z', '2026-03-08T02:03:28.767Z', 'a81c75ef8a1ed2db7537d8c4116a638453922a6b11fd121e4af2787135cc657f', '{"id":"blesstosam/trpc-fastify-starter/fastify-best-practices","name":"fastify-best-practices","description":{"en":"fastify-best-practices helps developers build efficient backend applications using Fastify. It provides guidance on architecture, patterns, and testing.","zh":"Fastify最佳实践指南，帮助开发者使用Fastify开发后端应用，包括插件、路由处理和测试","ja":"Fastifyのベストプラクティスセットアップガイド。Fastifyでバックエンドアプリケーションを開発する開発者向け","ko":"Fastify의 최고의 실무 지침 설정 가이드. Fastify로 백엔드 애플리케이션 개발을 하는 개발자를 위한","es":"Fastify es un framework de Node.js para desarrollar aplicaciones backend. Esta guía cubre las mejores prácticas para su uso.","fr":"Fastify est un framework Node.js pour développer des applications backend. Ce guide couvre les meilleures pratiques pour son utilisation.","de":"Fastify ist ein Node.js-Framework für die Entwicklung von Backend-Anwendungen. Diese Anleitung behandelt die besten Praktiken für seine Verwendung.","pt":"Desenvolva aplicações backend com Fastify, implementando plugins e manipuladores de rotas, e obtenha orientação sobre arquitetura e padrões","ru":"Разрабатывайте backend-приложения с помощью Fastify, реализуя плагины и обработчики маршрутов, и получайте рекомендации по архитектуре и шаблонам","ar":"تطوير التطبيقات الخلفية باستخدام Fastify، وتنفيذ البرامج المساعدة و معالجات المسارات، و الحصول على إرشادات حول الهندسة المعمارية و الأنماط"},"seo":{"title":{"en":"fastify-best-practices: Setup Guide for AI Agents","zh":"Fastify 最佳实践指南 - AIエージェント","ja":"Fastify ベストプラクティスセットアップガイド - AIエージェント","ko":"Fastify最佳實踐설정 가이드 - AI 에이전트","es":"Guía de configuración de Fastify: Mejores prácticas para ...","fr":"Guide de configuration de Fastify: Bonnes pratiques pour ...","de":"Fastify-Konfigurationsleitfaden: Best Practices für Entwi...","pt":"Fastify Best Practices: Guia de Configuração","ru":"Лучшие практики Fastify: Настройка и оптимизация","ar":"أفضل الممارسات ل Fastify: دليل الإعداد"},"description":{"en":"Unlock efficient backend development with fastify-best-practices. Learn how to implement plugins, route handlers, and validation. Get started now!","zh":"使用Fastify开发后端应用？了解Fastify最佳实践，包括插件、路由处理、类型脚本和测试","ja":"Fastifyでバックエンドアプリケーションを開発する？Fastifyのベストプラクティスを学び、プラグイン、ルーティングハンドラー、TypeScript、テストをマスターする","ko":"Fastify로 백엔드 애플리케이션 개발을 하는데 도움이 필요합니까? Fastify의 최고의 실무 지침을 배우고 플러그인, 라우팅 핸들러, TypeScript 및 테스트를 사용하세요","es":"Aprende a desarrollar aplicaciones backend con Fastify de manera efectiva, incluyendo la implementación de plugins y controladores de rutas","fr":"Découvrez comment développer des applications backend avec Fastify de manière efficace, y compris la mise en œuvre de plugins et de gestionnaires de routes","de":"Erfahren Sie, wie Sie Backend-Anwendungen mit Fastify effektiv entwickeln, einschließlich der Implementierung von Plugins und Routen-Handlern","pt":"Aprenda a desenvolver aplicações backend com Fastify, implementando plugins e manipuladores de rotas, e obtenha orientação sobre arquitetura e padrões","ru":"Изучите разработку backend-приложений с помощью Fastify, реализацию плагинов и обработчиков маршрутов, а также получите рекомендации по архитектуре и шаблонам","ar":"تعلم تطوير التطبيقات الخلفية باستخدام Fastify، وتنفيذ البرامج المساعدة و معالجات المسارات، و احصل على إرشادات حول الهندسة المعمارية و الأنماط"},"definition":{"en":"fastify-best-practices is a skill that provides guidelines for developing backend applications using Fastify, including plugin implementation and testing best practices.","zh":"Fastify最佳实践是指使用Fastify开发后端应用的最佳方法和技巧","ja":"Fastifyのベストプラクティスとは、Fastifyでバックエンドアプリケーションを開発