INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sunqb/ccsdk/Topic_Planning', 'Topic_Planning', 'sunqb', 'ccsdk', 'community', 'Topic_Planning sunqb ccsdk community Topic_Planning is a comprehensive content strategy system that understands user needs and recommends suitable planning scenarios. It benefits content creators and strategists by streamlining the planning process. Topic_Planning是选题策划系统的总入口，负责理解用户需求和识别适用的策划场景 トピックプランニングはAIエージェントの一部で、ユーザーのニーズを理解し、適切なシナリオを識別する 주제 계획은 주제 계획 시스템의 총 입구로, 사용자의 요구 사항을 이해하고 적합한 시나리오를 식별하는 역할을 담당합니다 Topic_Planning es un sistema de planificación de temas que ayuda a los desarrolladores a crear estrategias de contenido personalizadas Topic_Planning est un système de planification de sujets qui aide les développeurs à créer des stratégies de contenu personnalisées Topic_Planning ist ein Themenplanungssystem, das Entwicklern hilft, personalisierte Inhaltsstrategien zu erstellen O planejamento de tópicos é uma habilidade que permite criar conteúdos personalizados com base em necessidades específicas, utilizando técnicas de análise de cenários e recomendação de fluxos de habilidades Планирование тем - это навык, который позволяет создавать персонализированный контент на основе конкретных потребностей, используя методы анализа сценариев и рекомендации потоков навыков تخطيط الموضوعات هو مهارة تمكن من إنشاء محتوى مخصص بناءً على احتياجات محددة، باستخدام تقنيات تحليل السيناريوهات وتوصية بتدفقات المهارات how to use Topic_Planning Topic_Planning alternative what is Topic_Planning Topic_Planning setup guide Topic_Planning vs content strategy tools Topic_Planning install for AI agents Topic_Planning for content creators Topic_Planning best practices Topic_Planning for IP extension 选题策划系统 AI工具 策划场景识别 Skill流程路径推荐 快速启动选项 Topic_Planning Recognizes user demands and current status for personalized planning Identifies suitable planning scenarios, including new projects, IP extension, customization, and optimization Recommends Skill flow paths for efficient content planning Provides quick launch options for streamlined planning Supports various content types, including books, courses, columns, and IP content extension Topic_Planning is a systematic approach to identifying and planning content topics, utilizing AI to recognize user demands and recommend optimal planning paths.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('piotroq/adwokat-trzebnica-html-to-php-com/Scale Game', 'community', 'piotroq', 'adwokat-trzebnica-html-to-php-com', 'piotroq/adwokat-trzebnica-html-to-php-com', 'Scale Game', 0, 0, 43, '2026-03-08T01:57:15.475Z', '2026-03-08T02:09:45.362Z', '43373c54188b3bd9ba5eca74e57a53dfd3967ed65503996bcd16441e34cd15aa', '{"id":"piotroq/adwokat-trzebnica-html-to-php-com/Scale Game","name":"Scale Game","description":{"en":"Scale Game is a skill that tests approaches at extreme scales, revealing fundamental truths about algorithmic complexity, async requirements, and concurrency. It benefits developers who need to optimize their applications for large volumes, high speeds, and multiple users.","zh":"Scale Game是一种极限规模测试技术，通过测试极端情况下的算法复杂度和异步要求，帮助开发者优化应用性能","ja":"Scale Gameは極限スケールテスト技術であり、極端な状況でのアルゴリズムの複雑度と非同期の要件をテストし、開発者がアプリケーションのパフォーマンスを最適化するのに役立ちます","ko":"Scale Game은 극한 규모 테스트 기술로极端 상황下的 알고리즘 복잡도와 비동기 요구 사항을 테스트하여 개발자가 애플리케이션 성능을 최적화하는 데 도움을 줍니다","es":"Scale Game es una herramienta para probar la escalabilidad de aplicaciones, identificando limitaciones y optimizando el rendimiento.","fr":"Scale Game est un outil pour tester la scalabilité des applications, identifier les limitations et optimiser les performances.","de":"Scale Game ist ein Tool zum Testen der Skalierbarkeit von Anwendungen, um Einschränkungen zu identifizieren und die Leistung zu optimieren.","pt":"O Scale Game é uma ferramenta para testar escalabilidade em extremos, revelando limites de complexidade algorítmica e necessidades de cache","ru":"ИИ Агент Scale Game - это инструмент для тестирования масштабируемости в крайних условиях, раскрывающий пределы алгоритмической сложности и потребности в кэше","ar":"Scale Game هو أداة لاختبار التوسع في الحدود القصوى، مما يكشف عن حدود التعقيد الخوارزمي ومتطلبات التخزين المؤقت"},"seo":{"title":{"en":"Scale Game: Extreme Scaling Setup Guide | AI Agent Skill","zh":"Scale Game_SETUP GUIDE：极限规模测试","ja":"Scale Gameベストプラクティス：極限スケールテスト","ko":"Scale Game 설정 가이드: 극한 규모 테스트","es":"Guía de configuración de Scale Game: Pruebas de escalabil...","fr":"Guide de mise en place de Scale Game : Tests de scalabilité","de":"Einrichtungsleitfaden für Scale Game: Skalierbarkeitstests","pt":"Guia de Configuração do Scale Game para Desenvolvedores","ru":"Настройка ИИ Агента Scale Game: Руководство для Разработч...","ar":"دليل إعداد Scale Game للبرمجة"},"description":{"en":"Discover how to test your approach at extreme scales with Scale Game. Learn to identify breaking points and optimize performance. Get started now!","zh":"了解Scale Game的极限规模测试原理，发现算法复杂度限制和异步要求","ja":"Scale Gameの極限スケールテストの原理を学び、アルゴリズムの複雑度の限界と非同期の要件を発見する","ko":"Scale Game의 극한 규모 테스트 원리를 배우고 알고리즘 복잡도 제한과 비동기 요구 사항을 발견","es":"Aprende a probar la escalabilidad de tus aplicaciones con Scale Game. Descubre cómo identificar limitaciones y optimizar el rendimiento.","fr":"Découvrez comment tester la scalabilité de vos applications avec Scale Game. Identifiez les limitations et optimisez les performances.","de":"Erfahren Sie, wie Sie die Skalierbarkeit Ihrer Anwendungen mit Scale Game testen. Entdecken Sie, wie Sie Einschränkungen identifizieren und die Leistung opti...","pt":"Aprenda a configurar o Scale Game para testar escalabilidade em extremos e revelar limites de complexidade algorítmica","ru":"Узнайте, как настроить ИИ Агент Scale Game для тестирования масштабируемости в крайних условиях и раскрытия пределов алгоритмической сложности","ar":"تعلم كيفية إعداد Scale Game لاختبار التوسع في الحدود القصوى وكشف حدود التعقيد الخوارزمي"},"definition":{"en":"Scale Game is a technical skill that exposes fundamental truths hidden at normal scales by testing approaches at extremes, such as 1 item vs 1B items or 1 user vs 1B users.","zh":"Scale Game：一种通过极限规模测试发现算法复杂度限制和异步要求的技术","ja":"Scale Game：アルゴリズムの複雑度の限界と非同期の要件を発見するための極限スケールテスト技術","ko":"Scale Game：알고리즘 복잡도 제한과 비동기 요구 사항을 발견하는 극한 규모 테스트 기술","es":"Scale Game es una herramienta de pruebas de escalabilidad que ayuda a identificar limitaciones y optimizar el rendimiento de aplicaciones.","fr":"Scale Game est un outil de tests de scalabilité qui aide à identifier les limitations et à optimiser les performances des applications.","de":"Scale Game ist ein Tool zum Testen der Skalierbarkeit, das dabei hilft, Einschränkungen zu identifizieren und die Leistung von Anwendungen zu optimieren.","pt":"O Scale Game é uma técnica de teste de escalabilidade que expõe verdades fundamentais ocultas em escalas normais","ru":"ИИ Агент Scale Game - это метод тестирования масштабируемости, который раскрывает фундаментальные истины, скрытые на нормальных масштабах","ar":"Scale Game هو تقنية لاختبار التوسع التي تكشف الحقائق الأساسية المخفية في المقاييس العادية"},"features":{"en":["Tests algorithmic complexity limits at extreme volumes","Evaluates async requirements and caching needs at varying speeds","Assesses concurrency performance with 1 user vs 1B users","Reveals fundamental truths hidden at normal scales","Supports dynamic PHP refactoring from template HTML","Optimizes performance for large volumes and high speeds"],"zh":["支持极限规模测试","发现算法复杂度限制","识别异步要求和缓存需求","优化应用性能","支持1项至10亿项的数据测试","支持瞬间至1年的速度测试"],"ja":["極限スケールテストのサポート","アルゴリズムの複雑度の限界の発見","非同期の要件とキャッシュの要件の識別","アプリケーションのパフォーマンスの最適化","1アイテムから10億アイテムのデータテストのサポート","瞬間から1年の速度テストのサポート"],"ko":["극한 규모 테스트 지원","알고리즘 복잡도 제한 발견","비동기 요구 사항과 캐싱需求 식별","애플리케이션 성능 최적화","1개부터 10억개의 데이터 테스트 지원","순간부터 1年的 속도 테스트 지원"],"es":["Pruebas de escalabilidad en volumen, velocidad y usuarios","Identificación de limitaciones algorítmicas y de complejidad","Optimización del rendimiento y la escalabilidad","Análisis de requisitos de concurrencia y caching","Soporte para pruebas de escalabilidad en entornos dinámicos"],"fr":["Tests de scalabilité en volume, vitesse et utilisateurs","Identification des limitations algorithmiques et de complexité","Optimisation des performances et de la scalabilité","Analyse des exigences de concurrence et de caching","Prise en charge des tests de scalabilité dans des environnements dynamiques"],"de":["Skalierbarkeitstests in Bezug auf Volumen, Geschwindigkeit und Benutzer","Identifizierung von algorithmischen und komplexitätsbezogenen Einschränkungen","Optimierung der Leistung und Skalierbarkeit","Analyse von Anforderungen an Konkurrenz und Caching","Unterstützung von Skalierbarkeitstests in dynamischen Umgebungen"],"pt":["Teste de escalabilidade em extremos","Revelação de limites de complexidade algorítmica","Análise de necessidades de cache","Suporte a volumes de dados grandes","Teste de velocidade em condições extremas"],"ru":["Тестирование масштабируемости в крайних условиях","Раскрытие пределов алгоритмической сложности","Анализ потребностей в кэше","Поддержка больших объемов данных","Тестирование скорости в крайних условиях"],"ar":["اختبار التوسع في الحدود القصوى","كشف حدود التعقيد الخوارزمي","تحليل متطلبات التخزين المؤقت","دعم حجم كبير من البيانات","اختبار السرعة في الظروف القصوى"]},"keywords":{"en":["how to use Scale Game","what is Scale Game","Scale Game alternative","Scale Game vs load testing tools","Scale Game install guide","Scale Game setup for PHP developers","extreme scaling techniques","algorithmic complexity optimization","async requirements testing"],"zh":["AIエージェント","极限规模测试","算法复杂度","异步要求","缓存需求","应用性能优化","Scale Game","极限スケールテスト","AI工具"],"ja":["AIエージェント","極限スケールテスト","アルゴリズムの複雑度","非同期の要件","キャッシュの要件","アプリケーションのパフォーマンスの最適化","Scale Game","極限スケールテスト","AIツール"],"ko":["AI 에이전트","극한 규모 테스트","알고리즘 복잡도","비동기 요구 사항","캐싱需求","애플리케이션 성능 최적화","Scale Game","극한 규모 테스트","AI 도구"],"es":["pruebas de escalabilidad","herramientas de escalabilidad","optimización del rendimiento","limitaciones algorítmicas","concurrencia y caching","desarrollo de aplicaciones escalables","pruebas de escalabilidad en PHP","herramientas de pruebas de escalabilidad para desarrolladores"],"fr":["tests de scalabilité","outils de scalabilité","optimisation des performances","limites algorithmiques","concurrence et caching","développement d''applications scalables","tests de scalabilité en PHP","outils de tests de scalabilité pour développeurs"],"de":["Skalierbarkeitstests","Tools für Skalierbarkeit","Leistungsoptimierung","algorithmische Einschränkungen","Konkurrenz und Caching","Entwicklung von skalierbaren Anwendungen","Skalierbarkeitstests in PHP","Tools für Skalierbarkeitstests für Entwickler"],"pt":["Scale Game","escalabilidade em extremos","complexidade algorítmica","necessidades de cache","desenvolvimento de software","testes de escalabilidade","otimização de desempenho","desenvolvedores"],"ru":["ИИ Агент Scale Game","масштабируемость в крайних условиях","алгоритмическая сложность","потребности в кэше","разработка программного обеспечения","тестирование масштабируемости","оптимизация производительности","разработчики"],"ar":["Scale Game","توسع في الحدود القصوى","تعقيد خوارزمي","متطلبات التخزين المؤقت","برمجة","اختبار التوسع","تحسين الأداء","مطورون"]}},"owner":"piotroq","repo":"adwokat-trzebnica-html-to-php-com","repoPath":"piotroq/adwokat-trzebnica-html-to-php-com","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.475Z","topics":[],"category":"community","skillMd":{"name":"Scale Game","description":"Test at extremes (1000x bigger/smaller, instant/year-long) to expose fundamental truths hidden at normal scales","version":"1.1.0","bodyPreview":"# Scale Game\n\n## Overview\n\nTest your approach at extreme scales to find what breaks and what surprisingly survives.\n\n**Core principle:** Extremes expose fundamental truths hidden at normal scales.\n\n## Quick Reference\n\n| Scale Dimension | Test At Extremes | What It Reveals |\n|-----------------|------------------|-----------------|\n| Volume | 1 item vs 1B items | Algorithmic complexity limits |\n| Speed | Instant vs 1 year | Async requirements, caching needs |\n| Users | 1 user vs 1B users | Concurr","body":"# Scale Game\n\n## Overview\n\nTest your approach at extreme scales to find what breaks and what surprisingly survives.\n\n**Core principle:** Extremes expose fundamental truths hidden at normal scales.\n\n## Quick Reference\n\n| Scale Dimension | Test At Extremes | What It Reveals |\n|-----------------|------------------|-----------------|\n| Volume | 1 item vs 1B items | Algorithmic complexity limits |\n| Speed | Instant vs 1 year | Async requirements, caching needs |\n| Users | 1 user vs 1B users | Concurrency issues, resource limits |\n| Duration | Milliseconds vs years | Memory leaks, state growth |\n| Failure rate | Never fails vs always fails | Error handling adequacy |\n\n## Process\n\n1. **Pick dimension** - What could vary extremely?\n2. **Test minimum** - What if this was 1000x smaller/faster/fewer?\n3. **Test maximum** - What if this was 1000x bigger/slower/more?\n4. **Note what breaks** - Where do limits appear?\n5. **Note what survives** - What''s fundamentally sound?\n\n## Examples\n\n### Example 1: Error Handling\n**Normal scale:** \"Handle errors when they occur\" works fine\n**At 1B scale:** Error volume overwhelms logging, crashes system\n**Reveals:** Need to make errors impossible (type systems) or expect them (chaos engineering)\n\n### Example 2: Synchronous APIs\n**Normal scale:** Direct function calls work\n**At global scale:** Network latency makes synchronous calls unusable\n**Reveals:** Async/messaging becomes survival requirement, not optimization\n\n### Example 3: In-Memory State\n**Normal duration:** Works for hours/days\n**At years:** Memory grows unbounded, eventual crash\n**Reveals:** Need persistence or periodic cleanup, can''t rely on memory\n\n## Red Flags You Need This\n\n- \"It works in dev\" (but will it work in production?)\n- No idea where limits are\n- \"Should scale fine\" (without testing)\n- Surprised by production behavior\n\n## Remember\n\n- Extremes reveal fundamentals\n- What works at one scale fails at another\n- Test both directions (bigger AND smaller)\n- Use insights to validate architecture early\n"},"lastSynced":"2026-03-08T02:09:45.362Z","agentAnalysis":{"suitability":{"en":"Ideal for Performance Optimization Agents requiring expertise in algorithmic complexity and concurrency testing.","zh":"适用于需要算法复杂性和并发性测试专业知识的性能优化代理。","ja":"アルゴリズムの複雑さと並行性テストの専門知識を必要とするパフォーマンス最適化エージェントに最適。","ko":"알고리즘 복잡도 및 동시성 테스트에 대한 전문 지식이 필요한 성능 최적화 에이전트에 적합합니다.","es":"Ideal para agentes de optimización de rendimiento que requieren experiencia en complejidad algorítmica y pruebas de concurrencia.","fr":"Idéal pour les agents d''optimisation de performances nécessitant une expertise en complexité algorithmique et tests de concurrence.","de":"Ideal für Leistungsoptimierungsagenten, die Expertenwissen in algorithmischer Komplexität und Konkurrenztests erfordern.","pt":"Ideal para Agentes de Otimização de Desempenho que exigem conhecimento em complexidade algorítmica e teste de concorrência.","ru":"Идеально для агентов оптимизации производительности, требующих знаний в области алгоритмической сложности и тестирования конкурентности.","ar":"مثالي لعميل تحسين الأداء الذين يتطلبون خبرة في التعقيد الخوارزمي واختبار التزامن."},"recommendation":{"en":"Empowers agents to test approaches at extreme scales, revealing fundamental truths about async requirements, caching needs, and concurrency through dimensions like volume, speed, and users, utilizing concepts such as algorithmic complexity limits and async requirements.","zh":"赋予代理在极端规模下测试方法的能力，揭示关于异步要求、缓存需求和并发性的基本真理，通过诸如算法复杂性限制和异步要求等概念，利用维度如体积、速度和用户。","ja":"エージェントに極端なスケールでアプローチをテストする力を与え、アルゴリズムの複雑さの限界や非同期要件などの概念を使用して、ボリューム、速度、ユーザーなどの次元を通じて、非同期要件、キャッシュ要件、並行性についての基本的な真実を明らかにする。","ko":"에이전트가極端한 규모에서 접근 방식을 테스트할 수 있는 능력을 부여하여, 알고리즘 복잡도 한계 및 비동기 요구 사항과 같은 개념을 사용하여, 볼륨, 속도, 사용자와 같은 차원을 통해 비동기 요구 사항, 캐싱 요구 사항 및 동시성에 대한 기본적인 진실을 드러냅니다.","es":"Habilita a los agentes a probar enfoques a escalas extremas, revelando verdades fundamentales sobre requisitos asíncronos, necesidades de caché y concurrencia a través de dimensiones como volumen, velocidad y usuarios, utilizando conceptos como límites de complejidad algorítmica y requisitos asíncronos.","fr":"Permet aux agents de tester des approches à des échelles extrêmes, révélant des vérités fondamentales sur les exigences asynchrones, les besoins de mise en cache et la concurrence à travers des dimensions telles que le volume, la vitesse et les utilisateurs, en utilisant des concepts tels que les limites de complexité algorithmique et les exigences asynchrones.","de":"Ermächtigt Agenten, Ansätze in extremen Größenordnungen zu testen, grundlegende Wahrheiten über asynchrone Anforderungen, Cachierungsbedürfnisse und Konkurrenz in Dimensionen wie Volumen, Geschwindigkeit und Benutzern aufzudecken, unter Verwendung von Konzepten wie algorithmischer Komplexitätsgrenzen und asynchronen Anforderungen.","pt":"Habilita os agentes a testar abordagens em escalas extremas, revelando verdades fundamentais sobre requisitos assíncronos, necessidades de cache e concorrência por meio de dimensões como volume, velocidade e usuários, utilizando conceitos como limites de complexidade algorítmica e requisitos assíncronos.","ru":"Наделяет агентов возможностью тестировать подходы в экстремальных масштабах, раскрывая фундаментальные истины о асинхронных требованиях, потребностях в кэше и конкурентности через такие измерения, как объем, скорость и пользователи, используя понятия, такие как пределы алгоритмической сложности и асинхронные требования.","ar":"يمنح الوكلاء إمكانية اختبار المناهج في مستويات متطرفة، وكشف الحقائق الأساسية حول المتطلبات غير المتزامنة واحتياجات الذاكرة المؤقتة والتنافس من خلال أبعاد مثل الحجم والسرعة والمستخدمين، باستخدام مفاهيم مثل حدود التعقيد الخوارزمي والمتطلبات غير المتزامنة."},"useCases":{"en":["Testing application scalability for large volumes of data","Debugging async requirements and caching needs at high speeds","Optimizing concurrency for multiple user interactions"],"zh":["测试大规模数据的应用程序