INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Satoru-Oki/naki-daifugo/websocket-engineer', 'websocket-engineer', 'Satoru-Oki', 'naki-daifugo', 'community', 'websocket-engineer Satoru-Oki naki-daifugo community The websocket-engineer skill enables senior real-time systems engineers to design and implement WebSocket infrastructure with expertise in Socket.IO, native WebSockets, and horizontal scaling. It benefits developers building real-time applications. WebSocket Engineer 是一位专门从事实时通信和可扩展架构的工程师，具有 Socket.IO 和 Redis pub/sub 技术的专业知识 WebSocket エンジニアは、リアルタイム通信とスケーラブルなメッセージングアーキテクチャを専門とするエンジニアで、Socket.IO と Redis pub/sub 技術の専門知識を持っています WebSocket Engineer는 실시간 통신과 확장 가능한 메시징 아키텍처를 전문으로 하는 엔지니어로, Socket.IO와 Redis pub/sub 기술에 대한 전문 지식을 가지고 있습니다 WebSocket Engineer es un especialista senior en comunicación en tiempo real con Socket.IO y arquitecturas de mensajería escalables WebSocket Engineer est un spécialiste senior en communication en temps réel avec Socket.IO et des architectures de messagerie évolutives WebSocket Engineer ist ein Senior-Spezialist für Echtzeitkommunikation mit Socket.IO und skalierbaren Messaging-Architekturen O WebSocket Engineer é um especialista em comunicação em tempo real com expertise em Socket.IO e arquiteturas de mensagens escaláveis ИИ Агент WebSocket Engineer - это специалист по реальному времени с опытом в Socket.IO и масштабируемых архитектурах сообщений WebSocket Engineer هو خبير في التواصل في الوقت الفعلي مع خبرة في Socket.IO وعمارة الرسائل القابلة للتحجيم how to use websocket-engineer websocket-engineer setup guide websocket-engineer vs Socket.IO websocket-engineer install what is websocket-engineer websocket-engineer alternative real-time communication with websocket-engineer scalable messaging systems with websocket-engineer websocket-engineer and Redis pub/sub WebSocket Engineer 实时通信 可扩展架构 Socket.IO Redis pub/sub 水平扩展 低延迟消息系统 AIエージェント 实时系统工程师 Expertise in Socket.IO for real-time bidirectional communication Native WebSockets support for low-latency messaging Horizontal scaling with Redis pub/sub for millions of concurrent connections Design for sub-10ms p99 latency with 99.99% uptime Specialization in building WebSocket infrastructure for real-time applications websocket-engineer is a senior real-time systems engineer skill specializing in WebSocket infrastructure, Socket.IO, and scalable messaging architectures.');
