INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('the-non-expert/SikhAidSPA/sikhaid-data', 'sikhaid-data', 'the-non-expert', 'SikhAidSPA', 'community', 'sikhaid-data the-non-expert SikhAidSPA community SikhAid数据AI工具是一个单页应用，为NGO组织SikhAid提供数据支持 SikhAid AIエージェントは、NGO団体SikhAid向けのシングルページアプリケーションです SikhAid 데이터 AI 에이전트는 SikhAid NGO를 위한 单页 응용 프로그램입니다 SikhAid Data es una aplicación de página única para ONG, desarrollada con tecnologías web modernas. Ofrece una plataforma eficiente para la gestión de datos SikhAid Data est une application à page unique pour ONG, développée avec des technologies web modernes. Elle offre une plateforme efficace pour la gestion de données SikhAid Data ist eine Single-Page-Anwendung für NRO, entwickelt mit modernen Webtechnologien. Sie bietet eine effiziente Plattform für die Datenverwaltung SikhAid-Data é uma aplicação de página única para a ONG SikhAid, desenvolvida com React SikhAid-Data - это одностраничное приложение для НПО SikhAid, разработанное с использованием React SikhAid-Data هو تطبيق صفحة واحدة لمنظمة SikhAid غير الحكومية، تم تطويره باستخدام React It''s a single page application for a NGO called "SikhAid" SikhAid数据AI工具 React单页应用 Node.js开发 AI工具安装 SikhAid NGO数据支持 如何使用SikhAid数据AI工具 SikhAid数据AI工具替代品 SikhAid数据AI工具与其他工具的比较 It''s a single page application for a NGO called "SikhAid"');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ChatAndBuild/chatchat-skills/Payment Integration', 'community', 'ChatAndBuild', 'chatchat-skills', 'ChatAndBuild/chatchat-skills', 'Payment Integration', 0, 0, 43, '2026-03-04T13:07:01.961Z', '2026-03-04T15:13:56.257Z', 'a0a65846d89c9737881dc9b1e2bfca7af8f36ffb761476d3db63c430b133e3d2', '{"id":"ChatAndBuild/chatchat-skills/Payment Integration","name":"Payment Integration","description":{"zh":"支付集成技能可用于ChatChat中的AI智能代理，实现便捷的支付功能","ja":"AIエージェントの決済統合スキルは、ChatChatで利用可能です","ko":"결제 통합 기능은 ChatChat의 AI 에이전트에서 사용할 수 있습니다","es":"La integración de pagos es una habilidad que permite a los agentes de IA procesar transacciones de forma segura y eficiente.","fr":"L''intégration de paiement est une compétence qui permet aux outils d''IA de traiter des transactions de manière sécurisée et efficace","de":"Die Zahlungsintegration ist eine Fähigkeit, die es KI-Agenten ermöglicht, Transaktionen sicher und effizient zu verarbeiten","pt":"A integração de pagamento é uma habilidade essencial para agentes de IA, permitindo transações financeiras seguras e eficientes.","ru":"Интеграция платежей - это важнейший навык для ИИ Агентов, позволяющий осуществлять безопасные и эффективные финансовые транзакции.","ar":"تكامل الدفع هو مهارة أساسية للأدوات الذكية، مما يسمح بالمعاملات المالية الآمنة والفعالة.","en":"Skills that can be used by your agents in ChatChat."},"seo":{"title":{"zh":"AI智能代理支付集成","ja":"AIエージェントの決済統合","ko":"AI 에이전트 결제 통합","es":"Integración de Pagos para Agentes de IA","fr":"Intégration de Paiement pour Outils d''IA","de":"Zahlungsintegration für KI-Agenten","pt":"Integração de Pagamento para Ferramentas de IA Agentes","ru":"ИИ Агенты: Интеграция Платежей","ar":"تكامل الدفع للأدوات الذكية","en":"Payment Integration"},"description":{"zh":"支付集成技能可用于ChatChat中的AI智能代理，实现便捷的支付功能","ja":"AIエージェントの決済統合スキルは、ChatChatで利用可能です","ko":"결제 통합 기능은 ChatChat의 AI 에이전트에서 사용할 수 있습니다","es":"La integración de pagos es una habilidad que permite a los agentes de IA procesar transacciones de forma segura y eficiente.","fr":"L''intégration de paiement est une compétence qui permet aux outils d''IA de traiter des transactions de manière sécurisée et efficace","de":"Die Zahlungsintegration ist eine Fähigkeit, die es KI-Agenten ermöglicht, Transaktionen sicher und effizient zu verarbeiten","pt":"A integração de pagamento é uma habilidade essencial para agentes de IA, permitindo transações financeiras seguras e eficientes.","ru":"Интеграция платежей - это важнейший навык для ИИ Агентов, позволяющий осуществлять безопасные и эффективные финансовые транзакции.","ar":"تكامل الدفع هو مهارة أساسية للأدوات الذكية، مما يسمح بالمعاملات المالية الآمنة والفعالة.","en":"Skills that can be used by your agents in ChatChat."},"definition":{"en":"Skills that can be used by your agents in ChatChat."},"features":{"zh":["支持多种支付方式","实现便捷的支付功能","提高开发效率","简化支付流程","增强用户体验"],"ja":["複数の決済方式をサポート","便利な決済機能を実現","開発効率を向上","決済プロセスを簡素化","ユーザーエクスペリエンスを向上"],"ko":["다양한 결제 방법 지원","편리한 결제 기능 구현","개발 효율성을 높임","결제 과정을 단순화","사용자 경험 향상"],"es":["Procesamiento de pagos seguro","Integración con múltiples gateways de pago","Soporte para diferentes monedas","Notificaciones de pago en tiempo real","Informes de pago detallados"],"fr":["Traitement de paiement sécurisé","Intégration avec de multiples passerelles de paiement","Prise en charge de différentes devises","Notifications de paiement en temps réel","Rapports de paiement détaillés"],"de":["Sichere Zahlungsverarbeitung","Integration mit mehreren Zahlungsgateways","Unterstützung für verschiedene Währungen","Echtzeit-Zahlungsbenachrichtigungen","Detaillierte Zahlungsberichte"],"pt":["Processamento de pagamentos seguros","Integração com gateways de pagamento","Suporte a múltiplos métodos de pagamento","Notificação de pagamentos em tempo real","Análise de pagamentos e relatórios"],"ru":["Безопасная обработка платежей","Интеграция с шлюзами оплаты","Поддержка нескольких методов оплаты","Уведомление о платежах в режиме реального времени","Анализ платежей и отчеты"],"ar":["معالجة مدفوعات آمنة","التكامل مع بوابات الدفع","دعم أساليب الدفع المتعددة","إشعار بالدفعات في الوقت الفعلي","تحليل الدفعات والتقارير"]},"keywords":{"zh":["AI智能代理","支付集成","如何使用支付集成","支付集成的优势","支付集成与其他工具的比较","支付集成安装指南","支付集成设置教程"],"ja":["AIエージェント","決済統合","決済統合の使い方","決済統合の利点","決済統合と他のツールの比較","決済統合のインストールガイド","決済統合の設定マニュアル"],"ko":["AI 에이전트","결제 통합","결제 통합 사용법","결제 통합의 장점","결제 통합과 다른 도구의 비교","결제 통합 설치 가이드","결제 통합 설정 매뉴얼"],"es":["cómo integrar pagos en agentes de IA","integación de pagos para ChatChat","alternativas a Stripe para agentes de IA","cómo configurar la integración de pagos","guía de instalación de la integración de pagos","integación de pagos vs pasarelas de pago","beneficios de la integración de pagos para agentes de IA","mejores prácticas para la integración de pagos en agentes de IA"],"fr":["comment intégrer les paiements dans les outils d''IA","intégration de paiement pour ChatChat","alternatives à Stripe pour les outils d''IA","comment configurer l''intégration de paiement","guide d''installation de l''intégration de paiement","intégration de paiement vs passerelles de paiement","avantages de l''intégration de paiement pour les outils d''IA","meilleures pratiques pour l''intégration de paiement dans les outils d''IA"],"de":["wie man Zahlungen in KI-Agenten integriert","Zahlungsintegration für ChatChat","Alternativen zu Stripe für KI-Agenten","wie man die Zahlungsintegration konfiguriert","Anleitung zur Installation der Zahlungsintegration","Zahlungsintegration vs Zahlungsgateways","Vorteile der Zahlungsintegration für KI-Agenten","beste Praktiken für die Zahlungsintegration in KI-Agenten"],"pt":["como usar integração de pagamento","o que é integração de pagamento","integração de pagamento para IA","alternative de pagamento para desenvolvedores","integração de pagamento vs gateway de pagamento","instalação de integração de pagamento","guia de configuração de integração de pagamento"],"ru":["как использовать интеграцию платежей","что такое интеграция платежей","интеграция платежей для ИИ","альтернатива платежей для разработчиков","интеграция платежей vs шлюз оплаты","установка интеграции платежей","руководство по настройке интеграции платежей"],"ar":["كيفية استخدام تكامل الدفع","ما هو تكامل الدفع","تكامل الدفع للأدوات الذكية","بديل الدفع للمطورين","تكامل الدفع مقابل بوابة الدفع","تثبيت تكامل الدفع","دليل إعداد تكامل الدفع"]}},"owner":"ChatAndBuild","repo":"chatchat-skills","repoPath":"ChatAndBuild/chatchat-skills","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.961Z","topics":[],"category":"community","skillMd":{"name":"Payment Integration","description":"Implement Stripe payment processing for robust, PCI-compliant payment flows including checkout, subscriptions, and webhooks.","bodyPreview":"# Stripe Integration\n\nMaster Stripe payment processing integration for robust, PCI-compliant payment flows including checkout, subscriptions, webhooks, and refunds.\n\n## When to Use This Skill\n\n- Implementing payment processing in web/mobile applications\n- Setting up subscription billing systems\n- Handling one-time payments and recurring charges\n- Processing refunds and disputes\n- Managing customer payment methods\n- Implementing SCA (Strong Customer Authentication) for European payments\n- Buildin","body":"# Stripe Integration\n\nMaster Stripe payment processing integration for robust, PCI-compliant payment flows including checkout, subscriptions, webhooks, and refunds.\n\n## When to Use This Skill\n\n- Implementing payment processing in web/mobile applications\n- Setting up subscription billing systems\n- Handling one-time payments and recurring charges\n- Processing refunds and disputes\n- Managing customer payment methods\n- Implementing SCA (Strong Customer Authentication) for European payments\n- Building marketplace payment flows with Stripe Connect\n\n## Core Concepts\n\n### 1. Payment Flows\n\n**Checkout Session (Hosted)**\n\n- Stripe-hosted payment page\n- Minimal PCI compliance burden\n- Fastest implementation\n- Supports one-time and recurring payments\n\n**Payment Intents (Custom UI)**\n\n- Full control over payment UI\n- Requires Stripe.js for PCI compliance\n- More complex implementation\n- Better customization options\n\n**Setup Intents (Save Payment Methods)**\n\n- Collect payment method without charging\n- Used for subscriptions and future payments\n- Requires customer confirmation\n\n### 2. Webhooks\n\n**Critical Events:**\n\n- `payment_intent.succeeded`: Payment completed\n- `payment_intent.payment_failed`: Payment failed\n- `customer.subscription.updated`: Subscription changed\n- `customer.subscription.deleted`: Subscription canceled\n- `charge.refunded`: Refund processed\n- `invoice.payment_succeeded`: Subscription payment successful\n\n### 3. Subscriptions\n\n**Components:**\n\n- **Product**: What you''re selling\n- **Price**: How much and how often\n- **Subscription**: Customer''s recurring payment\n- **Invoice**: Generated for each billing cycle\n\n### 4. Customer Management\n\n- Create and manage customer records\n- Store multiple payment methods\n- Track customer metadata\n- Manage billing details\n\n## Quick Start\n\n```python\nimport stripe\n\nstripe.api_key = \"sk_test_...\"\n\n# Create a checkout session\nsession = stripe.checkout.Session.create(\n    payment_method_types=[''card''],\n    line_items=[{\n        ''price_data'': {\n            ''currency'': ''usd'',\n            ''product_data'': {\n                ''name'': ''Premium Subscription'',\n            },\n            ''unit_amount'': 2000,  # $20.00\n            ''recurring'': {\n                ''interval'': ''month'',\n            },\n        },\n        ''quantity'': 1,\n    }],\n    mode=''subscription'',\n    success_url=''https://yourdomain.com/success?session_id={CHECKOUT_SESSION_ID}'',\n    cancel_url=''https://yourdomain.com/cancel'',\n)\n\n# Redirect user to session.url\nprint(session.url)\n```\n\n## Payment Implementation Patterns\n\n### Pattern 1: One-Time Payment (Hosted Checkout)\n\n```python\ndef create_checkout_session(amount, currency=''usd''):\n    \"\"\"Create a one-time payment checkout session.\"\"\"\n    try:\n        session = stripe.checkout.Session.create(\n            payment_method_types=[''card''],\n            line_items=[{\n                ''price_data'': {\n                    ''currency'': currency,\n                    ''product_data'': {\n                        ''name'': ''Purchase'',\n                        ''images'': [''https://example.com/product.jpg''],\n                    },\n                    ''unit_amount'': amount,  # Amount in cents\n                },\n                ''quantity'': 1,\n            }],\n            mode=''payment'',\n            success_url=''https://yourdomain.com/success?session_id={CHECKOUT_SESSION_ID}'',\n            cancel_url=''https://yourdomain.com/cancel'',\n            metadata={\n                ''order_id'': ''order_123'',\n                ''user_id'': ''user_456''\n            }\n        )\n        return session\n    except stripe.error.StripeError as e:\n        # Handle error\n        print(f\"Stripe error: {e.user_message}\")\n        raise\n```\n\n### Pattern 2: Custom Payment Intent Flow\n\n```python\ndef create_payment_intent(amount, currency=''usd'', customer_id=None):\n    \"\"\"Create a payment intent for custom checkout UI.\"\"\"\n    intent = stripe.PaymentIntent.create(\n        amount=amount,\n        currency=currency,\n        customer=customer_id,\n        automatic_payment_methods={\n            ''enabled'': True,\n        },\n        metadata={\n            ''integration_check'': ''accept_a_payment''\n        }\n    )\n    return intent.client_secret  # Send to frontend\n\n# Frontend (JavaScript)\n\"\"\"\nconst stripe = Stripe(''pk_test_...'');\nconst elements = stripe.elements();\nconst cardElement = elements.create(''card'');\ncardElement.mount(''#card-element'');\n\nconst {error, paymentIntent} = await stripe.confirmCardPayment(\n    clientSecret,\n    {\n        payment_method: {\n            card: cardElement,\n            billing_details: {\n                name: ''Customer Name''\n            }\n        }\n    }\n);\n\nif (error) {\n    // Handle error\n} else if (paymentIntent.status === ''succeeded'') {\n    // Payment successful\n}\n\"\"\"\n```\n\n### Pattern 3: Subscription Creation\n\n```python\ndef create_subscription(customer_id, price_id):\n    \"\"\"Create a subscription for a customer.\"\"\"\n    try:\n        subscription = stripe.Subscription.create(\n            customer=customer_id,\n            items=[{''price'': price_id}],\n            payment_behavior=''default_incomplete'',\n            payment_settings={''save_default_payment_method'': ''on_subscription''},\n            expand=[''latest_invoice.payment_intent''],\n        )\n\n        return {\n            ''subscription_id'': subscription.id,\n            ''client_secret'': subscription.latest_invoice.payment_intent.client_secret\n        }\n    except stripe.error.StripeError as e:\n        print(f\"Subscription creation failed: {e}\")\n        raise\n```\n\n### Pattern 4: Customer Portal\n\n```python\ndef create_customer_portal_session(customer_id):\n    \"\"\"Create a portal session for customers to manage subscriptions.\"\"\"\n    session = stripe.billing_portal.Session.create(\n        customer=customer_id,\n        return_url=''https://yourdomain.com/account'',\n    )\n    return session.url  # Redirect customer here\n```\n\n## Webhook Handling\n\n### Secure Webhook Endpoint\n\n```python\nfrom flask import Flask, request\nimport stripe\n\napp = Flask(__name__)\n\nendpoint_secret = ''whsec_...''\n\n@app.route(''/webhook'', methods=[''POST''])\ndef webhook():\n    payload = request.data\n    sig_header = request.headers.get(''Stripe-Signature'')\n\n    try:\n        event = stripe.Webhook.construct_event(\n            payload, sig_header, endpoint_secret\n        )\n    except ValueError:\n        # Invalid payload\n        return ''Invalid payload'', 400\n    except stripe.error.SignatureVerificationError:\n        # Invalid signature\n        return ''Invalid signature'', 400\n\n    # Handle the event\n    if event[''type''] == ''payment_intent.succeeded'':\n        payment_intent = event[''data''][''object'']\n        handle_successful_payment(payment_intent)\n    elif event[''type''] == ''payment_intent.payment_failed'':\n        payment_intent = event[''data''][''object'']\n        handle_failed_payment(payment_intent)\n    elif event[''type''] == ''customer.subscription.deleted'':\n        subscription = event[''data''][''object'']\n        handle_subscription_canceled(subscription)\n\n    return ''Success'', 200\n\ndef handle_successful_payment(payment_intent):\n    \"\"\"Process successful payment.\"\"\"\n    customer_id = payment_intent.get(''customer'')\n    amount = payment_intent[''amount'']\n    metadata = payment_intent.get(''metadata'', {})\n\n    # Update your database\n    # Send confirmation email\n    # Fulfill order\n    print(f\"Payment succeeded: {payment_intent[''id'']}\")\n\ndef handle_failed_payment(payment_intent):\n    \"\"\"Handle failed payment.\"\"\"\n    error = payment_intent.get(''last_payment_error'', {})\n    print(f\"Payment failed: {error.get(''message'')}\")\n    # Notify customer\n    # Update order status\n\ndef handle_subscription_canceled(subscription):\n    \"\"\"Handle subscription cancellation.\"\"\"\n    customer_id = subscription[''customer'']\n    # Update user access\n    # Send cancellation email\n    print(f\"Subscription canceled: {subscription[''id'']}\")\n```\n\n### Webhook Best Practices\n\n```python\nimport hashlib\nimport hmac\n\ndef verify_webhook_signature(payload, signature, secret):\n    \"\"\"Manually verify webhook signature.\"\"\"\n    expected_sig = hmac.new(\n        secret.encode(''utf-8''),\n        payload,\n        hashlib.sha256\n    ).hexdigest()\n\n    return hmac.compare_digest(signature, expected_sig)\n\ndef handle_webhook_idempotently(event_id, handler):\n    \"\"\"Ensure webhook is processed exactly once.\"\"\"\n    # Check if event already processed\n    if is_event_processed(event_id):\n        return\n\n    # Process event\n    try:\n        handler()\n        mark_event_processed(event_id)\n    except Exception as e:\n        log_error(e)\n        # Stripe will retry failed webhooks\n        raise\n```\n\n## Customer Management\n\n```python\ndef create_customer(email, name, payment_method_id=None):\n    \"\"\"Create a Stripe customer.\"\"\"\n    customer = stripe.Customer.create(\n        email=email,\n        name=name,\n        payment_method=payment_method_id,\n        invoice_settings={\n            ''default_payment_method'': payment_method_id\n        } if payment_method_id else None,\n        metadata={\n            ''user_id'': ''12345''\n        }\n    )\n    return customer\n\ndef attach_payment_method(customer_id, payment_method_id):\n    \"\"\"Attach a payment method to a customer.\"\"\"\n    stripe.PaymentMethod.attach(\n        payment_method_id,\n        customer=customer_id\n    )\n\n    # Set as default\n    stripe.Customer.modify(\n        customer_id,\n        invoice_settings={\n            ''default_payment_method'': payment_method_id\n        }\n    )\n\ndef list_customer_payment_methods(customer_id):\n    \"\"\"List all payment methods for a customer.\"\"\"\n    payment_methods = stripe.PaymentMethod.list(\n        customer=customer_id,\n        type=''card''\n    )\n    return payment_methods.data\n```\n\n## Refund Handling\n\n```python\ndef create_refund(payment_intent_id, amount=None, reason=None):\n    \"\"\"Create a refund.\"\"\"\n    refund_params = {\n        ''payment_intent'': payment_intent_id\n    }\n\n    if amount:\n        refund_params[''amount''] = amount  # Partial refund\n\n    if reason:\n        refund_params[''reason''] = reason  # ''duplicate'', ''fraudulent'', ''requested_by_customer''\n\n    refund = stripe.Refund.create(**refund_params)\n    return refund\n\ndef handle_dispute(charge_id, evidence):\n    \"\"\"Update dispute with evidence.\"\"\"\n    stripe.Dispute.modify(\n        charge_id,\n        evidence={\n            ''customer_name'': evidence.get(''customer_name''),\n            ''customer_email_address'': evidence.get(''customer_email''),\n            ''shipping_documentation'': evidence.get(''shipping_proof''),\n            ''customer_communication'': evidence.get(''communication''),\n        }\n    )\n```\n\n## Testing\n\n```python\n# Use test mode keys\nstripe.api_key = \"sk_test_...\"\n\n# Test card numbers\nTEST_CARDS = {\n    ''success'': ''4242424242424242'',\n    ''declined'': ''4000000000000002'',\n    ''3d_secure'': ''4000002500003155'',\n    ''insufficient_funds'': ''4000000000009995''\n}\n\ndef test_payment_flow():\n    \"\"\"Test complete payment flow.\"\"\"\n    # Create test customer\n    customer = stripe.Customer.create(\n        email=\"test@example.com\"\n    )\n\n    # Create payment intent\n    intent = stripe.PaymentIntent.create(\n        amount=1000,\n        currency=''usd'',\n        customer=customer.id,\n        payment_method_types=[''card'']\n    )\n\n    # Confirm with test card\n    confirmed = stripe.PaymentIntent.confirm(\n        intent.id,\n        payment_method=''pm_card_visa''  # Test payment method\n    )\n\n    assert confirmed.status == ''succeeded''\n```\n\n## Resources\n\n- **references/checkout-flows.md**: Detailed checkout implementation\n- **references/webhook-handling.md**: Webhook security and processing\n- **references/subscription-management.md**: Subscription lifecycle\n- **references/customer-management.md**: Customer and payment method handling\n- **references/invoice-generation.md**: Invoicing and billing\n- **assets/stripe-client.py**: Production-ready Stripe client wrapper\n- **assets/webhook-handler.py**: Complete webhook processor\n- **assets/checkout-config.json**: Checkout configuration templates\n\n## Best Practices\n\n1. **Always Use Webhooks**: Don''t rely solely on client-side confirmation\n2. **Idempotency**: Handle webhook events idempotently\n3. **Error Handling**: Gracefully handle all Stripe errors\n4. **Test Mode**: Thoroughly test with test keys before production\n5. **Metadata**: Use metadata to link Stripe objects to your database\n6. **Monitoring**: Track payment success rates and errors\n7. **PCI Compliance**: Never handle raw card data on your server\n8. **SCA Ready**: Implement 3D Secure for European payments\n\n## Common Pitfalls\n\n- **Not Verifying Webhooks**: Always verify webhook signatures\n- **Missing Webhook Events**: Handle all relevant webhook events\n- **Hardcoded Amounts**: Use cents/smallest currency unit\n- **No Retry Logic**: Implement retries for API calls\n- **Ignoring Test Mode**: Test all edge cases with test cards\n"},"lastSynced":"2026-03-04T15:13:56.257Z","agentAnalysis":{"suitability":{"en":"Ideal for E-commerce Agents requiring secure and compliant payment processing integration with Stripe","zh":"适合需要与Stripe集成安全合规的支付处理的电子商务代理","ja":"Stripeとのセキュアで準拠した決済処理の統合が必要な電子商取引エージェントに適しています","ko":"Stripe와의 안전하고 준수된 결제 처리 통합이 필요한 전자상거래 에이전트에 적합합니다","es":"Ideal para agentes de comercio electrónico que requieren una integración de procesamiento de pagos segura y cumplida con Stripe","fr":"Idéal pour les agents de commerce électronique nécessitant une intégration de traitement de paiement sécurisée et conforme avec Stripe","de":"Ideal für E-Commerce-Agents, die eine sichere und konforme Zahlungsabwicklungsintegration mit Stripe benötigen","pt":"Ideal para Agentes de Comércio Eletrônico que exigem processamento de pagamento seguro e compatível com a integração do Stripe","ru":"Идеально для агентов электронной коммерции, требующих безопасной и соответствующей интеграции обработки платежей с Stripe","ar":"مثالي لعميل تجارة إلكترونية يحتاج إلى معالجة دفع آمنة ومطابقة للتكامل مع Stripe"},"recommendation":{"en":"Empowers agents to implement robust PCI-compliant payment flows, including checkout, subscriptions, webhooks, and refunds, using Stripe''s API and handling SCA for European payments","zh":"赋予代理商使用Stripe的API实现强大的PCI合规支付流，包括结账、订阅、Webhooks和退款，并处理欧洲支付的SCA","ja":"エージェントがStripeのAPIを使用して、PCIコンプライアンスの支払いフローを実装できるようにすることで、チェックアウト、サブスクリプション、Webhook、返金、およびヨーロッパ向けの支払いのSCAのハンドリングが可能となる","ko":"에이전트가 Stripe의 API를 사용하여 강력한 PCI 준수 결제 흐름을 구현할 수 있도록 하여, 체크아웃, 구독, 웹후크, 환불 및 유럽 지불의 SCA 처리가 가능함","es":"Habilita a los agentes a implementar flujos de pago robustos y cumplidos con PCI, incluyendo checkout, suscripciones, webhooks y reembolsos, utilizando la API de Stripe y manejando SCA para pagos europeos","fr":"Permet aux agents de mettre en œuvre des flux de paiement robustes et conformes à la PCI, notamment la vérification, les abonnements, les webhooks et les remboursements, en utilisant l''API de Stripe et en gérant la SCA pour les paiements européens","de":"Ermächtigt Agenten, robuste und PCI-konforme Zahlungsflüsse zu implementieren, einschließlich Checkout, Abonnements, Webhooks und Rückerstattungen, unter Verwendung der Stripe-API und Handhabung von SCA für europäische Zahlungen","pt":"Habilita os agentes a implementar fluxos de pagamento robustos e compatíveis com o PCI, incluindo checkout, assinaturas, webhooks e reembolsos, usando a API do Stripe e lidando com a SCA para pagamentos europeus","ru":"Позволяет агентам реализовать надежные потоки платежей, соответствующие стандарту PCI, включая оформление заказа, подписки, вебхуки и возвраты, используя API Stripe и обрабатывая SCA для европейских платежей","ar":"تمكين الوكلاء من تنفيذ تدفقات الدفع القوية والمتوافقة مع معايير_PCI، بما في ذلك الدفع، والاشتراكات، و_webhooks، والاستردادات، باستخدام واجهة برمجة تطبيقات Stripe ومعالجة SCA لل مدفوعات الأوروبية"},"useCases":{"en":["Implementing one-time and recurring payment processing","Managing subscription billing systems and customer payment methods","Handling refunds, disputes, and chargebacks via Stripe webhooks"],"zh":["实现一次性和定期支付处理","管理订阅计费系统和客户支付方式","通过Stripe Webhooks处理退款、争议和退款"],"ja":["一時的な支払い処理と定期的な支払い処理の実装","サブスクリプション請求システムと顧客の支払い方法の管理","Stripe Webhooksを使用した返金、紛争、チャージバックの処理"],"ko":["1회성 및定기 결제 처리 구현","구독 청구 시스템 및 고객의 결제 방법 관리","Stripe 웹후크를 통한 환불, 분쟁, 차지백 처리"],"es":["Implementar el procesamiento de pagos de una sola vez y recurrente","Gestionar sistemas de facturación de suscripciones y métodos de pago del cliente","Manejar reembolsos, disputas y devoluciones de cargo mediante webhooks de Stripe"],"fr":["Mettre en œuvre le traitement des paiements à la fois et récurrents","Gérer les systèmes de facturation d''abonnement et les méthodes de paiement du client","Gérer les remboursements, les litiges et les débits de Stripe via des webhooks"],"de":["Implementierung von einmaligen und wiederkehrenden Zahlungsabwicklungen","Verwaltung von Abonnements-Rechnungssystemen und Kunden-Zahlungsmethoden","Handhabung von Rückerstattungen, Streitigkeiten und Chargebacks über Stripe-Webhooks"],"pt":["Implementar processamento de pagamento de uma só vez e recorrente","Gerenciar sistemas de faturamento de assinaturas e métodos de pagamento do cliente","Lidar com reembolsos, disputas e chargebacks via webhooks do Stripe"],"ru":["Реализация одноразовой и регулярной обработки платежей","Управление системами выставления счетов за подписку и методами оплаты клиентов","Обработка возвратов, споров и оспариваний через вебхуки Stripe"],"ar":["تنفيذ معالجة الدفع لمرة واحدة ومتكررة","إدارة أنظمة فواتير الاشتراك وأساليب الدفع للعميل","معالجة الاستردادات والمعارضات والاستردادات من خلال الـ webhooks لبرنامج Stripe"]},"limitations":{"en":["Requires Stripe account and API keys","Must comply with PCI standards for payment processing","Limited to Stripe payment gateway"],"zh":["需要Stripe帐户和API密钥","必须遵守PCI标准进行支付处理","仅限于Stripe支付网关"],"ja":["StripeアカウントとAPIキーが必要","支払い処理にPCI標準を遵守する必要がある","Stripe決済ゲートウェイに限定される"],"ko":["Stripe 계정 및 API 키가 필요함","결제 처리에 PCI 표준을 준수해야 함","Stripe 결제 게이트웨이에만 제한됨"],"es":["Requiere una cuenta y claves de API de Stripe","Debe cumplir con los estándares de PCI para el procesamiento de pagos","Limitado a la pasarela de pago de Stripe"],"fr":["Nécessite un compte et des clés d''API de Stripe","Doit se conformer aux normes de PCI pour le traitement des paiements","Limité à la passerelle de paiement de Stripe"],"de":["Benötigt ein Stripe-Konto und API-Schlüssel","Muss den PCI-Standards für die Zahlungsabwicklung entsprechen","Begrenzt auf die Stripe-Zahlungsgateway"],"pt":["Requer conta do Stripe e chaves de API","Deve cumprir com os padrões de PCI para processamento de pagamento","Limitado ao gateway de pagamento do Stripe"],"ru":["Требуется учетная запись Stripe и ключи API","Должно соответствовать стандартам PCI для обработки платежей","Ограничен только шлюзом оплаты Stripe"],"ar":["يتطلب حساب Stripe ومفاتيح API","يجب امتثاله لمعايير PCI لمعالجة الدفع","محدود ببوابة الدفع Stripe فقط"]},"version":3},"contentHash":"a0a65846d89c9737881dc9b1e2bfca7af8f36ffb761476d3db63c430b133e3d2","qualityScore":43}');
