INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ChatAndBuild/chatchat-skills/Payment Integration', 'Payment Integration', 'ChatAndBuild', 'chatchat-skills', 'community', 'Payment Integration ChatAndBuild chatchat-skills community 支付集成技能可用于ChatChat中的AI智能代理，实现便捷的支付功能 AIエージェントの決済統合スキルは、ChatChatで利用可能です 결제 통합 기능은 ChatChat의 AI 에이전트에서 사용할 수 있습니다 La integración de pagos es una habilidad que permite a los agentes de IA procesar transacciones de forma segura y eficiente. L''intégration de paiement est une compétence qui permet aux outils d''IA de traiter des transactions de manière sécurisée et efficace Die Zahlungsintegration ist eine Fähigkeit, die es KI-Agenten ermöglicht, Transaktionen sicher und effizient zu verarbeiten A integração de pagamento é uma habilidade essencial para agentes de IA, permitindo transações financeiras seguras e eficientes. Интеграция платежей - это важнейший навык для ИИ Агентов, позволяющий осуществлять безопасные и эффективные финансовые транзакции. تكامل الدفع هو مهارة أساسية للأدوات الذكية، مما يسمح بالمعاملات المالية الآمنة والفعالة. Skills that can be used by your agents in ChatChat. AI智能代理 支付集成 如何使用支付集成 支付集成的优势 支付集成与其他工具的比较 支付集成安装指南 支付集成设置教程 Skills that can be used by your agents in ChatChat.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dotnet/efcore/tooling', 'community', 'dotnet', 'efcore', 'dotnet/efcore', 'tooling', 14598, 3364, 42, '2026-03-06T22:49:36Z', '2026-03-07T01:50:07.020Z', '477b2212bf343f734e396bb502f77c61de4fe87d841793b2d818f95642da30a3', '{"id":"dotnet/efcore/tooling","name":"tooling","description":{"en":"Tooling enables efficient database management for .NET developers using EF Core. It supports LINQ queries, change tracking, and schema migrations.","zh":"EF Core 提供了 dotnet ef CLI 和 Visual Studio Package Manager Console 命令，用于简化数据库迁移和模型管理","ja":"EF Core は、dotnet ef CLI と Visual Studio Package Manager Console コマンドを提供し、データベース マイグレーションとモデル管理を簡素化します","ko":"EF Core는 dotnet ef CLI와 Visual Studio Package Manager Console 명령을 제공하여 데이터베이스 마이그레이션과 모델 관리를 간소화합니다","es":"Entity Framework Core es un mapeador de objetos de base de datos moderno para .NET que admite consultas LINQ, seguimiento de cambios y migraciones de esquemas.","fr":"Entity Framework Core est un mapeur d''objets de base de données moderne pour .NET qui prend en charge les requêtes LINQ, le suivi des modifications et les migrations de schémas.","de":"Entity Framework Core ist ein moderner Objekt-Datenbank-Mapper für .NET, der LINQ-Abfragen, Änderungsnachverfolgung und Schemamigrationen unterstützt.","pt":"O EF Core é um mapeador de objeto-banco de dados moderno para .NET, que suporta consultas LINQ, rastreamento de alterações e migrações de esquema.","ru":"EF Core — современный объектно-реляционный маппер для .NET, поддерживающий запросы LINQ, отслеживание изменений и миграции схемы с помощью ИИ Агентов","ar":"EF Core هو مُحَوِّل كائن-قاعدة بيانات حديث للـ .NET، يدعم استفسارات LINQ ومراقبة التغييرات وعمليات نقل مخطط القاعدة"},"seo":{"title":{"en":"Tooling: EF Core Setup Guide | AI Agent Skill","zh":"EF Core 工具设置指南","ja":"EF Core ツールのベストプラクティス","ko":"EF Core 도구 설정 가이드","es":"Guía de configuración de herramientas de Entity Framework...","fr":"Guide de configuration des outils Entity Framework Core","de":"Einrichtungsleitfaden für Entity Framework Core-Tools","pt":"Guia de Configuração de Ferramentas de Desenvolvimento co...","ru":"Настройка инструментов разработки с помощью EF Core и ИИ ...","ar":"دليل إعداد أدوات التطوير باستخدام EF Core ووكلاء الذكاء ا..."},"description":{"en":"Unlock efficient database management with tooling. Learn how to leverage dotnet ef CLI and Visual Studio Package Manager Console for seamless migrations and ...","zh":"了解 EF Core 的 dotnet ef CLI 和 Visual Studio Package Manager Console 命令，用于迁移、脚手架和编译模型","ja":"EF Core の dotnet ef CLI と Visual Studio Package Manager Console コマンドを使用して、マイグレーション、スキャフォールディング、コンパイル モデルを実行します","ko":"EF Core의 dotnet ef CLI와 Visual Studio Package Manager Console 명령을 사용하여 마이그레이션, 스캐폴딩, 컴파일 모델을 수행하는 방법을 확인합니다","es":"Aprende a utilizar las herramientas de Entity Framework Core para mejorar tus proyectos .NET","fr":"Découvrez comment utiliser les outils Entity Framework Core pour améliorer vos projets .NET","de":"Erfahren Sie, wie Sie Entity Framework Core-Tools verwenden, um Ihre .NET-Projekte zu verbessern","pt":"Aprenda a configurar e utilizar as ferramentas de desenvolvimento do EF Core para melhorar a produtividade e a eficiência do seu projeto","ru":"Узнайте, как настроить и использовать инструменты разработки EF Core для повышения производительности и эффективности вашего проекта с помощью ИИ Агентов","ar":"تعلم كيفية إعداد واستخدام أدوات التطوير في EF Core لتحسين الإنتاجية والكفاءة في مشروعك مع وكلاء الذكاء الاصطناعي"},"definition":{"en":"Tooling is a set of commands and tools for Entity Framework Core, including the dotnet ef CLI and Visual Studio Package Manager Console.","zh":"EF Core 工具是用于 .NET 的现代对象-数据库映射器，支持 LINQ 查询、更改跟踪、更新和模式迁移","ja":"EF Core ツールは、.NET 用のモダンなオブジェクト-データベース マッパーであり、LINQ クエリ、変更の追跡、更新、およびスキーマ マイグレーションをサポートします","ko":"EF Core 도구는 .NET용 현대적인 객체-데이터베이스 매퍼로서 LINQ 쿼리, 변경 추적, 업데이트 및 스키마 마이그레이션을 지원합니다","es":"Herramientas de Entity Framework Core son conjuntos de comandos CLI y herramientas de gestión de paquetes que facilitan la migración y el modelado de bases de datos.","fr":"Les outils Entity Framework Core sont des ensembles de commandes CLI et d''outils de gestion de packages qui facilitent la migration et la modélisation de bases de données.","de":"Entity Framework Core-Tools sind Satz von CLI-Befehlen und Paket-Manager-Tools, die die Migration und Modellierung von Datenbanken erleichtern.","pt":"Ferramentas de desenvolvimento do EF Core são um conjunto de utilitários para ajudar a configurar e gerenciar o mapeamento de objeto-banco de dados","ru":"Инструменты разработки EF Core — это набор утилит для настройки и управления отображением объектов в базу данных с помощью ИИ Агентов","ar":"أدوات التطوير في EF Core هي مجموعة من البرامج المساعدة لتكوين وإدارة ánh映 الكائنات إلى قاعدة البيانات"},"features":{"en":["Supports dotnet ef CLI for migrations and scaffolding","Utilizes Visual Studio Package Manager Console for compiled models","Includes subcommands like DatabaseCommand, DbContextCommand, and MigrationsCommand","Invokes MSBuild to build and shell for seamless integration","Parses global options like --project and --startup-project for flexible configuration"],"zh":["dotnet ef CLI 命令","Visual Studio Package Manager Console 命令","数据库迁移和模型管理","支持 LINQ 查询和更改跟踪","模式迁移和更新"],"ja":["dotnet ef CLI コマンド","Visual Studio Package Manager Console コマンド","データベース マイグレーションとモデル管理","LINQ クエリと変更の追跡のサポート","スキーマ マイグレーションと更新"],"ko":["dotnet ef CLI 명령","Visual Studio Package Manager Console 명령","데이터베이스 마이그레이션과 모델 관리","LINQ 쿼리와 변경 추적 지원","스키마 마이그레이션과 업데이트"],"es":["Soporte para consultas LINQ","Seguimiento de cambios y actualizaciones","Migraciones de esquemas de base de datos","Comandos CLI para migraciones y modelado","Integración con Visual Studio Package Manager Console","Compatibilidad con .NET Core y .NET Framework"],"fr":["Prise en charge des requêtes LINQ","Suivi des modifications et mises à jour","Migrations de schémas de base de données","Commandes CLI pour les migrations et la modélisation","Intégration avec Visual Studio Package Manager Console","Compatibilité avec .NET Core et .NET Framework"],"de":["Unterstützung für LINQ-Abfragen","Änderungsnachverfolgung und Aktualisierungen","Schemamigrationen von Datenbanken","CLI-Befehle für Migrationen und Modellierung","Integration mit Visual Studio Package Manager Console","Kompatibilität mit .NET Core und .NET Framework"],"pt":["Suporte a consultas LINQ","Rastreamento de alterações e atualizações","Migrações de esquema","Utilitários de linha de comando do dotnet ef","Integração com o Visual Studio Package Manager Console","Comandos personalizados para migrations e scaffolding"],"ru":["Поддержка запросов LINQ","Отслеживание изменений и обновлений","Миграции схемы","Утилиты командной строки dotnet ef","Интеграция с Visual Studio Package Manager Console","Пользовательские команды для migrations и scaffolding с помощью ИИ Агентов"],"ar":["دعم استفسارات LINQ","مراقبة التغييرات والتحديثات","عمليات نقل مخطط القاعدة","برامج مساعدة سطر الأوامر dotnet ef","التكامل مع Visual Studio Package Manager Console","أوامر مخصصة لعمليات نقل البيانات وتجهيز القوالب"]},"keywords":{"en":["how to use tooling with EF Core","tooling vs Entity Framework","dotnet ef CLI tutorial","tooling setup guide for .NET developers","what is tooling in Entity Framework Core","tooling alternative for database management","Entity Framework Core tooling install","tooling best practices for .NET applications"],"zh":["EF Core 工具","dotnet ef CLI","Visual Studio Package Manager Console","数据库迁移","模型管理","LINQ 查询","更改跟踪","模式迁移","更新"],"ja":["EF Core ツール","dotnet ef CLI","Visual Studio Package Manager Console","データベース マイグレーション","モデル管理","LINQ クエリ","変更の追跡","スキーマ マイグレーション","更新"],"ko":["EF Core 도구","dotnet ef CLI","Visual Studio Package Manager Console","데이터베이스 마이그레이션","모델 관리","LINQ 쿼리","변경 추적","스키마 마이그레이션","업데이트"],"es":["Entity Framework Core","herramientas de Entity Framework","mapeador de objetos de base de datos","consultas LINQ","migraciones de esquemas","CLI de Entity Framework","Visual Studio Package Manager Console","desarrollo de .NET","Entity Framework Core para .NET Core","Entity Framework Core para .NET Framework"],"fr":["Entity Framework Core","outils Entity Framework","mappeur d''objets de base de données","requêtes LINQ","migrations de schémas","CLI Entity Framework","Visual Studio Package Manager Console","développement .NET","Entity Framework Core pour .NET Core","Entity Framework Core pour .NET Framework"],"de":["Entity Framework Core","Entity Framework Core-Tools","Objekt-Datenbank-Mapper","LINQ-Abfragen","Schemamigrationen","Entity Framework Core-CLI","Visual Studio Package Manager Console",".NET-Entwicklung","Entity Framework Core für .NET Core","Entity Framework Core für .NET Framework"],"pt":["EF Core","desenvolvimento de software","ferramentas de desenvolvimento","mapeamento de objeto-banco de dados","LINQ","migrações de esquema","dotnet ef","Visual Studio Package Manager Console"],"ru":["EF Core","разработка программного обеспечения","инструменты разработки","отображение объектов в базу данных","LINQ","миграции схемы","dotnet ef","Visual Studio Package Manager Console","ИИ Агенты"],"ar":["EF Core","تطوير البرمجيات","أدوات التطوير"," ánh映 الكائنات إلى قاعدة البيانات","LINQ","عمليات نقل مخطط القاعدة","dotnet ef","Visual Studio Package Manager Console","وكلاء الذكاء الاصطناعي"]}},"owner":"dotnet","repo":"efcore","repoPath":"dotnet/efcore","stars":14598,"forks":3364,"updatedAt":"2026-03-06T22:49:36Z","topics":["aspnet-product","c-sharp","database","dotnet-core","dotnet-framework","dotnet-standard","entity-framework","hacktoberfest","orm"],"category":"community","skillMd":{"name":"tooling","description":"Implementation details for the EF Core dotnet-ef CLI and tooling. Use when changing dotnet-ef commands, the ef wrapper, EFCore.Tools (PMC), or EFCore.Tasks MSBuild integration.","bodyPreview":"# Tooling\n\nThe `dotnet ef` CLI and Visual Studio Package Manager Console commands for migrations, scaffolding, and compiled models.\n\n## dotnet-ef CLI (`src/dotnet-ef/`)\n\n`RootCommand` parses global options (`--project`, `--startup-project`, `--framework`, `--configuration`, `--runtime`, `--no-build`). Subcommands implemented in `src/ef/Commands/` (`Microsoft.EntityFrameworkCore.Tools.Commands`): `DatabaseCommand`, `DbContextCommand`, `MigrationsCommand`. Each invokes MSBuild to build, then shell","body":"# Tooling\n\nThe `dotnet ef` CLI and Visual Studio Package Manager Console commands for migrations, scaffolding, and compiled models.\n\n## dotnet-ef CLI (`src/dotnet-ef/`)\n\n`RootCommand` parses global options (`--project`, `--startup-project`, `--framework`, `--configuration`, `--runtime`, `--no-build`). Subcommands implemented in `src/ef/Commands/` (`Microsoft.EntityFrameworkCore.Tools.Commands`): `DatabaseCommand`, `DbContextCommand`, `MigrationsCommand`. Each invokes MSBuild to build, then shells out via `dotnet exec ef.dll`, which hosts `OperationExecutor`.\n\n## PMC (`src/EFCore.Tools/`)\n\nPowerShell module: `Add-Migration`, `Update-Database`, `Scaffold-DbContext`, `Optimize-DbContext`, etc. Routes to `OperationExecutor`.\n\n## MSBuild Tasks (`src/EFCore.Tasks/`)\n\nNuGet package `Microsoft.EntityFrameworkCore.Tasks` provides build/publish-time compiled model and precompiled query generation.\n\n### Build Integration Flow\n\nTargets in `buildTransitive/Microsoft.EntityFrameworkCore.Tasks.targets`:\n- **Build flow**: `_EFGenerateFilesAfterBuild` triggers after compilation when `EFOptimizeContext=true` and stage is `build`. Invokes `OptimizeDbContext` task, writes generated file list, re-triggers `Build` to compile new files.\n- **Publish flow**: `_EFGenerateFilesBeforePublish` runs before `GeneratePublishDependencyFile`. Auto-activates for `PublishAOT=true`. `_EFPrepareDependenciesForPublishAOT` cascades to project references.\n- **Incremental**: `_EFProcessGeneratedFiles` reads tracking files and adds `.g.cs` to `@(Compile)`. Stale files removed by `_EFPrepareForCompile`.\n- **Clean**: `_EFCleanGeneratedFiles` deletes generated and tracking files.\n\n## Testing\n\n- CLI tests: `test/dotnet-ef.Tests/`, `test/ef.Tests/`\n- EFCore.Tasks has no dedicated test project — for task/target changes, create a test project and manually run `dotnet build` / `dotnet publish` with `EFOptimizeContext=true` to verify\n\n## Validation\n\n- For tool changes, create a test project and manually run affected commands to verify behavior\n- `dotnet ef migrations script` output matches expected DDL"},"lastSynced":"2026-03-07T01:50:07.020Z","agentAnalysis":{"suitability":{"en":"Perfect for .NET Development Agents needing efficient database management using EF Core.","zh":"非常适合需要使用 EF Core 进行高效数据库管理的 .NET 开发代理。","ja":".NET Development Agents が EF Core を使用した効率的なデータベース管理を必要とする場合に最適です。","ko":"EF Core를 사용하여 효율적인 데이터베이스 관리가 필요한 .NET 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de .NET que necesitan una gestión de base de datos eficiente utilizando EF Core.","fr":"Parfait pour les agents de développement .NET ayant besoin d''une gestion de base de données efficace à l''aide d''EF Core.","de":"Perfekt für .NET-Entwicklungsagenten, die eine effiziente Datenbankverwaltung mit EF Core benötigen.","pt":"Perfeito para Agentes de Desenvolvimento .NET que necessitam de gerenciamento de banco de dados eficiente usando EF Core.","ru":"Идеально подходит для агентов разработки .NET, требующих эффективного управления базами данных с использованием EF Core.","ar":"مثالي لعميل تطوير .NET الذين يحتاجون إلى إدارة قواعد البيانات بكفاءة باستخدام EF Core."},"recommendation":{"en":"Empowers agents to manage databases efficiently using LINQ queries, change tracking, and schema migrations with the dotnet-ef CLI and Visual Studio Package Manager Console commands, supporting MSBuild and compiled models.","zh":"赋予代理使用 LINQ 查询、更改跟踪和模式迁移的能力，使用 dotnet-ef CLI 和 Visual Studio 包管理器控制台命令，支持 MSBuild 和编译模型。","ja":"LINQ クエリ、変更追跡、スキーマ マイグレーションを使用してエージェントがデータベースを効率的に管理できるようにし、dotnet-ef CLI および Visual Studio パッケージ マネージャー コンソール コマンドを使用して MSBuild およびコンパイル済みモデルをサポートします。","ko":"LINQ 쿼리, 변경 추적 및 스키마 마이그레이션을 사용하여 에이전트가 데이터베이스를 효율적으로 관리할 수 있도록 하며, dotnet-ef CLI 및 Visual Studio 패키지 관리자 콘솔 명령을 사용하여 MSBuild 및 컴파일된 모델을 지원합니다.","es":"Habilita a los agentes a gestionar bases de datos de forma eficiente utilizando consultas LINQ, seguimiento de cambios y migraciones de esquemas con los comandos de la CLI de dotnet-ef y la consola de comandos del Administrador de paquetes de Visual Studio, que admiten MSBuild y modelos compilados.","fr":"Permet aux agents de gérer les bases de données de manière efficace en utilisant des requêtes LINQ, un suivi des modifications et des migrations de schéma avec les commandes de la CLI dotnet-ef et la console de commandes du Gestionnaire de packages Visual Studio, prenant en charge MSBuild et les modèles compilés.","de":"Ermöglicht es den Agenten, Datenbanken effizient zu verwalten, indem sie LINQ-Abfragen, Änderungsverfolgung und Schemamigrationen mit den dotnet-ef-CLI- und Visual-Studio-Paket-Manager-Konsole-Befehlen verwenden, die MSBuild und kompilierte Modelle unterstützen.","pt":"Habilita os agentes a gerenciar bancos de dados de forma eficiente usando consultas LINQ, rastreamento de alterações e migrações de esquema com os comandos dotnet-ef CLI e Console de Gerenciamento de Pacotes do Visual Studio, suportando MSBuild e modelos compilados.","ru":"Наделяет агентов возможностью эффективно управлять базами данных с использованием запросов LINQ, отслеживания изменений и миграций схем с помощью команд dotnet-ef CLI и консоли диспетчера пакетов Visual Studio, поддерживая MSBuild и скомпилированные модели.","ar":"تمكن الوكلاء من إدارة قواعد البيانات بكفاءة باستخدام استفسارات LINQ وتتبع التغييرات وعمليات نقل المخططات باستخدام أوامر dotnet-ef CLI ووحدة تحكم مدير الحزم في Visual Studio، مع دعم MSBuild والنماذج المجمعة."},"useCases":{"en":["Scaffolding database models using dotnet-ef CLI","Managing schema migrations with EF Core","Executing LINQ queries for data analysis"],"zh":["使用 dotnet-ef CLI 搭建数据库模型","使用 EF Core 管理模式迁移","执行 LINQ 查询进行数据分析"],"ja":["dotnet-ef CLI を使用してデータベース モデルをスキャフォールド","EF Core を使用してスキーマ マイグレーションを管理","データ分析のために LINQ クエリを実行"],"ko":["dotnet-ef CLI를 사용하여 데이터베이스 모델 스캐폴딩","EF Core를 사용하여 스키마 마이그레이션 관리","데이터 분석을 위한 LINQ 쿼리 실행"],"es":["Creación de modelos de base de datos con la CLI de dotnet-ef","Administración de migraciones de esquema con EF Core","Ejecución de consultas LINQ para análisis de datos"],"fr":["Création de modèles de base de données à l''aide de la CLI dotnet-ef","Gestion des migrations de schéma avec EF Core","Exécution de requêtes LINQ pour l''analyse de données"],"de":["Erstellung von Datenbankmodellen mit der dotnet-ef-CLI","Verwaltung von Schemamigrationen mit EF Core","Ausführung von LINQ-Abfragen zur Datenanalyse"],"pt":["Criação de modelos de banco de dados usando dotnet-ef CLI","Gerenciamento de migrações de esquema com EF Core","Execução de consultas LINQ para análise de dados"],"ru":["Создание моделей базы данных с помощью dotnet-ef CLI","Управление миграциями схем с помощью EF Core","Выполнение запросов LINQ для анализа данных"],"ar":["إنشاء نماذج قاعدة البيانات باستخدام dotnet-ef CLI","إدارة عمليات نقل المخططات باستخدام EF Core","تنفيذ استفسارات LINQ لتحليل البيانات"]},"limitations":{"en":["Requires .NET Core installation","Specific to EF Core and .NET development"],"zh":[".NET Core 安装要求","特定于 EF Core 和 .NET 开发"],"ja":[".NET Core インストールの要件","EF Core および .NET 開発に特有"],"ko":[".NET Core 설치 요구 사항","EF Core 및 .NET 개발에 특정"],"es":["Requiere instalación de .NET Core","Específico para EF Core y desarrollo de .NET"],"fr":["Nécessite une installation de .NET Core","Spécifique à EF Core et au développement .NET"],"de":["Benötigt .NET-Core-Installation","Spezifisch für EF Core und .NET-Entwicklung"],"pt":["Requer instalação do .NET Core","Específico para EF Core e desenvolvimento .NET"],"ru":["Требует установки .NET Core","Специфичен для EF Core и разработки .NET"],"ar":["يتطلب تثبيت .NET Core","محدد ل EF Core وتطوير .NET"]},"version":4},"contentHash":"477b2212bf343f734e396bb502f77c61de4fe87d841793b2d818f95642da30a3","qualityScore":42}');
