INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jianxcao/qbittorrent-web/vue-best-practices', 'vue-best-practices', 'jianxcao', 'qbittorrent-web', 'community', 'vue-best-practices jianxcao qbittorrent-web community qb qbittorent webui The vue-best-practices skill provides comprehensive development guidelines for Vue 3 applications, including TypeScript configuration and best practices for debugging and optimization. Vue最佳实践为您提供了Vue 3应用的综合开发指南，包括TypeScript配置和Vite集成 Vue Best Practicesは、Vue 3アプリケーションのための包括的な開発ガイドラインを提供します。TypeScript構成やVite統合など Vue 베스트 프랙티스는 Vue 3 애플리케이션을 위한 포괄적인 개발 가이드를 제공하며, TypeScript 구성 및 Vite 통합 등 Este skill proporciona directrices de desarrollo y configuración de TypeScript para aplicaciones Vue 3, incluyendo la integración con Vite y Vue Router Ce skill fournit des directives de développement et de configuration de TypeScript pour les applications Vue 3, y compris l''intégration avec Vite et Vue Router Dieses Skill bietet Entwicklungshinweise und Konfigurationsrichtlinien für TypeScript in Vue 3-Anwendungen, einschließlich der Integration mit Vite und Vue Router O Vue Best Practices é um guia abrangente para desenvolvedores que buscam configurar e otimizar aplicações web com Vue 3 e TypeScript. Vue Best Practices - это комплексное руководство для разработчиков, которые хотят настроить и оптимизировать веб-приложения с Vue 3 и TypeScript. أفضل الممارسات لفيو هي دليل شامل للمطورين الذين يبحثون عن ضبط وتحسين تطبيقات الويب مع فيو 3 وتايب سكريبت. how to use vue-best-practices vue-best-practices setup guide vue 3 typescript configuration vue-best-practices vs vue-cli vue-best-practices install vue router typed routes vitest component testing what is vue-best-practices Vue最佳实践 Vue 3应用 TypeScript配置 Vite集成 Vue Router类型路由 AIエージェント Vue开发指南 Configures Vite for Vue projects Enables typed routes with Vue Router Supports component testing with Vitest Utilizes Composition API patterns Works with defineModel, defineProps, and defineExpose Integrates with Volar for IDE/editor support vue-best-practices is a set of guidelines and configurations for building robust and maintainable Vue 3 applications with TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aalmada/BookStore/frontend__debug_sse', 'community', 'aalmada', 'BookStore', 'aalmada/BookStore', 'frontend__debug_sse', 15, 0, 42, '2026-02-20T19:40:57Z', '2026-03-06T06:43:47.599Z', '7e212838ed784d1a41dcc1880c73db777d7e5411a7098d132f5184aa0c396557', '{"id":"aalmada/BookStore/frontend__debug_sse","name":"frontend__debug_sse","description":{"en":"The frontend__debug_sse skill helps developers troubleshoot Server-Sent Events issues in full-stack .NET applications with Blazor frontend and event-sourced backend API. It benefits developers using Aspire, .NET Core, and Postgres.","zh":"此 AI 工具提供 Server-Sent Events 调试指南，帮助您解决 SSE 问题","ja":"この AI ツールは Server-Sent Events のデバッグ ガイドを提供し、SSE の問題を解決するのに役立ちます","ko":"이 AI 도구는 Server-Sent Events 디버깅 가이드를 제공하여 SSE 문제를 해결하는 데 도움이 됩니다","es":"Esta guía de depuración de frontend__debug_sse ayuda a solucionar problemas de Eventos de Servidor en aplicaciones .NET con Blazor y Aspire.","fr":"Ce guide de débogage de frontend__debug_sse aide à résoudre les problèmes d''événements serveur dans les applications .NET avec Blazor et Aspire.","de":"Dieser Debug-Leitfaden für frontend__debug_sse hilft bei der Fehlerbehebung von Server-Sent Events in .NET-Anwendungen mit Blazor und Aspire.","pt":"O frontend__debug_sse é uma habilidade para depurar problemas de Server-Sent Events no frontend de uma aplicação .NET Core com Blazor e event-sourcing.","ru":"Фронтенд__дебаг_ссе - это навык для отладки проблем Server-Sent Events в frontend приложения .NET Core с Blazor и event-sourcing, используя ИИ Агенты","ar":"واجهة المستخدم الأمامية__debug_sse هي مهارة لتصحيح أخطاء Server-Sent Events في واجهة المستخدم الأمامية لتطبيق .NET Core مع Blazor و event-sourcing، باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"frontend__debug_sse: Server-Sent Events Debugging Setup G...","zh":"AIエージェント：Server-Sent Events 调试设置指南","ja":"AIエージェント：Server-Sent Events デバッグセットアップガイド","ko":"AI 에이전트: 서버-SENT 이벤트 디버깅 설정 가이드","es":"Guía de configuración de frontend__debug_sse para solucio...","fr":"Guide de configuration de frontend__debug_sse pour dépann...","de":"Einrichtungsanleitung für frontend__debug_sse zur Fehlerb...","pt":"Guia de Depuração de Eventos de Servidor para Frontend","ru":"Руководство по отладке серверных событий для frontend с И...","ar":"دليل حل المشكلات ل事件ات الخادم الأمامي باستخدام أدوات الذك..."},"description":{"en":"Troubleshoot Server-Sent Events issues with this step-by-step guide for .NET and Blazor applications, featuring Aspire and event-sourced backend API","zh":"使用此 AI 工具调试 Server-Sent Events 问题，包括测试 SSE 端点、检查 ProjectionCommitListener 和 QueryInvalidationService","ja":"この AI ツールを使用して Server-Sent Events の問題をデバッグします。SSE エンドポイントのテスト、ProjectionCommitListener と QueryInvalidationService の確認を含みます","ko":"이 AI 도구를 사용하여 Server-Sent Events 문제를 디버깅합니다. SSE 엔드ポイント 테스트, ProjectionCommitListener 및 QueryInvalidationService 확인 포함","es":"Aprende a solucionar problemas comunes de Eventos de Servidor en aplicaciones .NET con Blazor y Aspire con esta guía de depuración","fr":"Découvrez comment résoudre les problèmes courants d''événements serveur dans les applications .NET avec Blazor et Aspire grâce à ce guide de débogage","de":"Erfahren Sie, wie Sie häufige Probleme mit Server-Sent Events in .NET-Anwendungen mit Blazor und Aspire mithilfe dieses Debug-Leitfadsens lösen","pt":"Aprenda a depurar problemas de Server-Sent Events no frontend com nossa guia passo a passo, incluindo testes de endpoint e verificação de serviços","ru":"Узнайте, как устранять неполадки Server-Sent Events в frontend с помощью нашей пошаговой инструкции, включая тестирование точек подключения и проверку сервис...","ar":"تعلم كيفية حل مشكلات Server-Sent Events في واجهة المستخدم الأمامية باستخدام دليلنا خطوة بخطوة، بما في ذلك اختبار نهاية ونقاط التحقق من الخدمات مع أدوات الذكا..."},"definition":{"en":"frontend__debug_sse is a debugging tool for troubleshooting Server-Sent Events issues in .NET applications with Blazor frontend and event-sourced backend API","zh":"Server-Sent Events 调试是指使用 AI 工具来诊断和解决 SSE 问题的过程","ja":"Server-Sent Events デバッグとは、AI ツールを使用して SSE の問題を診断および解決するプロセスです","ko":"서버-SENT 이벤트 디버깅은 AI 도구를 사용하여 SSE 문제를 진단하고 해결하는 프로세스입니다","es":"frontend__debug_sse es una herramienta de depuración para solucionar problemas de Eventos de Servidor en aplicaciones .NET","fr":"frontend__debug_sse est un outil de débogage pour résoudre les problèmes d''événements serveur dans les applications .NET","de":"frontend__debug_sse ist ein Debug-Tool zur Fehlerbehebung von Server-Sent Events in .NET-Anwendungen","pt":"O que é frontend__debug_sse? É uma habilidade para depurar problemas de Server-Sent Events no frontend de uma aplicação .NET Core.","ru":"Что такое фронтенд__дебаг_ссе? Это навык для отладки проблем Server-Sent Events в frontend приложения .NET Core с ИИ Агентами","ar":"ما هي واجهة المستخدم الأمامية__debug_sse؟ هي مهارة لتصحيح أخطاء Server-Sent Events في واجهة المستخدم الأمامية لتطبيق .NET Core مع أدوات الذكاء الاصطناعي"},"features":{"en":["Tests SSE endpoint using curl command","Checks ProjectionCommitListener for case handling","Verifies QueryInvalidationService mapping for notifications","Ensures ReactiveQuery uses matching query keys","Supports event-sourced backend API with Marten and Postgres","Orchestrated by Aspire for seamless debugging experience"],"zh":["测试 SSE 端点","检查 ProjectionCommitListener","检查 QueryInvalidationService","使用 curl 命令调试 SSE","支持 Blazor 前端和 .NET 后端","集成 Aspire 和 Marten"],"ja":["SSE エンドポイントのテスト","ProjectionCommitListener の確認","QueryInvalidationService の確認","curl コマンドを使用した SSE デバッグ","Blazor フロントエンドと .NET バックエンドのサポート","Aspire と Marten の統合"],"ko":["SSE 엔드ポイント 테스트","ProjectionCommitListener 확인","QueryInvalidationService 확인","curl 명령을 사용한 SSE 디버깅","Blazor 프론트엔드와 .NET 백엔드 지원","Aspire 및 Marten 통합"],"es":["Pruebas de puntos de conexión de Eventos de Servidor con curl","Verificación de ProjectionCommitListener para proyecciones personalizadas","Configuración de QueryInvalidationService para notificaciones y claves de consulta","Uso de ReactiveQuery con claves de consulta coincidentes","Integración con Blazor y Aspire para aplicaciones .NET","Soporte para PostgreSQL y Marten"],"fr":["Tests de points de terminaison d''événements serveur avec curl","Vérification de ProjectionCommitListener pour les projections personnalisées","Configuration de QueryInvalidationService pour les notifications et les clés de requête","Utilisation de ReactiveQuery avec des clés de requête correspondantes","Intégration avec Blazor et Aspire pour les applications .NET","Prise en charge de PostgreSQL et Marten"],"de":["Tests von Server-Sent-Events-Endpunkten mit curl","Überprüfung von ProjectionCommitListener für benutzerdefinierte Projections","Konfiguration von QueryInvalidationService für Benachrichtigungen und Abfrageschlüssel","Verwendung von ReactiveQuery mit übereinstimmenden Abfrageschlüsseln","Integration mit Blazor und Aspire für .NET-Anwendungen","Unterstützung für PostgreSQL und Marten"],"pt":["Teste de endpoint de Server-Sent Events","Verificação de ProjectionCommitListener","Verificação de QueryInvalidationService","Uso de ReactiveQuery com queryKeys","Integração com Blazor e event-sourcing","Suporte a .NET Core"],"ru":["Тестирование точки подключения Server-Sent Events","Проверка ProjectionCommitListener","Проверка QueryInvalidationService","Использование ReactiveQuery с queryKeys","Интеграция с Blazor и event-sourcing","Поддержка .NET Core с ИИ Агентами"],"ar":["اختبار نهاية Server-Sent Events","التحقق من ProjectionCommitListener","التحقق من QueryInvalidationService","استخدام ReactiveQuery مع queryKeys","التكامل مع Blazor و event-sourcing","دعم .NET Core مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use frontend__debug_sse","frontend__debug_sse setup guide","troubleshooting Server-Sent Events in .NET","Aspire debugging tools","Blazor frontend debugging","event-sourced backend API troubleshooting","frontend__debug_sse vs traditional debugging methods","install frontend__debug_sse","frontend__debug_sse alternative solutions"],"zh":["Server-Sent Events 调试","SSE 问题解决","AI 工具","Blazor",".NET","Aspire","Marten","curl 命令","ProjectionCommitListener","QueryInvalidationService"],"ja":["Server-Sent Events デバッグ","SSE の問題解決","AI ツール","Blazor",".NET","Aspire","Marten","curl コマンド","ProjectionCommitListener","QueryInvalidationService"],"ko":["서버-SENT 이벤트 디버깅","SSE 문제 해결","AI 도구","Blazor",".NET","Aspire","Marten","curl 명령","ProjectionCommitListener","QueryInvalidationService"],"es":["depuración de Eventos de Servidor","frontend__debug_sse","Blazor","Aspire","aplicaciones .NET","Server-Sent Events","curl","ProjectionCommitListener","QueryInvalidationService","ReactiveQuery"],"fr":["débogage d''événements serveur","frontend__debug_sse","Blazor","Aspire","applications .NET","événements serveur","curl","ProjectionCommitListener","QueryInvalidationService","ReactiveQuery"],"de":["Fehlerbehebung von Server-Sent Events","frontend__debug_sse","Blazor","Aspire",".NET-Anwendungen","Server-Sent Events","curl","ProjectionCommitListener","QueryInvalidationService","ReactiveQuery"],"pt":["depuração de eventos de servidor","frontend debug","Server-Sent Events",".NET Core","Blazor","event-sourcing","ReactiveQuery","ProjectionCommitListener","QueryInvalidationService"],"ru":["отладка серверных событий","фронтенд дебаг","Server-Sent Events",".NET Core","Blazor","event-sourcing","ReactiveQuery","ProjectionCommitListener","QueryInvalidationService","ИИ Агенты"],"ar":["تصحيح أخطاء事件ات الخادم","واجهة المستخدم الأمامية دебاج","Server-Sent Events",".NET Core","Blazor","event-sourcing","ReactiveQuery","ProjectionCommitListener","QueryInvalidationService","أدوات الذكاء الاصطناعي"]}},"owner":"aalmada","repo":"BookStore","repoPath":"aalmada/BookStore","stars":15,"forks":0,"updatedAt":"2026-02-20T19:40:57Z","topics":["aspire","aspire-dotnet","blazor","cqrs","dotnet","dotnet-core","dotnetcore","event-sourcing","example","marten","postgres","wolverine"],"category":"community","skillMd":{"name":"frontend__debug_sse","description":"Debug Server-Sent Events (SSE) notification issues when real-time updates arent working. Use this when mutations dont trigger frontend updates.","bodyPreview":"Use this guide to troubleshoot Server-Sent Events (SSE) issues.\n\n## Quick Path (80% of issues)\n\n// turbo\n1. **Test SSE endpoint**:\n   ```bash\n   curl -N -H \"Accept: text/event-stream\" http://localhost:5000/api/notifications/stream\n   ```\n   Should see: `data: {\"type\":\"Connected\",...}`\n\n2. **Check ProjectionCommitListener** has case for your projection\n3. **Check QueryInvalidationService** maps notification to query keys\n4. **Check ReactiveQuery** uses matching `queryKeys`\n\nIf still broken, conti","body":"Use this guide to troubleshoot Server-Sent Events (SSE) issues.\n\n## Quick Path (80% of issues)\n\n// turbo\n1. **Test SSE endpoint**:\n   ```bash\n   curl -N -H \"Accept: text/event-stream\" http://localhost:5000/api/notifications/stream\n   ```\n   Should see: `data: {\"type\":\"Connected\",...}`\n\n2. **Check ProjectionCommitListener** has case for your projection\n3. **Check QueryInvalidationService** maps notification to query keys\n4. **Check ReactiveQuery** uses matching `queryKeys`\n\nIf still broken, continue to full debugging below.\n\n---\n\n## Symptoms\n\n- ✗ Frontend doesn''t update after mutation\n- ✗ `ReactiveQuery` doesn''t invalidate\n- ✗ SSE connection fails or disconnects\n- ✗ Events not received in browser\n\n## Related Skills\n\n**Prerequisites**:\n- `/aspire__start_solution` - Solution must be running to debug SSE\n\n**First Steps**:\n- `/test__verify_feature` - Run basic checks (build, tests) before deep debugging\n\n**Related Debugging**:\n- `/cache__debug_cache` - If issue seems cache-related instead of SSE\n- `/ops__doctor_check` - Check if environment setup is correct\n\n**After Fixing**:\n- `/test__verify_feature` - Confirm fix works\n- `/test__integration_scaffold` - Add tests to prevent regression\n\n## Debugging Steps\n\n### 1. Verify SSE Endpoint is Working\n\nTest the SSE endpoint directly:\n\n```bash\n# Terminal 1: Connect to SSE stream\ncurl -N -H \"Accept: text/event-stream\" http://localhost:5000/api/notifications/stream\n```\n\nYou should see:\n```\n: connected\n\ndata: {\"type\":\"Connected\",\"timestamp\":\"2026-01-15T20:00:00Z\"}\n```\n\n**If connection fails**:\n- ✗ Check API service is running\n- ✗ Verify `/api/notifications/stream` endpoint exists in `NotificationEndpoints.cs`\n- ✗ Check firewall/network issues\n\n### 2. Verify Notifications Are Defined\n\nCheck `src/Shared/BookStore.Shared/Notifications/DomainEventNotifications.cs`:\n\n```csharp\n// ✅ Correct - implements IDomainEventNotification\npublic record BookCreatedNotification(Guid Id, string Title) : IDomainEventNotification;\n\n// ✗ Wrong - missing interface\npublic record BookCreatedNotification(Guid Id, string Title);\n```\n\n**If notification is missing**:\n1. Create notification in `DomainEventNotifications.cs`\n2. Implement `IDomainEventNotification` interface\n3. Include all data needed for frontend invalidation\n\n### 3. Verify ProjectionCommitListener Configuration\n\nOpen `src/BookStore.ApiService/Infrastructure/MartenCommitListener.cs`:\n\n**Check if your projection has a handler**:\n\n```csharp\nprivate async Task ProcessDocumentChangeAsync(\n    IDocumentChange change,\n    CancellationToken cancellationToken)\n{\n    switch (change)\n    {\n        case BookProjection proj:\n            await HandleBookChangeAsync(proj, cancellationToken);\n            break;\n\n        // ❌ Missing: Your projection case\n        case AuthorProjection proj:\n            await HandleAuthorChangeAsync(proj, cancellationToken);\n            break;\n    }\n}\n```\n\n**Check if handler sends notification**:\n\n```csharp\nprivate async Task HandleBookChangeAsync(\n    BookProjection book,\n    CancellationToken cancellationToken)\n{\n    var notification = new BookUpdatedNotification(book.Id, book.Title);\n\n    // ✅ Correct - sends notification\n    await _notificationService.NotifyAsync(notification, cancellationToken);\n\n    // ✗ Wrong - forgot to send\n    // (no NotifyAsync call)\n}\n```\n\n**If handler is missing**:\n1. Add case for your projection\n2. Create handler method that calls `NotifyAsync`\n3. Use appropriate notification type\n\n### 4. Verify QueryInvalidationService Mapping\n\nOpen `src/Web/BookStore.Web/Services/QueryInvalidationService.cs`:\n\n**Check if notification maps to query keys**:\n\n```csharp\nIEnumerable<string> GetInvalidationKeys(IDomainEventNotification notification)\n{\n    switch (notification)\n    {\n        case BookCreatedNotification n:\n            yield return \"Books\";\n            yield return $\"Book:{n.EntityId}\";\n            break;\n        case BookUpdatedNotification n:\n            yield return \"Books\";\n            yield return $\"Book:{n.EntityId}\";\n            break;\n\n        // ❌ Missing: Your notification\n        case AuthorUpdatedNotification n:\n            yield return \"Authors\";\n            yield return $\"Author:{n.EntityId}\";\n            break;\n    }\n}\n```\n\n**If mapping is missing**:\n1. Add case for your notification type\n2. Yield return query keys that should be invalidated\n3. Match keys used in `ReactiveQuery` setup\n\n### 5. Verify Frontend BookStoreEventsService\n\nCheck browser console for SSE connection:\n\n**In Chrome DevTools**:\n1. Open Network tab\n2. Look for \"events\" request (type: eventsource)\n3. Check status is \"pending\" (active connection)\n4. View \"EventStream\" tab to see events\n\n**If connection is closed**:\n- Check `BookStoreEventsService.StartListening()` is called in `OnInitializedAsync`\n- Verify base URL is correct\n- Check for JavaScript errors\n\n### 6. Verify ReactiveQuery Configuration\n\nCheck component using `ReactiveQuery`:\n\n```csharp\n// ✅ Correct - query keys match invalidation mapping\nbookQuery = new ReactiveQuery<PagedListDto<BookDto>>(\n    queryFn: FetchBooksAsync,\n    eventsService: BookStoreEventsService,\n    invalidationService: InvalidationService,\n    queryKeys: new[] { \"Books\" },  // Matches QueryInvalidationService\n    onStateChanged: StateHasChanged,\n    logger: Logger\n);\n\n// ✗ Wrong - query keys don''t match\nqueryKeys: new[] { \"AllBooks\" }  // Doesn''t match \"Books\"\n```\n\n**If query doesn''t invalidate**:\n1. Ensure `queryKeys` match `QueryInvalidationService` mapping\n2. Verify `BookStoreEventsService` is subscribed\n3. Check `onStateChanged` callback is provided\n\n### 7. Test End-to-End\n\nPerform a mutation and watch the flow:\n\n```bash\n# Terminal 1: Watch SSE stream\ncurl -N -H \"Accept: text/event-stream\" http://localhost:5000/api/notifications/stream\n\n# Terminal 2: Trigger mutation\ncurl -X POST http://localhost:5000/api/admin/books \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"title\":\"Test Book\",...}''\n```\n\n**Expected flow**:\n1. Command executed\n2. Event stored in Marten\n3. `ProjectionCommitListener` triggered\n4. Notification sent via SSE\n5. Browser receives event\n6. `QueryInvalidationService` maps to keys\n7. `ReactiveQuery` invalidates\n8. Query refetches\n9. UI updates\n\n**If any step fails**, locate where:\n- Check logs in Aspire dashboard\n- Add debug logging to `ProjectionCommitListener`\n- Use browser console to see received events\n\n## Common Issues & Fixes\n\n### Issue: Events Not Sent\n\n**Symptom**: ProjectionCommitListener not triggered\n\n**Fix**:\n- Ensure `ProjectionCommitListener` is registered in DI\n- Check Marten event store configuration\n- Verify projection lifecycle (`Inline` vs `Async`)\n\n### Issue: Wrong Event Type\n\n**Symptom**: Notification sent but frontend doesn''t invalidate\n\n**Fix**:\n```csharp\n// Check notification type name matches exactly\ncase \"BookUpdatedNotification\":  // ✅ Correct\ncase \"BookUpdated\":              // ✗ Wrong\n```\n\n### Issue: Multiple Tabs Don''t Update\n\n**Symptom**: Updates only visible in tab that made change\n\n**Fix**:\n- SSE works per-connection, each tab needs own connection\n- Each tab should call `BookStoreEventsService.StartListening()`\n- Verify SignalR isn''t being used (project uses SSE)\n\n### Issue: SSE Connection Drops\n\n**Symptom**: Connection works then stops\n\n**Fix**:\n- Check server-side timeout configuration\n- Verify no proxy/load balancer kills long connections\n- Add reconnection logic in `BookStoreEventsService`\n\n## Verification Checklist\n\n- [ ] SSE endpoint accessible at `/api/notifications/stream`\n- [ ] Notification class implements `IDomainEventNotification`\n- [ ] `ProjectionCommitListener` has handler for projection\n- [ ] Handler calls `NotifyAsync` with notification\n- [ ] `QueryInvalidationService` maps notification to keys\n- [ ] Frontend `ReactiveQuery` uses matching query keys\n- [ ] `BookStoreEventsService.StartListening()` called on mount\n- [ ] Browser DevTools shows active EventSource connection\n- [ ] End-to-end test confirms UI updates after mutation\n\n## Debugging Tools\n\n**Backend**:\n- Aspire Dashboard → Structured Logs → Filter by \"notification\"\n- Add logging in `ProjectionCommitListener`: `_logger.LogInformation(\"Sending {Type}\", notification.GetType().Name)`\n\n**Frontend**:\n- Browser Console → Look for EventSource logs\n- React DevTools → Check component re-renders\n- Network tab → Verify EventSource connection\n\n## Related Skills\n\n**First Steps**:\n- `/test__verify_feature` - Run basic checks (build, tests) before deep debugging\n\n**Related Debugging**:\n- `/cache__debug_cache` - If issue seems cache-related instead of SSE\n- `/ops__doctor_check` - Check if environment setup is correct\n\n**After Fixing**:\n- `/test__verify_feature` - Confirm fix works\n- `/test__integration_scaffold` - Add tests to prevent regression\n\n**See Also**:\n- [wolverine__create_operation](../wolverine__create_operation/SKILL.md) - SSE notification setup in ProjectionCommitListener\n- [frontend__feature_scaffold](../frontend__feature_scaffold/SKILL.md) - Frontend SSE integration\n- [real-time-notifications](../../../docs/guides/real-time-notifications.md) - SSE architecture and data flow\n- ApiService AGENTS.md - Backend notification patterns\n- Web AGENTS.md - Frontend SSE patterns\n"},"lastSynced":"2026-03-06T06:43:47.599Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing advanced Server-Sent Events troubleshooting in .NET applications with Blazor frontend and event-sourced backend API.","zh":"非常适合需要在具有Blazor前端和事件源后端API的.NET应用程序中高级Server-Sent Events故障排除的全栈代理。","ja":"BlazorフロントエンドとイベントソースバックエンドAPIを備えた.NETアプリケーションで高度なServer-Sent Eventsのトラブルシューティングを必要とするフルスタックエージェントに最適です。","ko":"Blazor 프론트엔드와 이벤트 소스 백엔드 API를備えた .NET 애플리케이션에서 고급 Server-Sent Events 문제 해결을 필요로하는 풀스택 에이전트에게 적합합니다.","es":"Perfecto para agentes Full-Stack que necesitan solucionar problemas avanzados de eventos enviados por el servidor en aplicaciones .NET con frontend Blazor y API de backend con eventos registrados.","fr":"Parfait pour les agents Full-Stack qui ont besoin de dépanner les événements envoyés par le serveur dans les applications .NET avec un frontend Blazor et une API de backend basée sur les événements.","de":"Perfekt für Full-Stack-Agents, die erweiterte Fehlersuche für Server-Sent-Events in .NET-Anwendungen mit Blazor-Frontend und ereignisgesteuertem Backend-API benötigen.","pt":"Perfeito para Agentes Full-Stack que precisam de solução de problemas avançados de Eventos Enviados pelo Servidor em aplicações .NET com frontend Blazor e backend API orientado a eventos.","ru":"Идеально подходит для полнофункциональных агентов, которым требуются расширенные возможности устранения неполадок с Server-Sent Events в приложениях .NET с frontend Blazor и backend API, ориентированным на события.","ar":"مثالي لعميل برمجي كامل النطاق الذي يحتاج إلى تشخيص متقدم لأحداث الإرسال من parte الخادم في تطبيقات .NET مع واجهة المستخدم Blazor وخلفية واجهة برمجة التطبيقات الموجهة بالأحداث."},"recommendation":{"en":"Empowers agents to debug Server-Sent Events issues using curl for endpoint testing, and verify ProjectionCommitListener, QueryInvalidationService, and ReactiveQuery configurations, ensuring seamless event-driven communication between the frontend and backend using protocols like HTTP and technologies such as Aspire, .NET Core, and Postgres.","zh":"赋予代理人使用curl进行端点测试、验证ProjectionCommitListener、QueryInvalidationService和ReactiveQuery配置的能力，确保使用HTTP等协议和Aspire、.NET Core、Postgres等技术的前端和后端之间的无缝事件驱动通信。","ja":"エージェントがcurlを使用してエンドポイントをテストし、ProjectionCommitListener、QueryInvalidationService、ReactiveQueryの構成を検証する能力を提供し、HTTPなどのプロトコルやAspire、.NET Core、Postgresなどのテクノロジーを使用したフロントエンドとバックエンドの間のシームレスなイベント駆動通信を保証します。","ko":"에이전트가 curl을 사용하여 엔드포인트를 테스트하고 ProjectionCommitListener, QueryInvalidationService 및 ReactiveQuery 구성 검증을 수행하여 HTTP와 같은 프로토콜 및 Aspire, .NET Core, Postgres와 같은 기술을 사용하는 프론트엔드와 백엔드 간의 무결점 이벤트 주도 통신을 보장합니다.","es":"Habilita a los agentes a depurar problemas de eventos enviados por el servidor utilizando curl para pruebas de puntos de conexión y verificar las configuraciones de ProjectionCommitListener, QueryInvalidationService y ReactiveQuery, garantizando una comunicación basada en eventos sin problemas entre el frontend y el backend utilizando protocolos como HTTP y tecnologías como Aspire, .NET Core y Postgres.","fr":"Permet aux agents de dépanner les problèmes d''événements envoyés par le serveur en utilisant curl pour les tests de points de terminaison et en vérifiant les configurations de ProjectionCommitListener, QueryInvalidationService et ReactiveQuery, garantissant une communication basée sur les événements sans problème entre le frontend et le backend en utilisant des protocoles tels que HTTP et des technologies telles que Aspire, .NET Core et Postgres.","de":"Ermächtigt Agenten, Server-Sent-Events-Probleme mithilfe von curl für Endpunkte-Tests und Überprüfung der Konfigurationen von ProjectionCommitListener, QueryInvalidationService und ReactiveQuery zu debuggen, um eine reibungslose ereignisgesteuerte Kommunikation zwischen Frontend und Backend unter Verwendung von Protokollen wie HTTP und Technologien wie Aspire, .NET Core und Postgres sicherzustellen.","pt":"Habilita os agentes a depurar problemas de Eventos Enviados pelo Servidor usando curl para testar pontos de extremidade e verificar as configurações de ProjectionCommitListener, QueryInvalidationService e ReactiveQuery, garantindo uma comunicação baseada em eventos sem problemas entre o frontend e o backend usando protocolos como HTTP e tecnologias como Aspire, .NET Core e Postgres.","ru":"Наделяет агентов возможностью отладки проблем с Server-Sent Events с помощью curl для тестирования конечных точек и проверки конфигураций ProjectionCommitListener, QueryInvalidationService и ReactiveQuery, обеспечивая бесперебойную связь, основанную на событиях, между frontend и backend с использованием протоколов, таких как HTTP, и технологий, таких как Aspire, .NET Core и Postgres.","ar":"يمنح الوكيل القدرة على تصحيح أخطاء حدث الإرسال من parte الخادم باستخدام curl لاختبار نقاط النهاية والتحقق من إعدادات ProjectionCommitListener و QueryInvalidationService و ReactiveQuery، مما يضمن التواصل السلس الذي يعتمد على الأحداث بين واجهة المستخدم وخلفية واجهة برمجة التطبيقات باستخدام بروتوكولات مثل HTTP وتقنيات مثل Aspire و .NET Core و Postgres."},"useCases":{"en":["Debugging Server-Sent Events endpoints with curl","Verifying ProjectionCommitListener for custom projection cases","Validating QueryInvalidationService notification mappings to query keys","Troubleshooting ReactiveQuery issues with mismatched query keys"],"zh":["使用curl调试Server-Sent Events端点","验证ProjectionCommitListener用于自定义投影情况","验证QueryInvalidationService通知映射到查询键","排除ReactiveQuery问题与不匹配的查询键"],"ja":["curlを使用してServer-Sent Eventsエンドポイントをデバッグする","ProjectionCommitListenerをカスタム投影ケースに使用して検証する","QueryInvalidationServiceの通知マッピングをクエリキーに検証する","不一致のクエリキーでReactiveQueryの問題をトラブルシューティングする"],"ko":["curl을 사용하여 Server-Sent Events 엔드포인트 디버깅","ProjectionCommitListener를 사용하여 사용자 지정 투영 사례를 검증","QueryInvalidationService 알림 매핑을 쿼리 키에 대한 유효성 검사","일치하지 않는 쿼리 키로 인한 ReactiveQuery 문제 해결"],"es":["Depuración de puntos de conexión de eventos enviados por el servidor con curl","Verificación de ProjectionCommitListener para casos de proyección personalizados","Validación de asignaciones de notificación de QueryInvalidationService a claves de consulta","Solución de problemas de ReactiveQuery con claves de consulta no coincidentes"],"fr":["Dépannage des points de terminaison d''événements envoyés par le serveur avec curl","Vérification de ProjectionCommitListener pour les cas de projection personnalisés","Validation des mappages de notification de QueryInvalidationService aux clés de requête","Dépannage des problèmes de ReactiveQuery avec des clés de requête non correspondantes"],"de":["Fehlersuche für Server-Sent-Events-Endpunkte mit curl","Überprüfung von ProjectionCommitListener für benutzerdefinierte Projektionen","Validierung von QueryInvalidationService-Benachrichtigungszuordnungen zu Abfrageschlüsseln","Fehlersuche für ReactiveQuery-Probleme mit nicht übereinstimmenden Abfrageschlüsseln"],"pt":["Depuração de pontos de extremidade de Eventos Enviados pelo Servidor com curl","Verificação de ProjectionCommitListener para casos de projeção personalizados","Validação de mapeamentos de notificação do QueryInvalidationService para chaves de consulta","Solução de problemas do ReactiveQuery com chaves de consulta não correspondentes"],"ru":["Отладка конечных точек Server-Sent Events с помощью curl","Проверка ProjectionCommitListener для пользовательских случаев проекции","Проверка сопоставлений уведомлений QueryInvalidationService с ключами запроса","Устранение неполадок ReactiveQuery с несоответствующими ключами запроса"],"ar":["تصحيح أخطاء نقاط النهاية لأحداث الإرسال من parte الخادم مع curl","التحقق من ProjectionCommitListener لحالات المشروع المخصصة","التحقق من مapeamentos الإشعار ل QueryInvalidationService إلى مفاتيح الاستعلام","تصحيح أخطاء ReactiveQuery مع مفاتيح الاستعلام غير المتوافقة"]},"limitations":{"en":["Requires .NET Core and Blazor setup","Specific to Server-Sent Events (SSE) protocol","Dependent on Aspire and Postgres for full functionality"],"zh":[".NET Core和Blazor设置是必需的","特定于Server-Sent Events（SSE）协议","依赖于Aspire和Postgres以实现全部功能"],"ja":[".NET CoreとBlazorの設定が必要","Server-Sent Events（SSE）プロトコルに特有","AspireとPostgresに依存して完全な機能を実現"],"ko":[".NET Core 및 Blazor 설정이 필요","Server-Sent Events(SSE) 프로토콜에 특정","Aspire 및 Postgres에 의존하여 전체 기능을 구현"],"es":["Requiere configuración de .NET Core y Blazor","Específico del protocolo de eventos enviados por el servidor (SSE)","Dependiente de Aspire y Postgres para la funcionalidad completa"],"fr":["Nécessite une configuration .NET Core et Blazor","Spécifique au protocole d''événements envoyés par le serveur (SSE)","Dépendant d''Aspire et de Postgres pour une fonctionnalité complète"],"de":["Benötigt .NET Core- und Blazor-Setup","Spezifisch für das Server-Sent-Events-Protokoll (SSE)","Abhängig von Aspire und Postgres für die volle Funktionalität"],"pt":["Exige configuração .NET Core e Blazor","Específico para o protocolo Server-Sent Events (SSE)","Dependente de Aspire e Postgres para funcionalidade completa"],"ru":["Требует настройки .NET Core и Blazor","Специфичен для протокола Server-Sent Events (SSE)","Зависит от Aspire и Postgres для полной функциональности"],"ar":["يتطلب إعداد .NET Core و Blazor","محدد لبروتوكول أحداث الإرسال من parte الخادم (SSE)","يعتمد على Aspire و Postgres من أجل الوظيفة الكاملة"]},"version":4},"contentHash":"7e212838ed784d1a41dcc1880c73db777d7e5411a7098d132f5184aa0c396557","qualityScore":42}');
