INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aalmada/BookStore/frontend__debug_sse', 'frontend__debug_sse', 'aalmada', 'BookStore', 'community', 'frontend__debug_sse aalmada BookStore community aspire aspire-dotnet blazor cqrs dotnet dotnet-core dotnetcore event-sourcing example marten postgres wolverine The frontend__debug_sse skill helps developers troubleshoot Server-Sent Events issues in full-stack .NET applications with Blazor frontend and event-sourced backend API. It benefits developers using Aspire, .NET Core, and Postgres. 此 AI 工具提供 Server-Sent Events 调试指南，帮助您解决 SSE 问题 この AI ツールは Server-Sent Events のデバッグ ガイドを提供し、SSE の問題を解決するのに役立ちます 이 AI 도구는 Server-Sent Events 디버깅 가이드를 제공하여 SSE 문제를 해결하는 데 도움이 됩니다 Esta guía de depuración de frontend__debug_sse ayuda a solucionar problemas de Eventos de Servidor en aplicaciones .NET con Blazor y Aspire. Ce guide de débogage de frontend__debug_sse aide à résoudre les problèmes d''événements serveur dans les applications .NET avec Blazor et Aspire. Dieser Debug-Leitfaden für frontend__debug_sse hilft bei der Fehlerbehebung von Server-Sent Events in .NET-Anwendungen mit Blazor und Aspire. O frontend__debug_sse é uma habilidade para depurar problemas de Server-Sent Events no frontend de uma aplicação .NET Core com Blazor e event-sourcing. Фронтенд__дебаг_ссе - это навык для отладки проблем Server-Sent Events в frontend приложения .NET Core с Blazor и event-sourcing, используя ИИ Агенты واجهة المستخدم الأمامية__debug_sse هي مهارة لتصحيح أخطاء Server-Sent Events في واجهة المستخدم الأمامية لتطبيق .NET Core مع Blazor و event-sourcing، باستخدام أدوات الذكاء الاصطناعي how to use frontend__debug_sse frontend__debug_sse setup guide troubleshooting Server-Sent Events in .NET Aspire debugging tools Blazor frontend debugging event-sourced backend API troubleshooting frontend__debug_sse vs traditional debugging methods install frontend__debug_sse frontend__debug_sse alternative solutions Server-Sent Events 调试 SSE 问题解决 AI 工具 Blazor .NET Aspire Marten curl 命令 ProjectionCommitListener QueryInvalidationService Tests SSE endpoint using curl command Checks ProjectionCommitListener for case handling Verifies QueryInvalidationService mapping for notifications Ensures ReactiveQuery uses matching query keys Supports event-sourced backend API with Marten and Postgres Orchestrated by Aspire for seamless debugging experience frontend__debug_sse is a debugging tool for troubleshooting Server-Sent Events issues in .NET applications with Blazor frontend and event-sourced backend API');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sorryhyun/DiPeO/dipeo-backend', 'community', 'sorryhyun', 'DiPeO', 'sorryhyun/DiPeO', 'dipeo-backend', 12, 2, 42, '2026-02-06T07:13:58Z', '2026-03-06T06:44:54.802Z', '385b8298fdd6d15a17afaca6765fd67fe313081962210da9928e8561400ca9af', '{"id":"sorryhyun/DiPeO/dipeo-backend","name":"dipeo-backend","description":{"en":"The dipeo-backend skill provides a block diagram UI for building tools, supporting backend ecosystem development with FastAPI server and CLI tools. It benefits developers working with backend ecosystems.","zh":"Dipeo Backend是一个强大的AI工具构建平台，支持FastAPI服务器、CLI工具和数据库模式初始化","ja":"Dipeo Backendは、AIエージェントの構築を容易にするためのツールを提供するバックエンドエコシステムです","ko":"Dipeo Backend는 AI 에이전트를 위한 백엔드 솔루션으로, FastAPI 서버, CLI 도구, 데이터베이스 스키마 초기화 등을 지원합니다","es":"DiPeO Backend es una herramienta para crear agentes de inteligencia artificial mediante una interfaz de usuario de block diagram. Incluye un servidor FastAPI y herramientas de línea de comandos.","fr":"DiPeO Backend est un outil pour créer des agents d''intelligence artificielle via une interface utilisateur de diagramme de blocs. Il comprend un serveur FastAPI et des outils de ligne de commande.","de":"DiPeO Backend ist ein Tool zum Erstellen von künstlichen Intelligenz-Agenten über eine Blockdiagramm-Benutzeroberfläche. Es umfasst einen FastAPI-Server und Befehlszeilenwerkzeuge.","pt":"O DiPeO Backend é uma plataforma de construção de agentes que utiliza uma interface de diagrama de blocos para criar ferramentas personalizadas. Com recursos como FastAPI e CLI, é ideal para desenvolvedores que buscam criar soluções personalizadas.","ru":"DiPeO Backend - это платформа для построения агентов, которая использует интерфейс блок-схем для создания индивидуальных инструментов. С функциями như FastAPI и CLI, она идеальна для разработчиков, которые хотят создавать индивидуальные решения.","ar":"DiPeO Backend هي منصة بناء الوكلاء التي تستخدم واجهة الرسم بالكتلة لإنشاء أدوات مخصصة. مع ميزات مثل FastAPI و CLI، فهي مثالية للمطورين الذين يبحثون عن إنشاء حلول مخصصة."},"seo":{"title":{"en":"dipeo-backend: FastAPI Server Setup Guide | AI Agent Skill","zh":"Dipeo Backend Setup Guide - AI工具快速集成","ja":"Dipeo Backend ベストプラクティス - AIエージェントの構築","ko":"Dipeo Backend 개발자 안내 - AI 에이전트를 위한 백엔드 솔루션","es":"Guía de configuración de DiPeO Backend para desarrolladores","fr":"Guide de mise en place de DiPeO Backend pour les développ...","de":"Einrichtungsleitfaden für DiPeO Backend-Entwickler","pt":"Guia de Configuração do DiPeO Backend: Ferramentas de Con...","ru":"Настройка DiPeO Backend: Инструменты построения агентов ИИ","ar":"دليل إعداد DiPeO Backend: أدوات بناء الوكلاء"},"description":{"en":"Discover how dipeo-backend streamlines backend ecosystem development with its block diagram UI and FastAPI server. Get started with setup and configuration t...","zh":"了解Dipeo Backend的技术细节，包括FastAPI服务器、CLI工具和数据库模式初始化，快速构建AI工具","ja":"Dipeo Backendの機能を活用して、AIエージェントの構築を効率化する方法を紹介","ko":"Dipeo Backend의 핵심기술을 이해하고, FastAPI 서버, CLI 도구, 데이터베이스 스키마 초기화를 통해 AI 에이전트를 개발하세요","es":"Aprenda a utilizar DiPeO Backend con FastAPI y CLI para crear herramientas de bloque de diagrama UI para agentes de inteligencia artificial","fr":"Découvrez comment utiliser DiPeO Backend avec FastAPI et CLI pour créer des outils de bloc de diagramme UI pour les agents d''intelligence artificielle","de":"Erfahren Sie, wie Sie DiPeO Backend mit FastAPI und CLI verwenden, um Blockdiagramm-UI-Tools für künstliche Intelligenz-Agenten zu erstellen","pt":"Aprenda a configurar o DiPeO Backend, uma plataforma de construção de agentes via interface de diagrama de blocos, com recursos como FastAPI e CLI","ru":"Узнайте, как настроить DiPeO Backend, платформу для построения агентов с помощью интерфейса блок-схем, с функциями FastAPI и CLI","ar":"تعرف على كيفية إعداد DiPeO Backend، منصة بناء الوكلاء عبر واجهة الرسم بالكتلة، مع ميزات مثل FastAPI و CLI"},"definition":{"en":"dipeo-backend is a skill for building tools via block diagram UI, integrating with FastAPI server, CLI tools, and message store within the backend ecosystem.","zh":"Dipeo Backend是支持AI工具构建的后端生态系统","ja":"Dipeo BackendはAIエージェントの構築を支援するバックエンドエコシステムです","ko":"Dipeo Backend는 AI 에이전트를 위한 백엔드 솔루션입니다","es":"DiPeO Backend es un entorno de backend que incluye un servidor FastAPI y herramientas de línea de comandos para crear agentes de inteligencia artificial","fr":"DiPeO Backend est un environnement de backend qui comprend un serveur FastAPI et des outils de ligne de commande pour créer des agents d''intelligence artificielle","de":"DiPeO Backend ist eine Backend-Umgebung, die einen FastAPI-Server und Befehlszeilenwerkzeuge zur Erstellung von künstlichen Intelligenz-Agenten umfasst","pt":"O DiPeO Backend é uma plataforma de construção de agentes que permite criar ferramentas personalizadas via interface de diagrama de blocos","ru":"DiPeO Backend - это платформа для построения агентов, которая позволяет создавать индивидуальные инструменты с помощью интерфейса блок-схем","ar":"DiPeO Backend هي منصة بناء الوكلاء التي تسمح بإنشاء أدوات مخصصة عبر واجهة الرسم بالكتلة"},"features":{"en":["Utilizes FastAPI server for backend ecosystem development","Provides CLI tools for efficient task management","Integrates with message store for streamlined communication","Supports database schema initialization via persistence_manager.py","Enables read-only tasks for understanding code and reviewing configs","Facilitates debugging logs for improved issue resolution"],"zh":["支持FastAPI服务器","提供CLI工具","数据库模式初始化","MCP集成","简单的代码修改","只读任务支持"],"ja":["FastAPIサーバーのサポート","CLIツールの提供","データベーススキーマ初期化","MCP統合","簡単なコード変更","読み取り専用タスクのサポート"],"ko":["FastAPI 서버 지원","CLI 도구 제공","데이터베이스 스키마 초기화","MCP 통합","단순한 코드 수정","읽기 전용 작업 지원"],"es":["Servidor FastAPI para la creación de agentes de inteligencia artificial","Herramientas de línea de comandos (CLI) para la configuración y el depurado","Almacenamiento de mensajes y integración con MCP","Inicialización de esquemas de base de datos en `/dipeo/infrastructure/execution/state/persistence_manager.py`"],"fr":["Serveur FastAPI pour la création d''agents d''intelligence artificielle","Outils de ligne de commande (CLI) pour la configuration et le débogage","Stockage de messages et intégration avec MCP","Initialisation de schémas de base de données en `/dipeo/infrastructure/execution/state/persistence_manager.py`"],"de":["FastAPI-Server für die Erstellung von künstlichen Intelligenz-Agenten","Befehlszeilenwerkzeuge (CLI) für die Konfiguration und Fehlersuche","Nachrichtenspeicher und Integration mit MCP","Initialisierung von Datenbankschemata in `/dipeo/infrastructure/execution/state/persistence_manager.py`"],"pt":["Interface de diagrama de blocos para construção de agentes","Suporte a FastAPI para criação de servidores personalizados","Ferramentas de linha de comando (CLI) para automação de tarefas","Integração com message store e MCP","Inicialização de esquema de banco de dados via persistence_manager.py"],"ru":["Интерфейс блок-схем для построения агентов","Поддержка FastAPI для создания индивидуальных серверов","Инструменты командной строки (CLI) для автоматизации задач","Интеграция с message store и MCP","Инициализация схемы базы данных через persistence_manager.py"],"ar":["واجهة الرسم بالكتلة لإنشاء الوكلاء","دعم FastAPI لإنشاء خوادم مخصصة","أدوات سطر الأوامر (CLI) للتحكم الآلي في المهام","التكامل مع message store و MCP","تخزين مخطط قاعدة البيانات عبر persistence_manager.py"]},"keywords":{"en":["how to use dipeo-backend","dipeo-backend setup guide","FastAPI server integration","dipeo-backend vs other backend tools","dipeo-backend install","what is dipeo-backend","block diagram UI for backend development","dipeo-backend documentation","dipeo-backend alternative"],"zh":["Dipeo Backend","AI工具","FastAPI","CLI工具","数据库模式初始化","MCP集成","AI开发","后端生态系统","AIエージェント"],"ja":["Dipeo Backend","AIエージェント","FastAPI","CLIツール","データベーススキーマ初期化","MCP統合","AI開発","バックエンドエコシステム","AIツール"],"ko":["Dipeo Backend","AI 에이전트","FastAPI","CLI 도구","데이터베이스 스키마 초기화","MCP 통합","AI 개발","백엔드 솔루션","AI 도구"],"es":["DiPeO Backend","FastAPI","CLI","agentes de inteligencia artificial","herramientas de bloque de diagrama UI","desarrollo de backend","integración con MCP","almacenamiento de mensajes"],"fr":["DiPeO Backend","FastAPI","CLI","agents d''intelligence artificielle","outils de bloc de diagramme UI","développement de backend","intégration avec MCP","stockage de messages"],"de":["DiPeO Backend","FastAPI","CLI","künstliche Intelligenz-Agenten","Blockdiagramm-UI-Tools","Backend-Entwicklung","Integration mit MCP","Nachrichtenspeicher"],"pt":["dipeo backend","construção de agentes","fastapi","cli","message store","mcp","persistence manager","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["dipeo backend","построение агентов","fastapi","cli","message store","mcp","persistence manager","разработка программного обеспечения","инструменты разработки"],"ar":["dipeo backend","بناء الوكلاء","fastapi","cli","message store","mcp","persistence manager","تطوير البرمجيات","أدوات التطوير"]}},"owner":"sorryhyun","repo":"DiPeO","repoPath":"sorryhyun/DiPeO","stars":12,"forks":2,"updatedAt":"2026-02-06T07:13:58Z","topics":[],"category":"community","skillMd":{"name":"dipeo-backend","description":"Router skill for DiPeO backend ecosystem (server/ and cli/): FastAPI server, CLI tools, database, MCP integration. Use when task mentions CLI commands, server endpoints, database queries, or MCP tools. For simple tasks, handle directly; for complex work, escalate to dipeo-backend agent.","bodyPreview":"# DiPeO Backend Router\n\n**Domain**: Backend ecosystem including FastAPI server (`server/`), CLI tools (`cli/`), message store, and MCP integration. Database schema initialization is in `/dipeo/infrastructure/execution/state/persistence_manager.py` (package-maintainer domain).\n\n## Quick Decision: Skill or Agent?\n\n### ✅ Handle Directly (This Skill)\n- **Simple changes**: <20 lines, 1-2 files\n- **Read-only tasks**: Understanding code, reviewing configs, debugging logs\n- **Documentation lookup**: CLI","body":"# DiPeO Backend Router\n\n**Domain**: Backend ecosystem including FastAPI server (`server/`), CLI tools (`cli/`), message store, and MCP integration. Database schema initialization is in `/dipeo/infrastructure/execution/state/persistence_manager.py` (package-maintainer domain).\n\n## Quick Decision: Skill or Agent?\n\n### ✅ Handle Directly (This Skill)\n- **Simple changes**: <20 lines, 1-2 files\n- **Read-only tasks**: Understanding code, reviewing configs, debugging logs\n- **Documentation lookup**: CLI help, API signatures, database schema\n- **Small config tweaks**: Environment variables, command flags\n\n### ❌ Escalate to Agent\n- **Complex features**: Multi-file changes, new CLI commands, database migrations\n- **Architecture changes**: New API endpoints, MCP tool implementation\n- **Cross-cutting concerns**: Affects CLI + database + execution engine\n- **Uncertain scope**: Not sure how many files will change\n\n**Agent**: `Task(dipeo-backend, \"your detailed task description\")`\n\n## Documentation Sections (Load On-Demand)\n\nUse `Skill(doc-lookup)` with these anchors when you need detailed context:\n\n**Core Responsibilities**:\n- `docs/agents/backend-development.md#core-responsibilities` - CLI, FastAPI server, database, MCP server\n\n**Implementation Patterns**:\n- `docs/agents/backend-development.md#common-patterns` - CLI, background execution, database, MCP patterns\n\n**Troubleshooting**:\n- `docs/agents/backend-development.md#troubleshooting` - Server, CLI, database, MCP issues\n\n**MCP Integration**:\n- `docs/features/mcp-server-integration.md#quick-start` - Setup and usage guide\n- `docs/features/chatgpt-mcp-integration.md#quick-start` - ChatGPT connection\n\n**Example doc-lookup call**:\n```bash\npython .claude/skills/doc-lookup/scripts/section_search.py \\\n  --query \"cli-commands\" \\\n  --paths docs/agents/backend-development.md \\\n  --top 1\n```\n\n## Escalation to Other Agents\n\n**To dipeo-package-maintainer**: Execution handlers, service architecture, domain models, LLM infrastructure\n**To dipeo-codegen-pipeline**: GraphQL schema changes, generated type issues, TypeScript specs\n\n## Typical Workflow\n\n1. **Assess task complexity**: Simple (handle) vs. complex (escalate)\n2. **If simple**: Load relevant section via `Skill(doc-lookup)`\n3. **Execute**: Make changes or provide answer\n4. **If complex**: Escalate with `Task(dipeo-backend, \"task details\")`\n"},"lastSynced":"2026-03-06T06:44:54.802Z","agentAnalysis":{"suitability":{"en":"Perfect for Python-based AI Agents needing advanced backend ecosystem development with FastAPI and CLI tools.","zh":"非常适合需要使用FastAPI和CLI工具进行高级后端生态系统开发的Python-based AI Agents。","ja":"FastAPIとCLIツールを使用した高度なバックエンドエコシステム開発が必要なPythonベースのAIエージェントに最適です。","ko":"FastAPI와 CLI 도구를 사용하여 고급 백엔드 생태계 개발이 필요한 Python 기반 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial basados en Python que necesitan un desarrollo de ecosistema de backend avanzado con FastAPI y herramientas de CLI.","fr":"Parfait pour les Agents d''Intelligence Artificielle basés sur Python nécessitant un développement d''écosystème de backend avancé avec FastAPI et des outils de CLI.","de":"Perfekt für Python-basierte KI-Agents, die eine erweiterte Backend-Ökosystem-Entwicklung mit FastAPI und CLI-Tools benötigen.","pt":"Perfeito para Agentes de IA baseados em Python que precisam de desenvolvimento de ecossistema de backend avançado com FastAPI e ferramentas CLI.","ru":"Идеально подходит для агентов ИИ на основе Python, которым требуется разработка продвинутой экосистемы бэкенда с FastAPI и инструментами CLI.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تعتمد على بايثون التي تحتاج إلى تطوير بيئة خلفية متقدمة مع FastAPI وأدوات CLI."},"recommendation":{"en":"Empowers agents to develop and manage comprehensive backend ecosystems using FastAPI server, CLI tools, and message store integration, while also providing database schema initialization capabilities through persistence_manager.py.","zh":"赋予代理开发和管理使用FastAPI服务器、CLI工具和消息存储集成的综合后端生态系统的能力，同时也提供通过persistence_manager.py初始化数据库模式的能力。","ja":"FastAPIサーバー、CLIツール、メッセージストア統合を使用した包括的なバックエンドエコシステムの開発と管理、およびpersistence_manager.pyを介したデータベーススキーマ初期化の能力をエージェントに提供します。","ko":"FastAPI 서버, CLI 도구 및 메시지 저장소 통합을 사용하여 포괄적인 백엔드 생태계를 개발하고 관리하며, persistence_manager.py를 통해 데이터베이스 스키마 초기화를 제공합니다.","es":"Habilita a los agentes a desarrollar y gestionar ecosistemas de backend integrales utilizando el servidor FastAPI, herramientas de CLI y la integración del almacén de mensajes, y también proporciona capacidades de inicialización de esquemas de bases de datos a través de persistence_manager.py.","fr":"Permet aux agents de développer et de gérer des écosystèmes de backend complets en utilisant le serveur FastAPI, des outils de CLI et l''intégration du magasin de messages, et fournit également des capacités d''initialisation de schémas de bases de données via persistence_manager.py.","de":"Ermöglicht es den Agents, umfassende Backend-Ökosysteme zu entwickeln und zu verwalten, indem sie den FastAPI-Server, CLI-Tools und die Nachrichtenspeicherintegration verwenden, und bietet auch die Möglichkeit, Datenbankschemata über persistence_manager.py zu initialisieren.","pt":"Habilita os agentes a desenvolver e gerenciar ecossistemas de backend abrangentes usando servidor FastAPI, ferramentas CLI e integração de armazenamento de mensagens, além de fornecer capacidades de inicialização de esquema de banco de dados por meio do persistence_manager.py.","ru":"Предоставляет агентам возможность разработки и управления комплексными экосистемами бэкенда с использованием сервера FastAPI, инструментов CLI и интеграции хранилища сообщений, а также обеспечивает возможности инициализации схемы базы данных через persistence_manager.py.","ar":"تمكن الوكلاء من تطوير وإدارة بيئات خلفية شاملة باستخدام خادم FastAPI وأدوات CLI ودمج مخزن الرسائل، بالإضافة إلى تقديم إمكانيات 초기ه مخطط قاعدة البيانات من خلال persistence_manager.py."},"useCases":{"en":["Building and deploying FastAPI servers","Creating custom CLI tools for backend tasks","Debugging and optimizing backend ecosystem logs"],"zh":["构建和部署FastAPI服务器","创建自定义CLI工具用于后端任务","调试和优化后端生态系统日志"],"ja":["FastAPIサーバーの構築とデプロイ","バックエンドタスク用のカスタムCLIツールの作成","バックエンドエコシステムログのデバッグと最適化"],"ko":["FastAPI 서버 빌드 및 배포","백엔드 작업을 위한 사용자 지정 CLI 도구 생성","백엔드 생태계 로그 디버깅 및 최적화"],"es":["Construcción y despliegue de servidores FastAPI","Creación de herramientas de CLI personalizadas para tareas de backend","Depuración y optimización de registros del ecosistema de backend"],"fr":["Construction et déploiement de serveurs FastAPI","Création d''outils de CLI personnalisés pour les tâches de backend","Débogage et optimisation des journaux de l''écosystème de backend"],"de":["Erstellung und Bereitstellung von FastAPI-Servern","Erstellung benutzerdefinierter CLI-Tools für Backend-Aufgaben","Fehlerbehebung und Optimierung von Backend-Ökosystem-Protokollen"],"pt":["Construir e implantar servidores FastAPI","Criar ferramentas CLI personalizadas para tarefas de backend","Depurar e otimizar logs de ecossistema de backend"],"ru":["Создание и развертывание серверов FastAPI","Разработка пользовательских инструментов CLI для задач бэкенда","Отладка и оптимизация журналов экосистемы бэкенда"],"ar":["بناء وتحديث خوادم FastAPI","إنشاء أدوات CLI مخصصة لمهام الخلفية","تصحيح الأخطاء وتحسين سجلات بيئة الخلفية"]},"limitations":{"en":["Requires Python environment","Limited to FastAPI and CLI tools","Database schema initialization restricted to persistence_manager.py"],"zh":["需要Python环境","仅限FastAPI和CLI工具","数据库模式初始化仅限于persistence_manager.py"],"ja":["Python環境が必要","FastAPIとCLIツールのみの制限","データベーススキーマ初期化はpersistence_manager.pyのみ"],"ko":["Python 환경이 필요합니다.","FastAPI 및 CLI 도구로 제한됩니다.","데이터베이스 스키마 초기화는 persistence_manager.py로 제한됩니다."],"es":["Requiere entorno de Python","Limitado a FastAPI y herramientas de CLI","La inicialización del esquema de base de datos está restringida a persistence_manager.py"],"fr":["Nécessite un environnement Python","Limité à FastAPI et aux outils de CLI","L''initialisation du schéma de base de données est restreinte à persistence_manager.py"],"de":["Benötigt Python-Umgebung","Begrenzt auf FastAPI und CLI-Tools","Die Initialisierung des Datenbankschemas ist auf persistence_manager.py beschränkt"],"pt":["Exige ambiente Python","Limitado a FastAPI e ferramentas CLI","Inicialização do esquema de banco de dados restrita ao persistence_manager.py"],"ru":["Требуется среда Python","Ограничен до FastAPI и инструментов CLI","Инициализация схемы базы данных ограничена persistence_manager.py"],"ar":["يتطلب بيئة بايثون","محدود ب FastAPI وأدوات CLI","محدودية 初期ه مخطط قاعدة البيانات إلى persistence_manager.py"]},"version":4},"contentHash":"385b8298fdd6d15a17afaca6765fd67fe313081962210da9928e8561400ca9af","qualityScore":42}');
