INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sorryhyun/DiPeO/dipeo-backend', 'dipeo-backend', 'sorryhyun', 'DiPeO', 'community', 'dipeo-backend sorryhyun DiPeO community The dipeo-backend skill provides a block diagram UI for building tools, supporting backend ecosystem development with FastAPI server and CLI tools. It benefits developers working with backend ecosystems. Dipeo Backend是一个强大的AI工具构建平台，支持FastAPI服务器、CLI工具和数据库模式初始化 Dipeo Backendは、AIエージェントの構築を容易にするためのツールを提供するバックエンドエコシステムです Dipeo Backend는 AI 에이전트를 위한 백엔드 솔루션으로, FastAPI 서버, CLI 도구, 데이터베이스 스키마 초기화 등을 지원합니다 DiPeO Backend es una herramienta para crear agentes de inteligencia artificial mediante una interfaz de usuario de block diagram. Incluye un servidor FastAPI y herramientas de línea de comandos. DiPeO Backend est un outil pour créer des agents d''intelligence artificielle via une interface utilisateur de diagramme de blocs. Il comprend un serveur FastAPI et des outils de ligne de commande. DiPeO Backend ist ein Tool zum Erstellen von künstlichen Intelligenz-Agenten über eine Blockdiagramm-Benutzeroberfläche. Es umfasst einen FastAPI-Server und Befehlszeilenwerkzeuge. O DiPeO Backend é uma plataforma de construção de agentes que utiliza uma interface de diagrama de blocos para criar ferramentas personalizadas. Com recursos como FastAPI e CLI, é ideal para desenvolvedores que buscam criar soluções personalizadas. DiPeO Backend - это платформа для построения агентов, которая использует интерфейс блок-схем для создания индивидуальных инструментов. С функциями như FastAPI и CLI, она идеальна для разработчиков, которые хотят создавать индивидуальные решения. DiPeO Backend هي منصة بناء الوكلاء التي تستخدم واجهة الرسم بالكتلة لإنشاء أدوات مخصصة. مع ميزات مثل FastAPI و CLI، فهي مثالية للمطورين الذين يبحثون عن إنشاء حلول مخصصة. how to use dipeo-backend dipeo-backend setup guide FastAPI server integration dipeo-backend vs other backend tools dipeo-backend install what is dipeo-backend block diagram UI for backend development dipeo-backend documentation dipeo-backend alternative Dipeo Backend AI工具 FastAPI CLI工具 数据库模式初始化 MCP集成 AI开发 后端生态系统 AIエージェント Utilizes FastAPI server for backend ecosystem development Provides CLI tools for efficient task management Integrates with message store for streamlined communication Supports database schema initialization via persistence_manager.py Enables read-only tasks for understanding code and reviewing configs Facilitates debugging logs for improved issue resolution dipeo-backend is a skill for building tools via block diagram UI, integrating with FastAPI server, CLI tools, and message store within the backend ecosystem.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lsp-client/LSAP/lsap-api-design', 'community', 'lsp-client', 'LSAP', 'lsp-client/LSAP', 'lsap-api-design', 12, 0, 42, '2026-02-27T11:16:01Z', '2026-03-06T06:45:46.317Z', '79b42205cdb59e9b4cb87b9482decfa02a336c03cdd60370a91fa4db9d0ab415', '{"id":"lsp-client/LSAP/lsap-api-design","name":"lsap-api-design","description":{"en":"The lsap-api-design skill enables AI coding agents to interact with Language Servers via the LSAP protocol, benefiting developers working with Language Server Agent Protocol. It provides a structured approach to API design.","zh":"LSAP API 设计是实现 AI 编码代理与语言服务器交互的关键，了解其架构和原理","ja":"LSAP API デザインは、AI エージェントと言語サーバーの接続を実現するための重要な要素です","ko":"LSAP API 디자인은 AI 코딩 에이전트와 언어 서버의 연동을 위한 핵심 기술입니다","es":"LSAP es un protocolo abierto que define la interacción entre agentes de código inteligentes y servidores de lenguaje. Nuestra guía cubre la arquitectura y los principios clave para el diseño de APIs LSAP.","fr":"LSAP est un protocole ouvert qui définit l''interaction entre les agents de codage intelligents et les serveurs de langage. Notre guide couvre l''architecture et les principes clés pour la conception d''API LSAP.","de":"LSAP ist ein offenes Protokoll, das die Interaktion zwischen KI-Coding-Agenten und Sprachservern definiert. Unsere Anleitung behandelt die Architektur und die Schlüsselprinzipien für das Design von LSAP-APIs.","pt":"O LSAP é um protocolo aberto que define como os agentes de codificação de IA interagem com Servidores de Linguagem. Nossa guia aborda a arquitetura de três camadas e os princípios de design.","ru":"LSAP — это открытый протокол, определяющий, как агенты кодирования ИИ взаимодействуют с Серверами Языка. Наше руководство охватывает трехслойную архитектуру и принципы проектирования.","ar":"LSAP هو بروتوكول مفتوح يحدد كيفية تفاعل عمليات التشفير الذكية مع خوادم اللغة. دليلنا يتطرق إلى هيكل ثلاثي الطبقات ومبادئ التصميم."},"seo":{"title":{"en":"lsap-api-design: API Setup Guide for AI Agents | AI Agent...","zh":"LSAP API 设计指南 - AI 编码代理接口实现","ja":"LSAP API デザインガイド - AI エージェントのための言語サーバー接続","ko":"LSAP API 디자인 가이드 - AI 코딩 에이전트 언어 서버 연동","es":"Diseño de API LSAP: Guía para Agentes de Código Inteligentes","fr":"Conception d''API LSAP : Guide pour les Agents de Codage I...","de":"LSAP-API-Design: Leitfaden für KI-Coding-Agenten","pt":"Guia de Design da API LSAP para Ferramentas de Inteligênc...","ru":"Руководство по проектированию API LSAP для ИИ Агентов","ar":"دليل تصميم واجهة برمجة التطبيقات LSAP لأدوات الذكاء الاصط..."},"description":{"en":"Discover how to implement LSAP API design for seamless AI coding agent interactions. Learn more and get started with our expert guide today!","zh":"了解 LSAP API 设计，实现 AI 编码代理与语言服务器的无缝连接，提高开发效率","ja":"LSAP API デザインの詳細を学ぶことで、AI エージェントと言語サーバーの連携を強化します","ko":"LSAP API 디자인을 통해 AI 코딩 에이전트와 언어 서버를 연결하고 개발 효율성을 높이세요","es":"Aprende a diseñar APIs LSAP para agentes de código inteligentes con nuestra guía detallada sobre arquitectura y principios clave","fr":"Découvrez comment concevoir des API LSAP pour les agents de codage intelligents avec notre guide détaillé sur l''architecture et les principes clés","de":"Erfahren Sie, wie Sie APIs LSAP für KI-Coding-Agenten entwerfen, mit unserer detaillierten Anleitung zu Architektur und Schlüsselprinzipien","pt":"Aprenda a projetar APIs LSAP para agentes de codificação de IA com nossa guia passo a passo, incluindo arquitetura de três camadas e princípios de design","ru":"Узнайте, как проектировать API LSAP для агентов кодирования ИИ с нашей пошаговой инструкцией, включая трехслойную архитектуру и принципы проектирования","ar":"تعرف على كيفية تصميم واجهات برمجة التطبيقات LSAP لعمليات التشفير الذكية مع دليلنا الخطوة بخطوة، بما في ذلك هيكل ثلاثي الطبقات ومبادئ التصميم"},"definition":{"en":"lsap-api-design is an open protocol defining interactions between AI coding agents and Language Servers, comprising three layers: Schema, Capability, and LSP.","zh":"LSAP API 设计是一种开放协议，定义了 AI 编码代理与语言服务器之间的交互","ja":"LSAP API デザインは、AI エージェントと言語サーバー間の接続を定義するオープンプロトコルです","ko":"LSAP API 디자인은 AI 코딩 에이전트와 언어 서버 사이의 상호작용을 정의하는 오픈 프로토콜입니다","es":"LSAP es un protocolo que permite a los agentes de código inteligentes interactuar con servidores de lenguaje de manera estandarizada","fr":"LSAP est un protocole qui permet aux agents de codage intelligents d''interagir avec les serveurs de langage de manière standardisée","de":"LSAP ist ein Protokoll, das es KI-Coding-Agenten ermöglicht, mit Sprachservern standardisiert zu interagieren","pt":"O LSAP é um protocolo que define a interação entre agentes de codificação de IA e Servidores de Linguagem","ru":"LSAP — это протокол, определяющий взаимодействие между агентами кодирования ИИ и Серверами Языка","ar":"LSAP هو بروتوكول يحدد التفاعل بين عمليات التشفير الذكية وخوادم اللغة"},"features":{"en":["Defines Request/Response models using Pydantic","Utilizes Markdown templates for output","Employs semantic anchoring via Locate","Composes capabilities for business logic and LSP orchestration","Leverages the lsp-client library for raw protocol operations"],"zh":["基于 Pydantic 的请求/响应模型","支持 Markdown 模板","三层架构：Schema、Capability 和 LSP","Agent-cognitive 设计","语义锚定通过 Locate","组合能力"],"ja":["Pydantic を使用したリクエスト/レスポンスモデル","Markdown テンプレートのサポート","3 層アーキテクチャ：Schema、Capability、LSP","エージェント認知設計","Locate によるセマンティックアンカー","組み合わせ可能な機能"],"ko":["Pydantic 기반의 요청/응답 모델","Markdown 템플릿 지원","3계층 아키텍처: Schema, Capability, LSP","에이전트인지 설계","Locate를 통한 의미錨","조합 가능한 능력"],"es":["Arquitectura de tres capas: Esquema, Capacidad y LSP","Diseño de agentes cognitivos","Salida en Markdown","Anclaje semántico mediante Locate","Capacidades compuestas"],"fr":["Architecture à trois couches : Schéma, Capacité et LSP","Conception d''agents cognitifs","Sortie en Markdown","Ancrage sémantique via Locate","Capacités composées"],"de":["Dreischichten-Architektur: Schema, Fähigkeit und LSP","Entwurf kognitiver Agenten","Markdown-Ausgabe","Semantisches Anker via Locate","Zusammengesetzte Fähigkeiten"],"pt":["Arquitetura de três camadas: Schema, Capability e LSP","Utilização de Pydantic para modelos de solicitação e resposta","Suporte a saída em Markdown com templates","Orquestração de LSP com capacidades compostas","Anchoring semântico via Locate"],"ru":["Трехслойная архитектура: Schema, Capability и LSP","Использование Pydantic для моделей запроса и ответа","Поддержка вывода в Markdown с шаблонами","Оркестрация LSP с составными возможностями","Семантическая привязка через Locate"],"ar":["هيكل ثلاثي الطبقات: Schema و Capability و LSP","استخدام Pydantic لنماذج الطلب والاستجابة","دعم الإخراج في Markdown مع القوالب","أوركسترا LSP مع القدرات المركبة","التثبيت الدلالي عبر Locate"]},"keywords":{"en":["how to use lsap-api-design","lsap-api-design setup guide","what is lsap-api-design","lsap-api-design alternative","lsap-api-design vs Language Server Protocol","lsap-api-design install","lsap-api-design for AI coding agents","Language Server Agent Protocol tutorial","LSAP API design best practices"],"zh":["LSAP API 设计","AI 编码代理","语言服务器","Pydantic","Markdown","Agent-cognitive 设计","语义锚定","组合能力"],"ja":["LSAP API デザイン","AI エージェント","言語サーバー","Pydantic","Markdown","エージェント認知設計","セマンティックアンカー","組み合わせ可能な機能"],"ko":["LSAP API 디자인","AI 코딩 에이전트","언어 서버","Pydantic","Markdown","에이전트인지 설계","의미錨","조합 가능한 능력"],"es":["agentes de código inteligentes","diseño de API LSAP","arquitectura LSAP","protocolo LSAP","servidores de lenguaje","Pydantic","Markdown","Locate"],"fr":["agents de codage intelligents","conception d''API LSAP","architecture LSAP","protocole LSAP","serveurs de langage","Pydantic","Markdown","Locate"],"de":["KI-Coding-Agenten","LSAP-API-Design","LSAP-Architektur","LSAP-Protokoll","Sprachserver","Pydantic","Markdown","Locate"],"pt":["LSAP","API LSAP","Design de API LSAP","Ferramentas de Inteligência Artificial","Agentes de codificação de IA","Servidores de Linguagem","Pydantic","Markdown","LSP"],"ru":["LSAP","API LSAP","Проектирование API LSAP","ИИ Агенты","Агенты кодирования ИИ","Серверы Языка","Pydantic","Markdown","LSP"],"ar":["LSAP","واجهة برمجة التطبيقات LSAP","تصميم واجهة برمجة التطبيقات LSAP","أدوات الذكاء الاصطناعي","عمليات التشفير الذكية","خوادم اللغة","Pydantic","Markdown","LSP"]}},"owner":"lsp-client","repo":"LSAP","repoPath":"lsp-client/LSAP","stars":12,"forks":0,"updatedAt":"2026-02-27T11:16:01Z","topics":[],"category":"community","skillMd":{"name":"lsap-api-design","description":"Guide for designing and implementing new LSAP APIs. Use when adding new capabilities to LSAP (definitions, references, rename, etc.) or when asking how to add new features to the LSAP protocol. Provides architectural patterns, implementation steps, and references to existing code examples.","bodyPreview":"# LSAP API Design\n\nGuide for adding new APIs to LSAP. Study existing code as needed.\n\n## Architecture\n\nThree layers:\n\n1. **Schema** (`src/lsap/schema/`): Request/Response models (Pydantic), Markdown templates\n2. **Capability** (`src/lsap/capability/`): Business logic, LSP orchestration\n3. **LSP** (lsp-client library): Raw protocol operations\n\n**Key Principles:** Agent-cognitive design, Markdown-first output, semantic anchoring via `Locate`, composed capabilities\n\n## Reference Implementations\n\nSt","body":"# LSAP API Design\n\nGuide for adding new APIs to LSAP. Study existing code as needed.\n\n## Architecture\n\nThree layers:\n\n1. **Schema** (`src/lsap/schema/`): Request/Response models (Pydantic), Markdown templates\n2. **Capability** (`src/lsap/capability/`): Business logic, LSP orchestration\n3. **LSP** (lsp-client library): Raw protocol operations\n\n**Key Principles:** Agent-cognitive design, Markdown-first output, semantic anchoring via `Locate`, composed capabilities\n\n## Reference Implementations\n\nStudy these before implementing:\n\n- **Simple**: `src/lsap/schema/definition.py` + `src/lsap/capability/definition.py`\n- **Paginated**: `src/lsap/schema/reference.py` + `src/lsap/capability/reference.py`\n- **Multi-mode**: `src/lsap/schema/rename.py` + `src/lsap/capability/rename.py`\n- **Complex**: `src/lsap/schema/symbol.py` + `src/lsap/capability/symbol.py`\n\n## Implementation Steps\n\n### 1. Define Schema (`src/lsap/schema/<name>.py`)\n\nSee `src/lsap/schema/definition.py` for complete example.\n\nKey components:\n\n- **Request Model**: Inherit from `Request`, `LocateRequest`, or `PaginatedRequest`\n- **Response Model**: Inherit from `Response` or `PaginatedResponse`\n- **Markdown Template**: Liquid template in `model_config.json_schema_extra[\"markdown\"]`\n\nTemplate basics (see `docs/liquid_cheatsheet.md`):\n- Conditionals: `{% if items.size == 0 %}...{% endif %}`\n- Loops: `{% for item in items %}...{% endfor %}`\n- Filters: `{{ mode | capitalize }}`, `{{ path | join: \".\" }}`\n\n### 2. Implement Capability (`src/lsap/capability/<name>.py`)\n\nSee `src/lsap/capability/definition.py` for complete example.\n\nPattern:\n\n```python\nfrom attrs import define\nfrom .abc import Capability\n\n@define\nclass MyCapability(Capability[MyRequest, MyResponse]):\n    async def __call__(self, req: MyRequest) -> MyResponse | None:\n        # 1. Locate position (if needed)\n        if not (loc_resp := await self.locate(req)):\n            return None\n        \n        # 2. Call LSP operations via ensure_capability()\n        # 3. Process results (use asyncer.create_task_group for parallelism)\n        # 4. Return response (or None on failure)\n```\n\n**Important:** Return `None` on failure, not empty response.\n\n### 3. Register Exports\n\nAdd to `src/lsap/capability/__init__.py` and `src/lsap/schema/__init__.py`\n\n### 4. Add Tests\n\nSee `tests/test_definition.py` for examples. Must test: success case, not found case.\n\n### 5. Add Documentation\n\nCreate `schema/<name>.md` with usage examples.\n\n## Common Patterns\n\n### Pagination\n\nSee `src/lsap/capability/reference.py` for complete pattern with `PaginationCache` and `paginate()`.\n\n### Reading Code Context\n\n```python\nfrom lsap.utils.document import DocumentReader\n\ncontent = await self.client.read_file(file_path)\nreader = DocumentReader(content)\nsnippet = reader.read(context_range, trim_empty=True)\n```\n\n### Symbol Information\n\n```python\nfrom lsap.utils.symbol import symbol_at\n\nsymbols = await ensure_capability(\n    self.client, WithRequestDocumentSymbol\n).request_document_symbol_list(file_path)\n\nif symbols and (match := symbol_at(symbols, position)):\n    symbol_path, symbol = match\n```\n\n### LSP Capability Check\n\n```python\nfrom lsap.utils.capability import ensure_capability\n\nresult = await ensure_capability(\n    self.client,\n    WithRequestReferences,\n    error=\"Fallback instructions if not supported\"\n).request_references(file_path, position)\n```\n\n## Common Utilities\n\nSee `src/lsap/utils/` for implementations.\n\n**Path handling:**\n- `client.from_uri(uri)` - Returns relative path by default\n- `client.from_uri(uri, relative=False)` - Returns absolute path\n\n**Position conversion:**\n- `Position.from_lsp(lsp_pos)` - LSP (0-based) → LSAP (1-based)\n- `lsap_pos.to_lsp()` - LSAP (1-based) → LSP (0-based)\n\n**Hover content:**\n- `clean_hover_content(hover.value)` - Removes LSP formatting artifacts\n\n## Checklists\n\n**Files to create:**\n- `src/lsap/schema/<name>.py`\n- `src/lsap/capability/<name>.py`\n- `tests/test_<name>.py`\n- `schema/<name>.md`\n\n**Files to update:**\n- `src/lsap/schema/__init__.py`\n- `src/lsap/capability/__init__.py`\n\n**Must verify:**\n- Returns `None` on failure (not empty response)\n- Uses `ensure_capability()` for LSP operations\n- Concurrent operations use semaphores\n- Tests cover success and failure cases\n\n## Related Documentation\n\n- `docs/locate_design.md` - Position resolution patterns\n- `docs/liquid_cheatsheet.md` - Template syntax\n- `CONTRIBUTING.md` - Development workflow\n"},"lastSynced":"2026-03-06T06:45:46.317Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Coding Agents requiring structured interaction with Language Servers via the LSAP protocol","zh":"适用于需要通过LSAP协议与语言服务器交互的AI编码代理","ja":"LSAPプロトコルを使用してLanguage Serverと構造化されたやり取りを必要とするAIコーディングエージェントに適しています","ko":"LSAP 프로토콜을 사용하여 언어 서버와 구조화된 상호 작용을 요구하는 AI 코딩 에이전트에 적합합니다","es":"Ideal para Agentes de Codificación de IA que requieren interacción estructurada con Servidores de Lenguaje a través del protocolo LSAP","fr":"Idéal pour les Agents de Codage IA nécessitant une interaction structurée avec les Serveurs de Langage via le protocole LSAP","de":"Ideal für AI-Coding-Agents, die eine strukturierte Interaktion mit Language-Servern über das LSAP-Protokoll erfordern","pt":"Ideal para Agentes de Codificação de IA que requerem interação estruturada com Servidores de Linguagem via protocolo LSAP","ru":"Идеально для агентов кодирования ИИ, требующих структурированного взаимодействия с языковыми серверами через протокол LSAP","ar":"مثالي للوكلاء الإيادي للذكاء الاصطناعي الذين يتطلبون تفاعلاً منظماً مع خوادم اللغة من خلال بروتوكول LSAP"},"recommendation":{"en":"Empowers agents to design and interact with LSAP APIs using a three-layered architecture, including schema, capability, and LSP layers, leveraging Pydantic for request/response models and Markdown templates for output","zh":"赋予代理设计和与LSAP API交互的能力，使用包括schema、capability和LSP层在内的三层架构，利用Pydantic进行请求/响应模型和Markdown模板进行输出","ja":"エージェントがスキーマ、キャパビリティ、LSPレイヤーを含む3層アーキテクチャを使用してLSAP APIを設計し、交互作用することを可能にし、Pydanticを使用してリクエスト/レスポンスモデルを作成し、Markdownテンプレートを使用して出力します","ko":"에이전트가 스키마, 능력, LSP 레이어를 포함한 3층 아키텍처를 사용하여 LSAP API를 설계하고 상호 작용할 수 있도록 하며, Pydantic를 사용하여 요청/응답 모델을 만들고 Markdown 템플릿을 사용하여 출력합니다","es":"Habilita a los agentes a diseñar e interactuar con APIs de LSAP utilizando una arquitectura de tres capas, que incluye esquema, capacidad y capas LSP, aprovechando Pydantic para modelos de solicitud/respuesta y plantillas de Markdown para la salida","fr":"Permet aux agents de concevoir et d''interagir avec des API LSAP en utilisant une architecture à trois couches, comprenant schéma, capacité et couches LSP, en exploitant Pydantic pour les modèles de requête/réponse et les modèles de Markdown pour la sortie","de":"Ermöglicht es den Agenten, LSAP-APIs zu entwerfen und zu interagieren, indem sie eine dreischichtige Architektur verwenden, die Schema, Fähigkeit und LSP-Schichten umfasst, wobei Pydantic für Anfrage/Antwort-Modelle und Markdown-Vorlagen für die Ausgabe genutzt wird","pt":"Habilita os agentes a projetar e interagir com APIs LSAP usando uma arquitetura de três camadas, incluindo esquema, capacidade e camadas LSP, utilizando Pydantic para modelos de solicitação/resposta e modelos de Markdown para saída","ru":"Предоставляет агентам возможность проектировать и взаимодействовать с API LSAP, используя трехслойную архитектуру, включающую схему, возможность и слои LSP, используя Pydantic для моделей запроса/ответа и шаблоны Markdown для вывода","ar":"تمكين الوكلاء من تصميم وتفاعل مع واجهات برمجة التطبيقات LSAP باستخدام هندسة ثلاثية الطبقات، بما في ذلك مخطط وقدرة وطبقات LSP، مع استخدام Pydantic لنمذجة الطلب والاستجابة وقوالب Markdown للخرج"},"useCases":{"en":["Designing new APIs for Language Server Agent Protocol","Implementing business logic and LSP orchestration for custom capabilities","Generating Markdown-first outputs with semantic anchoring via Locate"],"zh":["为语言服务器代理协议设计新的API","实现业务逻辑和LSP编排用于自定义能力","通过Locate生成带有语义锚定的Markdown-first输出"],"ja":["Language Server Agent Protocol用の新しいAPIを設計する","カスタム機能用のビジネスロジックとLSPオーケストレーションを実装する","Locate経由でセマンティックアンカー付きのMarkdown-first出力を生成する"],"ko":["언어 서버 에이전트 프로토콜용 새로운 API 설계","사용자 정의 기능을 위한 비즈니스 로직 및 LSP 오케스트레이션 구현","Locate를 통해 의미 있는 앵커가 있는 Markdown-첫 번째 출력 생성"],"es":["Diseñar nuevas API para el Protocolo de Agente de Servidor de Lenguaje","Implementar lógica empresarial y orquestación de LSP para capacidades personalizadas","Generar salidas de Markdown con anclaje semántico a través de Locate"],"fr":["Concevoir de nouvelles API pour le Protocole d''Agent de Serveur de Langage","Mettre en œuvre la logique métier et l''orchestration LSP pour les capacités personnalisées","Générer des sorties Markdown avec ancrage sémantique via Locate"],"de":["Entwerfen neuer APIs für das Language-Server-Agent-Protokoll","Implementieren von Geschäftslogik und LSP-Orchestrierung für benutzerdefinierte Fähigkeiten","Generieren von Markdown-Ausgaben mit semantischer Verankerung über Locate"],"pt":["Projeto de novas APIs para Protocolo de Agente do Servidor de Linguagem","Implementação de lógica de negócios e orquestração LSP para capacidades personalizadas","Geração de saídas Markdown-first com ancoragem semântica via Locate"],"ru":["Проектирование новых API для протокола агента языкового сервера","Реализация бизнес-логики и оркестровки LSP для пользовательских возможностей","Генерация вывода Markdown-first с семантической привязкой через Locate"],"ar":["تصميم واجهات برمجة تطبيقات جديدة لبروتوكول وكلاء خوادم اللغة","تنفيذ المنطق التجاري وتحكم LSP للقدرات المخصصة","توليد مخرجات Markdown-first مع ربط دلالي عبر Locate"]},"limitations":{"en":["Requires understanding of LSAP protocol and Language Server architecture","Python-based implementation with Pydantic and lsp-client library dependencies"],"zh":["需要理解LSAP协议和语言服务器架构","基于Python的实现，依赖Pydantic和lsp-client库"],"ja":["LSAPプロトコルとLanguage Serverアーキテクチャを理解する必要がある","Pythonベースの実装で、Pydanticとlsp-clientライブラリに依存する"],"ko":["LSAP 프로토콜 및 언어 서버 아키텍처를 이해해야 함","파이썬 기반 구현으로 Pydantic 및 lsp-client 라이브러리에 의존"],"es":["Requiere comprensión del protocolo LSAP y la arquitectura del Servidor de Lenguaje","Implementación basada en Python con dependencias de bibliotecas Pydantic y lsp-client"],"fr":["Nécessite une compréhension du protocole LSAP et de l''architecture du Serveur de Langage","Mise en œuvre basée sur Python avec des dépendances de bibliothèques Pydantic et lsp-client"],"de":["Erfordert Verständnis des LSAP-Protokolls und der Language-Server-Architektur","Python-basierte Implementierung mit Abhängigkeiten von Pydantic- und lsp-client-Bibliotheken"],"pt":["Exige compreensão do protocolo LSAP e arquitetura do Servidor de Linguagem","Implementação baseada em Python com dependências de bibliotecas Pydantic e lsp-client"],"ru":["Требует понимания протокола LSAP и архитектуры языкового сервера","Реализация на основе Python с зависимостями от библиотек Pydantic и lsp-client"],"ar":["يتطلب فهم بروتوكول LSAP وهندسة خادم اللغة","تنفيذ قائم على Python مع اعتماديات مكتبة Pydantic ومكتبة lsp-client"]},"version":4},"contentHash":"79b42205cdb59e9b4cb87b9482decfa02a336c03cdd60370a91fa4db9d0ab415","qualityScore":42}');
