INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('apptolast/FamilyFilmApp/mobile-design', 'mobile-design', 'apptolast', 'FamilyFilmApp', 'community', 'mobile-design apptolast FamilyFilmApp community The mobile-design skill enables developers to create touch-first, battery-conscious, and platform-respectful mobile applications. It benefits developers who need to design mobile interfaces with offline capabilities. 移动设计系统是一种基于触摸、节能、平台尊重和离线能力的设计哲学 モバイルデザインシステムはタッチファースト、バッテリー意識、プラットフォーム尊重、オフライン可能な設計哲学に基づくものです 모바일 디자인 시스템은 터치 우선, 배터리 сознательный, 플랫폼 존중, 오프라인 가능性的 설계 철학을 기반으로 합니다 El diseño móvil es fundamental para agentes de IA. Aprende a crear experiencias de usuario óptimas con nuestra guía La conception mobile est essentielle pour les outils d''IA. Découvrez comment créer des expériences utilisateur optimales avec notre guide Das mobile Design ist für KI-Agents von entscheidender Bedeutung. Erfahren Sie, wie Sie optimale Benutzererfahrungen mit unserem Leitfaden erstellen können O design móvel é uma abordagem touch-first, pensada para dispositivos móveis, com foco em UX e validação de scripts em Python Мобильный дизайн - это подход touch-first, предназначенный для мобильных устройств, с фокусом на UX и проверкой скриптов на Python التصميم المحمول هو نهج تعتمد على اللمس، مصمم لأجهزة الهاتف المحمول، مع التركيز على UX وتنفيذ البرامج النصية في Python how to use mobile-design what is mobile-design mobile-design alternative mobile-design vs responsive design mobile-design install mobile-design setup guide touch-first design principles platform-respectful mobile development offline-capable mobile applications 移动设计系统 AIエージェント 移动UX 触摸审计 Python脚本 离线能力 平台尊重 移动应用设计 Executes mobile UX and touch audits using scripts/mobile_audit.py Validates mobile applications for platform-respectful design Supports offline-capable mobile application development Applies core principle that mobile is not a small desktop Utilizes runtime scripts for validation and testing Runs on Python using commands like python scripts/mobile_audit.py mobile-design is a development approach that prioritizes touch-first interactions, battery efficiency, and platform-specific design, enabling the creation of effective mobile applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SylvainChabaud/spec-to-code-factory/factory-spec', 'community', 'SylvainChabaud', 'spec-to-code-factory', 'SylvainChabaud/spec-to-code-factory', 'factory-spec', 9, 2, 42, '2026-02-19T23:20:34Z', '2026-03-06T06:47:10.599Z', '1c71581457409be43a00f324c8704ee235056a1d50a7befc6e7f066904041edd', '{"id":"SylvainChabaud/spec-to-code-factory/factory-spec","name":"factory-spec","description":{"en":"factory-spec is a pipeline automation tool that transforms requirements.md into deliverable projects. It benefits developers by automating the spec-to-code process via 4 phases: BREAK, MODEL, ACT, and DEBRIEF.","zh":"Factory Spec是一种自动化的Spec-to-Code流程，通过4个阶段和5个验证门槛，实现项目的自动化交付","ja":"Factory Specは、4つの段階と5つの検証ゲートを通じてプロジェクトを自動的に納品するSpec-to-Codeの自動化プロセスです","ko":"Factory Spec은 4개의 단계와 5개의 검증 게이트를 통해 프로젝트를 자동으로 인도하는 Spec-to-Code 자동화 프로세스입니다","es":"Factory-spec es una herramienta de automatización de pipelines que transforma un archivo requirements.md en un proyecto entregable","fr":"Factory-spec est un outil d''automatisation de pipeline qui transforme un fichier requirements.md en un projet livrable","de":"Factory-spec ist ein Tool zur Automatisierung von Pipelines, das eine Datei requirements.md in ein ausführbares Projekt umwandelt","pt":"O Factory-Spec é uma ferramenta de automação de pipeline de código que transforma um arquivo requirements.md em um projeto entregaável","ru":"Factory-Spec - это инструмент автоматизации пайплайна кодирования, который преобразует файл requirements.md в доставляемый проект","ar":"Factory-Spec هو أداة آليّة لأنابيب الترميز التي تحول ملف requirements.md إلى مشروع قابل للتسليم"},"seo":{"title":{"en":"factory-spec: Automated Spec-to-Code Pipeline Setup Guide...","zh":"Factory Spec.Setup Guide - AI工具自动化Spec-to-Code","ja":"Factory Specベストプラクティス - AIエージェントによるSpec-to-Code自動化","ko":"Factory Spec 설정 가이드 - AI 에이전트를 사용한 Spec-to-Code 자동화","es":"Guía de configuración de factory-spec: Automatización de ...","fr":"Guide de démarrage de factory-spec: Pipeline automatisé S...","de":"Einrichtungsleitfaden für factory-spec: Automatisierte Pi...","pt":"Guia de Configuração do Factory-Spec: Automatize o Pipeli...","ru":"Настройка Factory-Spec: Автоматизация Пайплайна Кодирован...","ar":"دليل إعداد Factory-Spec: آليّة أنابيب الترميز مع وكلاء ال..."},"description":{"en":"Discover how factory-spec streamlines development with its 4-phase pipeline and 5 validation gates. Learn how to automate your spec-to-code workflow today!","zh":"了解Factory Spec的技术细节和工作流程，自动化Spec-to-Code流程，提高开发效率","ja":"Factory Specの技術的な詳細とワークフローを学び、Spec-to-Codeの自動化を実現し、開発効率を向上させる","ko":"Factory Spec의 기술적 세부 사항과 워크플로우를 학습하고, Spec-to-Code 자동화를 통해 개발 효율성을 개선합니다","es":"Aprende a configurar factory-spec para automatizar tus pipelines de desarrollo con 4 fases y 5 gates de validación","fr":"Découvrez comment démarrer avec factory-spec pour automatiser vos pipelines de développement via 4 phases et 5 portes de validation","de":"Erfahren Sie, wie Sie factory-spec einrichten, um Ihre Entwicklungs-Pipelines mit 4 Phasen und 5 Validierungstoren zu automatisieren","pt":"Aprenda a configurar o Factory-Spec para automatizar o pipeline de código com 4 fases e 5 portas de validação","ru":"Узнайте, как настроить Factory-Spec для автоматизации пайплайна кодирования с 4 фазами и 5 воротами валидации с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Factory-Spec لآليّة أنابيب الترميز مع 4 مراحل و 5 بوابات التحقق مع وكلاء الذكاء الاصطناعي"},"definition":{"en":"factory-spec is an automated Spec-to-Code pipeline tool that uses a 4-phase workflow with specialized agents, templates, and quality tools to deliver projects from requirements.md files.","zh":"Factory Spec是一种AI工具，用于自动化Spec-to-Code流程","ja":"Factory Specは、Spec-to-Codeの自動化に使用されるAIエージェントです","ko":"Factory Spec은 Spec-to-Code 자동화를 위한 AI 에이전트입니다","es":"Factory-spec es un agente de automatización de pipelines que utiliza 4 fases y 5 gates de validación","fr":"Factory-spec est un agent d''automatisation de pipeline qui utilise 4 phases et 5 portes de validation","de":"Factory-spec ist ein Agent zur Automatisierung von Pipelines, der 4 Phasen und 5 Validierungstoren verwendet","pt":"O que é Factory-Spec? É uma ferramenta de automação de pipeline de código que utiliza 4 fases e 5 portas de validação","ru":"Что такое Factory-Spec? Это инструмент автоматизации пайплайна кодирования, который использует 4 фазы и 5 ворот валидации","ar":"ما هو Factory-Spec? هو أداة آليّة لأنابيب الترميز التي تستخدم 4 مراحل و 5 بوابات التحقق"},"features":{"en":["Executes node tools/gate-check.js for Gate 1 validation","Runs node tools/factory-state.js to retrieve project state","Supports 4 phases: BREAK, MODEL, ACT, and DEBRIEF","Includes 5 gates of validation for quality assurance","Utilizes specialized agents and templates for automation"],"zh":["通过4个阶段（BREAK、MODEL、ACT、DEBRIEF）实现项目自动化交付","包含5个验证门槛，确保项目质量","使用node工具和JSON格式进行验证","支持greenfield和brownfield两种演化模式","可以读取和写入工厂状态"],"ja":["4つの段階（BREAK、MODEL、ACT、DEBRIEF）を通じてプロジェクトを自動的に納品する","5つの検証ゲートを含み、プロジェクトの品質を保証する","nodeツールとJSON形式を使用して検証を行う","greenfieldとbrownfieldの2つの進化モードをサポートする","ファクトリ状態を読み書きすることができる"],"ko":["4개의 단계（BREAK、MODEL、ACT、DEBRIEF）를 통해 프로젝트를 자동으로 인도하는","5개의 검증 게이트를 포함하여 프로젝트 품질을 보장한다","node 도구와 JSON 형식을 사용하여 검증을 수행한다","greenfield와 brownfield 두 가지 진화 모드를 지원한다","공장 상태를 읽고 쓸 수 있다"],"es":["Automatización de pipelines con 4 fases (BREAK, MODEL, ACT, DEBRIEF)","5 gates de validación para asegurar la calidad del proyecto","Uso de agents especializados y templates para agilizar el desarrollo","Herramientas de calidad integradas para garantizar la entrega de proyectos de alta calidad","Compatibilidad con herramientas de línea de comandos (CLI) como Node.js"],"fr":["Automatisation de pipeline avec 4 phases (BREAK, MODEL, ACT, DEBRIEF)","5 portes de validation pour assurer la qualité du projet","Utilisation d''agents spécialisés et de modèles pour accélérer le développement","Outils de qualité intégrés pour garantir la livraison de projets de haute qualité","Compatibilité avec les outils de ligne de commande (CLI) tels que Node.js"],"de":["Automatisierung von Pipelines mit 4 Phasen (BREAK, MODEL, ACT, DEBRIEF)","5 Validierungstoren, um die Qualität des Projekts zu gewährleisten","Verwendung spezialisierter Agenten und Vorlagen, um die Entwicklung zu beschleunigen","Integrierte Qualitätstools, um die Lieferung von Hochqualitätsprojekten zu gewährleisten","Kompatibilität mit Befehlszeilen-Tools (CLI) wie Node.js"],"pt":["Automatização de pipeline de código com 4 fases (BREAK, MODEL, ACT, DEBRIEF)","5 portas de validação para garantir a qualidade do código","Utilização de agentes especializados e templates para agilizar o desenvolvimento","Ferramentas de qualidade para garantir a entrega de projetos de alta qualidade","Compatibilidade com Node.js e CLI"],"ru":["Автоматизация пайплайна кодирования с 4 фазами (BREAK, MODEL, ACT, DEBRIEF)","5 ворот валидации для обеспечения качества кода","Использование специализированных агентов и шаблонов для ускорения разработки","Инструменты качества для обеспечения доставки проектов высокого качества","Совместимость с Node.js и CLI"],"ar":["آليّة أنابيب الترميز مع 4 مراحل (BREAK, MODEL, ACT, DEBRIEF)","5 بوابات التحقق لضمان جودة الكود","استخدام وكلاء متخصصين وقوالب لتعجيل التطوير","أدوات الجودة لضمان تسليم مشاريع ذات جودة عالية","التوافق مع Node.js و CLI"]},"keywords":{"en":["how to use factory-spec","factory-spec setup guide","factory-spec alternative","automated spec-to-code pipeline","factory-spec vs manual development","factory-spec install","what is factory-spec","factory-spec workflow automation","factory-spec quality tools"],"zh":["Factory Spec","AI工具","Spec-to-Code","自动化","node工具","JSON","greenfield","brownfield","工厂状态"],"ja":["Factory Spec","AIエージェント","Spec-to-Code","自動化","nodeツール","JSON","greenfield","brownfield","ファクトリ状態"],"ko":["Factory Spec","AI 에이전트","Spec-to-Code","자동화","node 도구","JSON","greenfield","brownfield","공장 상태"],"es":["factory-spec","automatización de pipelines","desarrollo de software","agente de automatización","herramientas de calidad","Node.js","CLI","pipelines de desarrollo","automatización de proyectos"],"fr":["factory-spec","automatisation de pipeline","développement de logiciels","agent d''automatisation","outils de qualité","Node.js","CLI","pipelines de développement","automatisation de projets"],"de":["factory-spec","Automatisierung von Pipelines","Software-Entwicklung","Automatisierungs-Agent","Qualitätstools","Node.js","CLI","Entwicklungs-Pipelines","Automatisierung von Projekten"],"pt":["Factory-Spec","automação de pipeline de código","desenvolvimento de software","Node.js","CLI","agentes especializados","templates","ferramentas de qualidade"],"ru":["Factory-Spec","автоматизация пайплайна кодирования","разработка программного обеспечения","Node.js","CLI","специализированные агенты","шаблоны","инструменты качества"],"ar":["Factory-Spec","آليّة أنابيب الترميز","تطوير البرمجيات","Node.js","CLI","وكلاء متخصصين","قوالب","أدوات الجودة"]}},"owner":"SylvainChabaud","repo":"spec-to-code-factory","repoPath":"SylvainChabaud/spec-to-code-factory","stars":9,"forks":2,"updatedAt":"2026-02-19T23:20:34Z","topics":[],"category":"community","skillMd":{"name":"factory-spec","description":"Phase MODEL - Génère specs + ADR + rules","bodyPreview":"# Factory Spec - Phase MODEL\n\nTu es l''orchestrateur de la phase MODEL.\n\n## Workflow\n\n1. **Verifier Gate 1 (entree)** :\n   ```bash\n   node tools/gate-check.js 1 --json\n   ```\n   - Si `status === \"FAIL\"` → STOP immediat (prerequis manquants, ne peut pas corriger).\n   - Terminer avec : `GATE_FAIL|1|<resume erreurs>|0`\n\n2. **Lire le state** :\n   ```bash\n   node tools/factory-state.js get\n   # Retourne: { \"evolutionMode\": \"greenfield|brownfield\", \"evolutionVersion\": N, \"requirementsFile\": \"...\", ...","body":"# Factory Spec - Phase MODEL\n\nTu es l''orchestrateur de la phase MODEL.\n\n## Workflow\n\n1. **Verifier Gate 1 (entree)** :\n   ```bash\n   node tools/gate-check.js 1 --json\n   ```\n   - Si `status === \"FAIL\"` → STOP immediat (prerequis manquants, ne peut pas corriger).\n   - Terminer avec : `GATE_FAIL|1|<resume erreurs>|0`\n\n2. **Lire le state** :\n   ```bash\n   node tools/factory-state.js get\n   # Retourne: { \"evolutionMode\": \"greenfield|brownfield\", \"evolutionVersion\": N, \"requirementsFile\": \"...\", ... }\n\n   # Lister les ADR actifs (brownfield : exclut SUPERSEDED)\n   node tools/list-active-adrs.js --summary\n\n   # Extraire le delta de la version courante (brownfield uniquement)\n   node tools/extract-version-delta.js -f brief -f scope\n   ```\n   Extraire : `evolutionMode`, `evolutionVersion`.\n\n3. **Deleguer aux agents** (sequentiel strict, UN A LA FOIS) :\n\n   **3a. Agent PM** (specs fonctionnelles) :\n   ```bash\n   # Instrumenter la delegation (les hooks ne fonctionnent pas dans les forks)\n   node tools/instrumentation/collector.js agent ''{\"agent\":\"pm\",\"source\":\"factory-spec\"}''\n   ```\n   ```\n   Task(\n     subagent_type: \"pm\",\n     prompt: \"Genere les specs fonctionnelles du projet.\n     Mode: <evolutionMode>. Version: <evolutionVersion>.\n     Si mode=greenfield: CREATE docs/specs/system.md et docs/specs/domain.md.\n     Si mode=brownfield: EDIT les specs existantes pour les mettre a jour.\n     DELTA VERSION COURANTE: <output de extract-version-delta.js>\n     Lis les fichiers BREAK: docs/brief.md, docs/scope.md, docs/acceptance.md.\n     Lis les templates: templates/specs/system.md, templates/specs/domain.md.\n     IMPORTANT: Respecte EXACTEMENT les headings des templates (##).\n     IMPORTANT: NE PAS inventer de numeros de version pour les librairies.\n     Ecrire uniquement le nom de la lib (ex: ''Tailwind CSS'', pas ''Tailwind CSS 3+'').\",\n     description: \"MODEL - PM specs\"\n   )\n   ```\n\n   **3b. Verification web des dependances et generation de stack-reference.md** (fait par le fork, AVANT l''architect) :\n\n   > **OBLIGATOIRE** : Verifier les dependances de la stack sur internet AVANT de deleguer a l''architect.\n   > Les LLMs ont souvent des connaissances obsoletes sur les versions recentes des libs.\n   > L''architect n''a pas acces a WebSearch/WebFetch — c''est le fork qui fournit les infos verifiees.\n\n   **Etape 1 : Identifier la stack dans le brief/scope**\n\n   Lire `docs/brief.md` et `docs/scope.md` pour extraire la liste des dependances prevues (framework, CSS lib, bundler, test runner, linter, chart lib, etc.).\n   Constituer une liste : `[ \"react\", \"tailwindcss\", \"vite\", \"vitest\", ... ]`.\n\n   **Etape 2 : Verifier les versions via npm registry** (source canonique)\n\n   Pour **chaque dependance** identifiee :\n   ```bash\n   npm view <package> version\n   # Retourne la derniere version stable (ex: \"19.1.0\")\n   ```\n   Si le nom npm n''est pas evident (ex: Tailwind CSS → `tailwindcss`), utiliser :\n   ```bash\n   npm search <lib> --json | head -5\n   ```\n\n   > **C''est la source la plus fiable** pour les numeros de version.\n   > Ne JAMAIS utiliser une version extraite d''une page web si elle contredit npm registry.\n\n   Compteur : noter le nombre de deps verifiees via npm (`verified_count`).\n\n   **Etape 3 : Rechercher les configs et breaking changes via web** (complementaire)\n\n   Pour **chaque dependance a risque de breaking changes** (identifiee dans le brief/scope) :\n\n   a. **Trouver la doc officielle** :\n      - `WebSearch` : `\"<lib> getting started\"` ou `\"<lib> installation guide\"`\n      - Privilegier les domaines officiels (npmjs.com, github.com/<org>, docs officiels)\n\n   b. **Extraire la configuration** :\n      - `WebFetch` sur la page d''installation officielle\n      - Extraire : packages a installer, fichiers de config requis, snippets de reference\n      - Copier le snippet EXACT depuis la doc (pas de memoire LLM)\n\n   c. **Identifier les breaking changes** :\n      - `WebSearch` : `\"<lib> migration guide\"` ou `\"<lib> upgrade from v<N-1>\"`\n      - Documenter : ancien pattern (a eviter) vs nouveau pattern (a utiliser)\n\n   > **Si WebSearch/WebFetch echoue** (rate limit, erreur reseau) : logger un warning et continuer.\n   > La verification configs/breaking changes est best-effort. Les versions npm sont obligatoires.\n\n   **Etape 4 : Seuil de fiabilite**\n\n   Calculer : `ratio = verified_count / total_deps`.\n   - Si `ratio >= 0.5` (50%+) → continuer normalement.\n   - Si `ratio < 0.5` → logger un warning :\n     ```bash\n     node tools/factory-log.js \"MODEL\" \"stack-warning\" \"Seuil de fiabilite non atteint: X/Y deps verifiees via npm. Risque de versions incorrectes.\"\n     ```\n     Continuer quand meme (ne pas bloquer), mais le warning sera visible dans les logs.\n\n   **Etape 5 : Generer `docs/specs/stack-reference.md`**\n\n   Lire le template `templates/specs/stack-reference.md`.\n   Creer le fichier `docs/specs/stack-reference.md` en remplissant :\n   - **Dependencies runtime** : tableau avec package, version exacte (depuis npm), commande install, URL source\n   - **Dependencies dev** : idem pour les deps de dev\n   - **Configurations de reference** : pour chaque lib necessitant un fichier de config, inclure le snippet EXACT copie depuis la doc officielle (pas de memoire LLM)\n   - **Compatibilite** : notes inter-dependances (ex: \"Tailwind v4 necessite @tailwindcss/vite\")\n   - **Breaking changes connus** : tableau ancien vs nouveau pour chaque lib avec breaking change\n\n   > **Ce fichier est la source de verite** pour toutes les etapes suivantes.\n   > L''architect et le developer doivent s''y referer, pas inventer de versions.\n\n   **Etape 6 : Logger**\n   ```bash\n   node tools/factory-log.js \"MODEL\" \"stack-verified\" \"Verification stack: X/Y deps verifiees via npm, Z configs web → docs/specs/stack-reference.md\"\n   ```\n\n   **3c. Agent Architect** (specs techniques + ADR, avec stack verifiee) :\n   ```bash\n   # Extraire le delta depuis les specs PM (disponibles apres 3a)\n   node tools/extract-version-delta.js -f system -f domain\n\n   # Instrumenter la delegation\n   node tools/instrumentation/collector.js agent ''{\"agent\":\"architect\",\"source\":\"factory-spec\"}''\n   ```\n   ```\n   Task(\n     subagent_type: \"architect\",\n     prompt: \"Genere les specs techniques et ADR.\n     Mode: <evolutionMode>. Version: <evolutionVersion>.\n     Si mode=greenfield: CREATE docs/specs/api.md, ADR-0001-stack.md, project-config.json.\n     Si mode=brownfield: EDIT api.md + CREATE nouveaux ADR + marquer anciens SUPERSEDED.\n     DELTA VERSION COURANTE: <output de extract-version-delta.js>\n     Lis les fichiers BREAK: docs/brief.md, docs/scope.md, docs/acceptance.md.\n     Lis les specs PM: docs/specs/system.md, docs/specs/domain.md.\n     Lis le fichier stack de reference: docs/specs/stack-reference.md.\n     Lis les templates: templates/specs/api.md, templates/adr/ADR-template.md, templates/specs/project-config.json.\n     IMPORTANT: Respecte EXACTEMENT les headings des templates (##).\n\n     STACK REFERENCE (source de verite - UTILISE CES VERSIONS ET CONFIGS, PAS TA MEMOIRE) :\n     Lis docs/specs/stack-reference.md pour toutes les versions, packages et configs.\n\n     Pour chaque dependance dans l''ADR :\n     - Utilise la version exacte et les packages indiques dans stack-reference.md\n     - Inclus les snippets de configuration de reference dans une section ''## Configuration de reference'' de l''ADR\n     - Si une lib a un setup specifique (ex: plugin Vite au lieu de PostCSS), documente-le\n     - NE PAS inventer de config : utilise UNIQUEMENT les infos de stack-reference.md\",\n     description: \"MODEL - Architect specs\"\n   )\n   ```\n\n   **3d. Agent Rules-Memory** (rules Claude Code) :\n   ```bash\n   # Extraire le delta depuis toutes les specs (disponibles apres 3a+3c)\n   node tools/extract-version-delta.js -f system -f domain -f api\n\n   # Instrumenter la delegation\n   node tools/instrumentation/collector.js agent ''{\"agent\":\"rules-memory\",\"source\":\"factory-spec\"}''\n   ```\n   ```\n   Task(\n     subagent_type: \"rules-memory\",\n     prompt: \"Genere les rules Claude Code pour le projet.\n     Mode: <evolutionMode>. Version: <evolutionVersion>.\n     Si mode=greenfield: CREATE les rules dans .claude/rules/.\n     Si mode=brownfield: mettre a jour les rules existantes, supprimer les obsoletes.\n     ADR ACTIFS: <liste des paths retournes par list-active-adrs.js --summary>\n     DELTA VERSION COURANTE: <output de extract-version-delta.js>\n     IMPORTANT: NE PAS charger les ADR au statut SUPERSEDED.\n     Lis les specs: docs/specs/system.md, docs/specs/domain.md, docs/specs/api.md.\n     Lis le template: templates/rule.md.\",\n     description: \"MODEL - Rules generation\"\n   )\n   ```\n\n4. **Executer Gate 2 (sortie avec auto-remediation)** :\n\n   ```bash\n   node tools/gate-check.js 2 --json\n   ```\n\n   Suivre le **protocole standard de gate handling** :\n\n   **Tentative 1** : Analyser le JSON retourne.\n   - Si `status === \"PASS\"` → continuer a l''etape 5.\n   - Si `status === \"FAIL\"` :\n     - Lire `errors[]`. Pour chaque erreur `fixable: true` :\n       - `missing_section` → identifier le fichier et le template de reference dans le message d''erreur (`ref: templates/...`). Relancer l''agent responsable avec prompt : \"Corrige [fichier]. Section manquante : [section]. Lis le template [template] et respecte exactement les headings.\"\n       - `missing_file` → identifier le fichier manquant :\n         - `stack-reference.md` → re-executer l''etape 3b (verification web + generation du fichier). C''est le fork qui le fait, pas un agent.\n         - `system.md` / `domain.md` → relancer l''agent PM (step 3a).\n         - `api.md` → relancer l''agent architect (step 3c).\n         - Autre → relancer l''agent responsable.\n       - `missing_pattern` → identifier le pattern manquant :\n         - `.claude/rules/*.md` → relancer l''agent rules-memory (step 3d).\n         - `docs/adr/ADR-*` → relancer l''agent architect (step 3c).\n       - `config` → relancer l''architect pour corriger project-config.json.\n       - `security` → corriger les secrets/PII directement.\n     - Pour chaque erreur `fixable: false` → STOP, ne pas retenter.\n     - Re-executer : `node tools/gate-check.js 2 --json`\n\n   **Tentative 2** : Relancer les agents fautifs complets (PM, architect ou rules-memory selon les erreurs restantes).\n   - Re-executer : `node tools/gate-check.js 2 --json`\n\n   **Tentative 3** : Si toujours FAIL, retourner le rapport d''echec.\n   - **NE PAS continuer le pipeline.**\n   - Terminer avec : `GATE_FAIL|2|<resume erreurs separees par ;>|3`\n\n5. **Sync ADR** (brownfield) :\n   ```bash\n   node tools/list-active-adrs.js --summary\n   ```\n\n6. **Logger** via :\n   ```bash\n   node tools/factory-log.js \"MODEL\" \"completed\" \"Phase MODEL terminee\"\n   ```\n\n7. **Retourner** un resume avec liste des fichiers generes (chemins complets).\n\n## Protocole d''echec\n\n- **Gate d''entree** (Gate 1) : Si FAIL → STOP immediat + marqueur `GATE_FAIL|1|...|0`.\n- **Gate de sortie** (Gate 2) : Auto-remediation 3x puis marqueur `GATE_FAIL|2|...|3` si echec persistant.\n- **Jamais** de STOP silencieux — toujours retourner un rapport structure.\n"},"lastSynced":"2026-03-06T06:47:10.599Z","agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents requiring pipeline automation and spec-to-code transformation capabilities.","zh":"适用于需要流水线自动化和规格到代码转换功能的自动化代理。","ja":"パイプライン自動化および仕様からコードへの変換機能を必要とする自動化エージェントに適しています。","ko":"파이프라인 자동화 및 규격에서 코드로의 변환 기능을 필요로 하는 자동화 에이전트에 적합합니다.","es":"Ideal para Automation Agents que requieren capacidades de automatización de pipelines y transformación de especificaciones a código.","fr":"Idéal pour les Automation Agents nécessitant des capacités d''automatisation de pipeline et de transformation de spécifications en code.","de":"Ideal für Automation Agents, die Pipeline-Automatisierung und Fähigkeiten zur Transformation von Spezifikationen in Code erfordern.","pt":"Ideal para Agentes de Automação que requerem automação de pipeline e capacidades de transformação de especificação em código.","ru":"Идеально подходит для Automation Agents, требующих автоматизации конвейера и возможностей преобразования спецификации в код.","ar":"مثالي لوكلاء الأتمتة الذين يتطلبون أتمتة خطوط الأنابيب وقدرات تحويل المواصفات إلى كود."},"recommendation":{"en":"Empowers agents to automate the spec-to-code process via 4 phases: BREAK, MODEL, ACT, and DEBRIEF, utilizing Node.js and JSON, and executing scripts like gate-check.js and factory-state.js.","zh":"通过4个阶段的BREAK、MODEL、ACT和DEBRIEF，利用Node.js和JSON，执行gate-check.js和factory-state.js等脚本，赋予代理自动化规格到代码的过程。","ja":"BREAK、MODEL、ACT、DEBRIEFの4つのフェーズを経て、Node.jsとJSONを利用し、gate-check.jsやfactory-state.jsなどのスクリプトを実行することで、エージェントが仕様からコードへのプロセスを自動化できるようになります。","ko":"BREAK, MODEL, ACT, DEBRIEF의 4단계를 통해 Node.js와 JSON을 활용하고 gate-check.js와 factory-state.js 등의 스크립트를 실행하여 에이전트가 규격에서 코드로의 프로세스를 자동화하도록 합니다.","es":"Permite a los agentes automatizar el proceso de especificación a código mediante 4 fases: BREAK, MODEL, ACT y DEBRIEF, utilizando Node.js y JSON, y ejecutando scripts como gate-check.js y factory-state.js.","fr":"Permet aux agents d''automatiser le processus de spécification à code via 4 phases : BREAK, MODEL, ACT et DEBRIEF, en utilisant Node.js et JSON, et en exécutant des scripts comme gate-check.js et factory-state.js.","de":"Ermöglicht Agents, den Spezifikation-zu-Code-Prozess über 4 Phasen zu automatisieren: BREAK, MODEL, ACT und DEBRIEF, unter Verwendung von Node.js und JSON und der Ausführung von Skripten wie gate-check.js und factory-state.js.","pt":"Capacita os agentes a automatizar o processo de especificação para código através de 4 fases: BREAK, MODEL, ACT e DEBRIEF, utilizando Node.js e JSON, e executando scripts como gate-check.js e factory-state.js.","ru":"Позволяет агентам автоматизировать процесс преобразования спецификации в код через 4 фазы: BREAK, MODEL, ACT и DEBRIEF, используя Node.js и JSON, и выполняя скрипты, такие как gate-check.js и factory-state.js.","ar":"يمكن الوكلاء من أتمتة عملية تحويل المواصفات إلى كود عبر 4 مراحل: BREAK، MODEL، ACT، وDEBRIEF، باستخدام Node.js وJSON، وتنفيذ نصوص برمجية مثل gate-check.js وfactory-state.js."},"useCases":{"en":["Automating the verification of prerequisites using Verifier Gate 1","Generating project deliverables by transforming requirements.md files","Debugging pipeline automation issues using the DEBRIEF phase"],"zh":["使用Verifier Gate 1自动验证前提条件","通过转换requirements.md文件生成项目交付成果","使用DEBRIEF阶段调试流水线自动化问题"],"ja":["Verifier Gate 1を使用して前提条件を自動検証する","requirements.mdファイルを変換してプロジェクトの成果物を生成する","DEBRIEFフェーズを使用してパイプライン自動化の問題をデバッグする"],"ko":["Verifier Gate 1을 사용하여 전제 조건을 자동으로 검증하는 것","requirements.md 파일을 변환하여 프로젝트 성과物을 생성하는 것","DEBRIEF 단계를 사용하여 파이프라인 자동화 문제를 디버깅하는 것"],"es":["Automatización de la verificación de prerrequisitos utilizando Verifier Gate 1","Generación de entregables de proyecto transformando archivos requirements.md","Depuración de problemas de automatización de pipelines utilizando la fase DEBRIEF"],"fr":["Automatisation de la vérification des prérequis en utilisant Verifier Gate 1","Génération des livrables du projet en transformant les fichiers requirements.md","Débogage des problèmes d''automatisation de pipeline en utilisant la phase DEBRIEF"],"de":["Automatisierung der Verifizierung von Voraussetzungen mit Verifier Gate 1","Generierung von Projektliefergegenständen durch die Transformation von requirements.md-Dateien","Debugging von Pipeline-Automatisierungsproblemen unter Verwendung der DEBRIEF-Phase"],"pt":["Automatizando a verificação de pré-requisitos usando o Verifier Gate 1","Gerando entregas de projeto transformando arquivos requirements.md","Depurando problemas de automação de pipeline usando a fase DEBRIEF"],"ru":["Автоматизация проверки предварительных условий с использованием Verifier Gate 1","Генерация результатов проекта путем преобразования файлов requirements.md","Отладка проблем автоматизации конвейера с использованием фазы DEBRIEF"],"ar":["أتمتة التحقق من المتطلبات الأساسية باستخدام Verifier Gate 1","إنشاء نتائج المشروع عن طريق تحويل ملفات requirements.md","تصحيح مشكلات أتمتة خطوط الأنابيب باستخدام مرحلة DEBRIEF"]},"limitations":{"en":["Requires Node.js environment","Dependent on specific scripts like gate-check.js and factory-state.js","Limited to JSON output format"],"zh":["需要Node.js环境","依赖于特定脚本，如gate-check.js和factory-state.js","仅限于JSON输出格式"],"ja":["Node.js環境を必要とする","gate-check.jsやfactory-state.jsなどの特定のスクリプトに依存する","出力形式はJSONのみ"],"ko":["Node.js 환경이 필요함","gate-check.js 및 factory-state.js와 같은 특정 스크립트에 의존함","출력 형식은 JSON만 가능함"],"es":["Requiere un entorno Node.js","Depende de scripts específicos como gate-check.js y factory-state.js","Limitado al formato de salida JSON"],"fr":["Nécessite un environnement Node.js","Dépend de scripts spécifiques comme gate-check.js et factory-state.js","Limité au format de sortie JSON"],"de":["Erfordert eine Node.js-Umgebung","Abhängig von spezifischen Skripten wie gate-check.js und factory-state.js","Beschränkt auf das JSON-Ausgabeformat"],"pt":["Requer ambiente Node.js","Dependente de scripts específicos como gate-check.js e factory-state.js","Limitado ao formato de saída JSON"],"ru":["Требует среду Node.js","Зависит от конкретных скриптов, таких как gate-check.js и factory-state.js","Ограничен форматом вывода JSON"],"ar":["يتطلب بيئة Node.js","يعتمد على نصوص برمجية محددة مثل gate-check.js وfactory-state.js","مقتصر على تنسيق إخراج JSON"]},"version":4},"contentHash":"1c71581457409be43a00f324c8704ee235056a1d50a7befc6e7f066904041edd","qualityScore":42}');
DELETE FROM skills_fts WHERE id = 'SylvainChabaud/spec-to-code-factory/factory-spec';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SylvainChabaud/spec-to-code-factory/factory-spec', 'factory-spec', 'SylvainChabaud', 'spec-to-code-factory', 'community', 'factory-spec SylvainChabaud spec-to-code-factory community factory-spec is a pipeline automation tool that transforms requirements.md into deliverable projects. It benefits developers by automating the spec-to-code process via 4 phases: BREAK, MODEL, ACT, and DEBRIEF. Factory Spec是一种自动化的Spec-to-Code流程，通过4个阶段和5个验证门槛，实现项目的自动化交付 Factory Specは、4つの段階と5つの検証ゲートを通じてプロジェクトを自動的に納品するSpec-to-Codeの自動化プロセスです Factory Spec은 4개의 단계와 5개의 검증 게이트를 통해 프로젝트를 자동으로 인도하는 Spec-to-Code 자동화 프로세스입니다 Factory-spec es una herramienta de automatización de pipelines que transforma un archivo requirements.md en un proyecto entregable Factory-spec est un outil d''automatisation de pipeline qui transforme un fichier requirements.md en un projet livrable Factory-spec ist ein Tool zur Automatisierung von Pipelines, das eine Datei requirements.md in ein ausführbares Projekt umwandelt O Factory-Spec é uma ferramenta de automação de pipeline de código que transforma um arquivo requirements.md em um projeto entregaável Factory-Spec - это инструмент автоматизации пайплайна кодирования, который преобразует файл requirements.md в доставляемый проект Factory-Spec هو أداة آليّة لأنابيب الترميز التي تحول ملف requirements.md إلى مشروع قابل للتسليم how to use factory-spec factory-spec setup guide factory-spec alternative automated spec-to-code pipeline factory-spec vs manual development factory-spec install what is factory-spec factory-spec workflow automation factory-spec quality tools Factory Spec AI工具 Spec-to-Code 自动化 node工具 JSON greenfield brownfield 工厂状态 Executes node tools/gate-check.js for Gate 1 validation Runs node tools/factory-state.js to retrieve project state Supports 4 phases: BREAK, MODEL, ACT, and DEBRIEF Includes 5 gates of validation for quality assurance Utilizes specialized agents and templates for automation factory-spec is an automated Spec-to-Code pipeline tool that uses a 4-phase workflow with specialized agents, templates, and quality tools to deliver projects from requirements.md files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blinqas/station/terraform-station-module', 'community', 'blinqas', 'station', 'blinqas/station', 'terraform-station-module', 9, 1, 42, '2026-02-27T11:40:30Z', '2026-03-06T06:48:16.793Z', '1e1a57d4ef004cd6198a42df2f12ade4707c91f42725cf192ac631c6af55f171', '{"id":"blinqas/station/terraform-station-module","name":"terraform-station-module","description":{"en":"This AI agent skill assists developers in implementing and modifying the Terraform Station module for Azure. It provides expertise for updating root module files, child modules, and module interfaces to create secure, automated environments.","zh":"Terraform Station模块技能用于创建安全和自动化的Azure环境，支持模块代码更改和测试执行","ja":"Terraform Stationモジュールスキルを使用してAzure環境を安全に自動化し、モジュールコードの変更とテストの実行をサポート","ko":"Terraform Station 모듈 스킬을 사용하여 Azure 환경을 보안하고 자동화하며 모듈 코드 변경 및 테스트 실행을 지원","es":"Terraform-station-module es un skill para crear entornos automatizados en Azure. Permite la implementación de lógica de módulos y la actualización de módulos secundarios","fr":"Terraform-station-module est un skill pour créer des environnements automatisés sur Azure. Il permet l''implémentation de la logique de modules et la mise à jour des sous-modules","de":"Terraform-station-module ist ein Skill für die Erstellung automatisierter Umgebungen in Azure. Es ermöglicht die Implementierung von Modullogik und die Aktualisierung von Untermodulen","pt":"O módulo Terraform Station permite criar ambientes seguros e automatizados no Azure. Ele é usado para alterar o comportamento em arquivos de módulo raiz e atualizar módulos filhos.","ru":"Модуль Terraform Station позволяет создавать безопасные и автоматизированные среды в Azure. Он используется для изменения поведения в корневых файлах модуля и обновления дочерних модулей.","ar":"موديل Terraform Station يسمح بإنشاء بيئات آمنة وآلية في Azure. يستخدم لتح