INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blinqas/station/terraform-station-module', 'terraform-station-module', 'blinqas', 'station', 'community', 'terraform-station-module blinqas station community This AI agent skill assists developers in implementing and modifying the Terraform Station module for Azure. It provides expertise for updating root module files, child modules, and module interfaces to create secure, automated environments. Terraform Station模块技能用于创建安全和自动化的Azure环境，支持模块代码更改和测试执行 Terraform Stationモジュールスキルを使用してAzure環境を安全に自動化し、モジュールコードの変更とテストの実行をサポート Terraform Station 모듈 스킬을 사용하여 Azure 환경을 보안하고 자동화하며 모듈 코드 변경 및 테스트 실행을 지원 Terraform-station-module es un skill para crear entornos automatizados en Azure. Permite la implementación de lógica de módulos y la actualización de módulos secundarios Terraform-station-module est un skill pour créer des environnements automatisés sur Azure. Il permet l''implémentation de la logique de modules et la mise à jour des sous-modules Terraform-station-module ist ein Skill für die Erstellung automatisierter Umgebungen in Azure. Es ermöglicht die Implementierung von Modullogik und die Aktualisierung von Untermodulen O módulo Terraform Station permite criar ambientes seguros e automatizados no Azure. Ele é usado para alterar o comportamento em arquivos de módulo raiz e atualizar módulos filhos. Модуль Terraform Station позволяет создавать безопасные и автоматизированные среды в Azure. Он используется для изменения поведения в корневых файлах модуля и обновления дочерних модулей. موديل Terraform Station يسمح بإنشاء بيئات آمنة وآلية في Azure. يستخدم لتحديث سلوك الملفات الرئيسية للموديل وتحديث الموديلات الفرعية. how to use terraform-station-module terraform-station-module vs terraform-station-test terraform-station-module install update azure station module variables.tf what is the station module application/ child module terraform-station-module setup guide station module hashicorp tfe configuration automate azure workloads with terraform Terraform Station模块 Azure环境自动化 模块代码更改 模块测试执行 根模块文件 子模块更新 模块接口更新 AIエージェント Terraform Modifies root module files (*.tf) at the repository root Updates specific child modules including application/ and group/ Manages user_assigned_identity/ child module configurations Handles changes to the hashicorp/tfe/ module Refines module interfaces by updating variables.tf files Focuses on implementation logic for code changes, not test authoring terraform-station-module is an AI agent skill designed for developers working on the Station module''s Terraform code. It specifically aids in modifying root module files (*.tf), updating child modules like application/ and group/, and refining module interfaces in variables.tf.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('photostructure/node-sqlite/tpp', 'community', 'photostructure', 'node-sqlite', 'photostructure/node-sqlite', 'tpp', 6, 0, 42, '2026-02-24T03:34:31Z', '2026-03-06T06:53:11.432Z', 'e7b4578bbdcad8cbaa6b9c2bcd9df9b47b853f141cc0d66b51af1a8de353db0b', '{"id":"photostructure/node-sqlite/tpp","name":"tpp","description":{"en":"The tpp skill is a drop-in replacement for node:sqlite, designed for developers seeking a seamless database management experience. It benefits developers working with SQLite databases.","zh":"TPP是一个Node.js的SQLite替代方案，通过阅读相关文档，开发者可以了解TPP的工作原理和使用方法","ja":"TPPはNode.jsのSQLiteの代替です。関連文書を読むことで、開発者はTPPの動作原理と使用方法を理解できます","ko":"TPP는 Node.js의 SQLite대체 솔루션입니다. 관련 문서를 읽음으로써 개발자는 TPP의 작동 원리와 사용 방법을 이해할 수 있습니다","es":"tpp es un reemplazo de node:sqlite que ofrece una alternativa para el desarrollo de aplicaciones. Se basa en principios de diseño simples y desarrollo dirigido por pruebas","fr":"tpp est un remplacement de node:sqlite qui offre une alternative pour le développement d''applications. Il repose sur des principes de conception simples et un développement dirigé par des tests","de":"tpp ist ein Ersatz für node:sqlite, der eine Alternative für die Entwicklung von Anwendungen bietet. Es basiert auf einfachen Designprinzipien und testgetriebenem Entwickeln","pt":"O TPP é uma substituição drop-in para o node:sqlite, oferecendo recursos avançados para desenvolvedores. Aprenda a configurá-lo e melhorar seu desenvolvimento","ru":"ИИ Агент TPP является заменой node:sqlite, предлагающей передовые возможности для разработчиков. Узнайте, как настроить и улучшить свое развитие","ar":"TPP هو بديل إسقاط ل node:sqlite، يوفر ميزات متقدمة للمطورين. تعرف على كيفية إعدادها وطور تطويرك"},"seo":{"title":{"en":"tpp: Drop-in Replacement for node:sqlite Setup Guide | AI...","zh":"TPP_SETUP GUIDE: Node.js SQLite替代方案","ja":"TPPセットアップガイド: Node.jsのSQLite代替","ko":"TPP설치 가이드: Node.js SQLite대체 솔루션","es":"Guía de configuración de tpp, reemplazo de node:sqlite","fr":"Guide de configuration de tpp, remplacement de node:sqlite","de":"Konfigurationsleitfaden für tpp, Ersatz für node:sqlite","pt":"Guia de Configuração do TPP: Substituto Drop-in para node...","ru":"ИИ Агент TPP: Настройка Замены node:sqlite","ar":"دليل إعداد TPP: بديل إسقاط ل node:sqlite"},"description":{"en":"Discover how tpp simplifies database management. Learn how to replace node:sqlite with tpp and improve your development workflow today!","zh":"了解TPP，一个Node.js SQLite的替代方案，通过阅读CLAUDE和SIMPLE-DESIGN等必读文档，掌握TPP的工作流程","ja":"TPPとは、Node.jsのSQLiteの代替です。CLAUDEやSIMPLE-DESIGNなどの必読文書を読み、TPPのワークフローをマスターしましょう","ko":"TPP는 Node.js SQLite의 대체 솔루션입니다. CLAUDE와 SIMPLE-DESIGN 등의 필독 문서를 읽고 TPP의 작업 흐름을 익히세요","es":"Descubre cómo configurar tpp, una alternativa a node:sqlite, y aprovecha sus características técnicas para mejorar tus proyectos de desarrollo","fr":"Découvrez comment configurer tpp, une alternative à node:sqlite, et profitez de ses fonctionnalités techniques pour améliorer vos projets de développement","de":"Erfahren Sie, wie Sie tpp konfigurieren, eine Alternative zu node:sqlite, und nutzen Sie seine technischen Funktionen, um Ihre Entwicklungsprojekte zu verbes...","pt":"Aprenda a configurar o TPP, uma substituição drop-in para o node:sqlite, e melhore seu desenvolvimento com recursos técnicos avançados","ru":"Узнайте, как настроить ИИ Агент TPP, замену node:sqlite, и улучшите свое развитие с помощью передовых технических возможностей","ar":"تعرف على كيفية إعداد TPP، بديل إسقاط ل node:sqlite، وطور تطويرك باستخدام الميزات الفنية المتقدمة"},"definition":{"en":"tpp is a drop-in replacement for node:sqlite, providing an alternative for database management in development projects.","zh":"TPP是Node.js中的一个SQLite替代方案，提供了类似的功能和特性","ja":"TPPはNode.jsのSQLiteの代替であり、類似の機能と特性を提供します","ko":"TPP는 Node.js의 SQLite대체 솔루션으로서 유사한 기능과 특징을 제공합니다","es":"tpp es un reemplazo de node:sqlite que permite a los desarrolladores crear aplicaciones de manera más eficiente","fr":"tpp est un remplacement de node:sqlite qui permet aux développeurs de créer des applications de manière plus efficace","de":"tpp ist ein Ersatz für node:sqlite, der es Entwicklern ermöglicht, Anwendungen effizienter zu erstellen","pt":"O que é TPP? Uma substituição drop-in para o node:sqlite, projetada para melhorar o desenvolvimento com recursos técnicos avançados","ru":"Что такое ИИ Агент TPP? Замена node:sqlite, предназначенная для улучшения разработки с помощью передовых технических возможностей","ar":"ما هو TPP؟ بديل إسقاط ل node:sqlite، مصمم لتحسين التطوير باستخدام الميزات الفنية المتقدمة"},"features":{"en":["Replaces node:sqlite for simplified database management","Requires reading of CLAUDE.md for project rules and patterns","Implements Test-driven Development (TDD) as outlined in TDD.md","Follows Kent Beck''s Simple Design principles from SIMPLE-DESIGN.md","Adheres to the TPP style guide outlined in TPP-GUIDE.md"],"zh":["支持Node.js的SQLite替代","遵循CLAUDE和SIMPLE-DESIGN的设计原则","支持Test-driven development（TDD）","提供TPP-GUIDE风格指南","支持多阶段工作流程","集成CLAUDE和SIMPLE-DESIGN的最佳实践"],"ja":["Node.jsのSQLiteの代替をサポート","CLAUDEとSIMPLE-DESIGNの設計原則に従う","Test-driven development（TDD）をサポート","TPP-GUIDEスタイルガイドを提供","多段階のワークフローをサポート","CLAUDEとSIMPLE-DESIGNのベストプラクティスを統合"],"ko":["Node.js의 SQLite대체를 지원","CLAUDE와 SIMPLE-DESIGN의 설계 원칙을 따름","Test-driven development（TDD）를 지원","TPP-GUIDE스타일 가이드를 제공","다단계 작업 흐름을 지원","CLAUDE와 SIMPLE-DESIGN의 최선의 관행을 통합"],"es":["Reemplazo de node:sqlite","Diseño simple basado en los principios de Kent Beck","Desarrollo dirigido por pruebas (TDD)","Compatibilidad con proyectos de desarrollo de aplicaciones","Seguimiento de un plan de proyecto técnico (TPP)"],"fr":["Remplacement de node:sqlite","Conception simple basée sur les principes de Kent Beck","Développement dirigé par des tests (TDD)","Compatibilité avec les projets de développement d''applications","Suivi d''un plan de projet technique (TPP)"],"de":["Ersatz für node:sqlite","Einfaches Design basierend auf den Prinzipien von Kent Beck","Testgetriebenes Entwickeln (TDD)","Kompatibilität mit Entwicklungsprojekten für Anwendungen","Verfolgung eines technischen Projektplans (TPP)"],"pt":["Substituição drop-in para node:sqlite","Compatibilidade com projetos existentes","Recursos avançados para desenvolvedores","Suporte a Test-Driven Development (TDD)","Integração com Kent Beck''s Simple Design"],"ru":["Замена node:sqlite","Совместимость с существующими проектами","Передовые возможности для разработчиков","Поддержка Test-Driven Development (TDD)","Интеграция с Kent Beck''s Simple Design"],"ar":["بديل إسقاط ل node:sqlite","الت ､ألمكانية مع المشاريع الحالية","الميزات المتقدمة للمطورين","دعم التطوير القائم على الاختبار (TDD)","التكامل مع Kent Beck''s Simple Design"]},"keywords":{"en":["how to use tpp","tpp alternative to node:sqlite","tpp vs node:sqlite","tpp setup guide","what is tpp","tpp install","tpp database management","tpp drop-in replacement","tpp for developers"],"zh":["TPP","Node.js","SQLite","CLAUDE","SIMPLE-DESIGN","TDD","TPP-GUIDE","AIエージェント","Node.js开发","SQLite替代方案"],"ja":["TPP","Node.js","SQLite","CLAUDE","SIMPLE-DESIGN","TDD","TPP-GUIDE","AIエージェント","Node.js開発","SQLiteの代替"],"ko":["TPP","Node.js","SQLite","CLAUDE","SIMPLE-DESIGN","TDD","TPP-GUIDE","AI에이전트","Node.js개발","SQLite대체 솔루션"],"es":["tpp","node:sqlite","desarrollo de aplicaciones","diseño simple","desarrollo dirigido por pruebas","plan de proyecto técnico","herramientas de desarrollo","alternativas a node:sqlite","agentes de inteligencia artificial","herramientas de IA para desarrolladores"],"fr":["tpp","node:sqlite","développement d''applications","conception simple","développement dirigé par des tests","plan de projet technique","outils de développement","alternatives à node:sqlite","agents d''intelligence artificielle","outils d''IA pour développeurs"],"de":["tpp","node:sqlite","Anwendungsentwicklung","einfaches Design","testgetriebenes Entwickeln","technischer Projektplan","Entwicklungstools","Alternativen zu node:sqlite","Künstliche Intelligenz Agenten","KI-Tools für Entwickler"],"pt":["TPP","node:sqlite","substituição drop-in","desenvolvimento de software","TDD","Kent Beck''s Simple Design","recursos avançados para desenvolvedores","configuração do TPP","guias de desenvolvimento"],"ru":["ИИ Агент TPP","node:sqlite","замена","разработка программного обеспечения","TDD","Kent Beck''s Simple Design","передовые возможности для разработчиков","настройка ИИ Агента TPP","руководства по разработке"],"ar":["TPP","node:sqlite","بديل إسقاط","تطوير البرمجيات","TDD","Kent Beck''s Simple Design","الميزات المتقدمة للمطورين","إعداد TPP","دلائل التطوير"]}},"owner":"photostructure","repo":"node-sqlite","repoPath":"photostructure/node-sqlite","stars":6,"forks":0,"updatedAt":"2026-02-24T03:34:31Z","topics":[],"category":"community","skillMd":{"name":"tpp","description":"Work on a Technical Project Plan - research, design, implement, or complete tasks based on current phase. Use when starting or continuing work on a TPP.","bodyPreview":"# Work on TPP\n\nMake progress on the referenced Technical Project Plan. Determine the current phase and take appropriate action.\n\n## Required Reading First\n\nBefore any work, you MUST read:\n\n- [CLAUDE.md](CLAUDE.md) - Project rules and patterns\n- [SIMPLE-DESIGN.md](doc/reference/SIMPLE-DESIGN.md) - Kent Beck''s Simple Design\n- [TDD.md](doc/reference/TDD.md) - Test-driven development\n- [TPP-GUIDE.md](doc/reference/TPP-GUIDE.md) - TPP style guide\n\n## Process\n\n### 1. Read the TPP\n\nFind and read the re","body":"# Work on TPP\n\nMake progress on the referenced Technical Project Plan. Determine the current phase and take appropriate action.\n\n## Required Reading First\n\nBefore any work, you MUST read:\n\n- [CLAUDE.md](CLAUDE.md) - Project rules and patterns\n- [SIMPLE-DESIGN.md](doc/reference/SIMPLE-DESIGN.md) - Kent Beck''s Simple Design\n- [TDD.md](doc/reference/TDD.md) - Test-driven development\n- [TPP-GUIDE.md](doc/reference/TPP-GUIDE.md) - TPP style guide\n\n## Process\n\n### 1. Read the TPP\n\nFind and read the referenced TPP from `doc/todo/` (named `${priority}-${desc}.md`). Identify the current phase from the checklist.\n\n### 2. Take Action Based on Phase\n\n| Phase                    | Action                                                                   |\n| ------------------------ | ------------------------------------------------------------------------ |\n| **Research & Planning**  | Read referenced docs and code. Gather context. Update TPP with findings. |\n| **Write breaking tests** | Follow TDD approach - write failing tests first.                         |\n| **Design alternatives**  | Iterate on design with critiques, consider multiple approaches.          |\n| **Breakdown of tasks**   | Create specific, verifiable task list with commands.                     |\n| **Implementation**       | Work through tasks sequentially. Update TPP as you go.                   |\n| **Review & Refinement**  | Review changed code. Address issues. Check API compatibility.            |\n| **Final Integration**    | Run full test suite. Verify all acceptance criteria.                     |\n| **Review**               | Present completion proof to user.                                        |\n\n### 3. Update the TPP\n\nAfter each work session:\n\n- Check off completed phases/tasks\n- Add discoveries to Tribal Knowledge\n- Document failed approaches and why\n- Keep under 400 lines (trim redundancy)\n\n### 4. Completion\n\nWhen all phases are complete:\n\n1. Run verification commands from the TPP\n2. Ensure all tests pass (`npm test`)\n3. Review all changes for API compatibility with `node:sqlite`\n4. Present proof of completion to user\n5. After user approval, move TPP to `doc/done/` with date prefix\n\n```bash\n# Example: P01-fix-aggregate-null.md -> 20250203-P01-fix-aggregate-null.md\ngit mv doc/todo/P01-feature.md doc/done/$(date +%Y%m%d)-P01-feature.md\n```\n\n## Phase Details\n\n### Research & Planning\n\n- Read all \"Required reading\" in the TPP\n- Explore referenced source files\n- Check Node.js SQLite and better-sqlite3 for API reference\n- Web search for prior art if needed\n- Consult `../node-addon-api/` for N-API questions\n- Document findings in the TPP\n\n### Design Alternatives\n\n- Generate 2-4 approaches\n- Critique each for simplicity, testability, maintainability\n- Consider API compatibility with `node:sqlite`\n- Iterate at least 3 times\n- Document final recommendation in TPP\n\n### Task Breakdown\n\nEach task must include:\n\n- Clear deliverable\n- Files to change\n- Success criteria\n- Verification command\n\n### Implementation\n\n- Work tasks sequentially\n- Mark tasks complete as you go\n- Run verification after each task\n- Update TPP with any discoveries\n- Follow N-API best practices (see `../node-addon-api/`)\n\n## Remember\n\n- Transfer expertise, not just instructions\n- Document what didn''t work and why\n- Ask for clarification when uncertain\n- The next engineer should be able to continue seamlessly\n- Maintain API compatibility with `node:sqlite`\n"},"lastSynced":"2026-03-06T06:53:11.432Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing seamless SQLite database management and integration with Technical Project Plans.","zh":"非常适合需要无缝管理SQLite数据库并集成技术项目计划的开发代理。","ja":"SQLiteデータベースの無制限な管理とテクニカルプロジェクトプランとの統合が必要な開発エージェントに最適です。","ko":"SQLite 데이터베이스를 원활하게 관리하고 기술 프로젝트 계획과 통합해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión y integración de bases de datos SQLite sin problemas.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''une intégration de bases de données SQLite sans problème.","de":"Perfekt für Entwicklungsmittel, die eine reibungslose SQLite-Datenbankverwaltung und -integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de banco de dados SQLite sem interrupções e integração com Planos de Projetos Técnicos.","ru":"Идеально для агентов разработки, которым требуется бесшовное управление базами данных SQLite и интеграция с техническими планами проектов.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى إدارة قواعد بيانات SQLite دون انقطاع وتكامل مع خطط المشاريع الفنية."},"recommendation":{"en":"Empowers agents to manage SQLite databases with a drop-in replacement for node:sqlite, leveraging Technical Project Plans for structured development and adhering to guidelines outlined in CLAUDE.md, SIMPLE-DESIGN.md, TDD.md, and TPP-GUIDE.md.","zh":"赋予代理管理SQLite数据库的能力，使用node:sqlite的替代品，并利用技术项目计划进行结构化开发，遵循CLAUDE.md、SIMPLE-DESIGN.md、TDD.md和TPP-GUIDE.md中的指南。","ja":"エージェントがSQLiteデータベースを管理できるようにし、node:sqliteの代替品を使用して、テクニカルプロジェクトプランを利用して構造化された開発を行い、CLAUDE.md、SIMPLE-DESIGN.md、TDD.md、TPP-GUIDE.mdに概説されているガイドラインに従います。","ko":"에이전트가 SQLite 데이터베이스를 관리할 수 있게 해주고, node:sqlite의 대체品을 사용하여 기술 프로젝트 계획을 활용한 구조화된 개발을 가능하게 하며, CLAUDE.md, SIMPLE-DESIGN.md, TDD.md, TPP-GUIDE.md에 정리된 지침을 따르도록 합니다.","es":"Habilita a los agentes para gestionar bases de datos SQLite con un reemplazo directo de node:sqlite, aprovechando los Planes de Proyecto Técnico para un desarrollo estructurado y siguiendo las pautas establecidas en CLAUDE.md, SIMPLE-DESIGN.md, TDD.md y TPP-GUIDE.md.","fr":"Permet aux agents de gérer les bases de données SQLite avec un remplacement direct de node:sqlite, en exploitant les Plans de Projet Technique pour un développement structuré et en suivant les directives établies dans CLAUDE.md, SIMPLE-DESIGN.md, TDD.md et TPP-GUIDE.md.","de":"Ermächtigt die Agenten, SQLite-Datenbanken mit einer direkten Ersetzung von node:sqlite zu verwalten, indem sie technische Projektpläne für ein strukturiertes Entwicklung und unter Beachtung der Richtlinien in CLAUDE.md, SIMPLE-DESIGN.md, TDD.md und TPP-GUIDE.md nutzen.","pt":"Habilita os agentes a gerenciar bases de dados SQLite com um substituto drop-in para node:sqlite, aproveitando os Planos de Projetos Técnicos para desenvolvimento estruturado e aderindo às diretrizes estabelecidas em CLAUDE.md, SIMPLE-DESIGN.md, TDD.md e TPP-GUIDE.md.","ru":"Наделяет агентов возможностью управлять базами данных SQLite с помощью drop-in-замены для node:sqlite, используя технические планы проектов для структурированного развития и соблюдая руководящие принципы, изложенные в CLAUDE.md, SIMPLE-DESIGN.md, TDD.md и TPP-GUIDE.md.","ar":"يمنح الوكلاء القدرة على إدارة قواعد بيانات SQLite باستخدام بديل drop-in ل node:sqlite، مستفيدًا من خطط المشاريع الفنية للتنمية المهيكلة والامتثال للمبادئ التوجيهية المنصوص عليها في CLAUDE.md و SIMPLE-DESIGN.md و TDD.md و TPP-GUIDE.md."},"useCases":{"en":["Implementing Test-Driven Development for SQLite projects","Streamlining database management using TPP style guides","Integrating SQLite databases with Technical Project Plans for efficient development"],"zh":["实现SQLite项目的测试驱动开发","使用TPP风格指南简化数据库管理","将SQLite数据库与技术项目计划集成以实现高效开发"],"ja":["SQLiteプロジェクトのテスト駆動開発の実装","TPPスタイルガイドを使用したデータベース管理の合理化","SQLiteデータベースとテクニカルプロジェクトプランの統合による効率的な開発"],"ko":["SQLite 프로젝트의 테스트 주도 개발 구현","TPP 스타일 가이드를 사용한 데이터베이스 관리의 간소화","SQLite 데이터베이스와 기술 프로젝트 계획의 통합을 통한 효율적인 개발"],"es":["Implementación del Desarrollo Dirigido por Pruebas para proyectos SQLite","Optimización de la gestión de bases de datos utilizando guías de estilo de TPP","Integración de bases de datos SQLite con Planes de Proyecto Técnico para un desarrollo eficiente"],"fr":["Mise en œuvre du Développement Dirigé par les Tests pour les projets SQLite","Optimisation de la gestion des bases de données en utilisant des guides de style de TPP","Intégration des bases de données SQLite avec les Plans de Projet Technique pour un développement efficace"],"de":["Implementierung von Testgetriebenem Entwicklung für SQLite-Projekte","Optimierung der Datenbankverwaltung unter Verwendung von TPP-Stilguides","Integration von SQLite-Datenbanken mit technischen Projektplänen für ein effizientes Entwicklung"],"pt":["Implementação do Desenvolvimento Orientado a Testes para projetos SQLite","Racionalização da gestão de banco de dados usando guias de estilo TPP","Integração de bases de dados SQLite com Planos de Projetos Técnicos para desenvolvimento eficiente"],"ru":["Реализация разработки, управляемой тестами, для проектов SQLite","Упрощение управления базами данных с помощью руководств по стилю TPP","Интеграция баз данных SQLite с техническими планами проектов для эффективного развития"],"ar":["تنفيذ التطوير القائم على الاختبار لمشاريع SQLite","تيسير إدارة قواعد البيانات باستخدام كتيبات بأسلوب TPP","دمج قواعد بيانات SQLite مع خطط المشاريع الفنية من أجل التطوير الفعال"]},"limitations":{"en":["Requires knowledge of SQLite databases","Must adhere to TPP style guide and project rules","Technical Project Plan (TPP) required for implementation"],"zh":["需要SQLite数据库的知识","必须遵守TPP风格指南和项目规则","需要技术项目计划（TPP）来实现"],"ja":["SQLiteデータベースの知識が必要","TPPスタイルガイドとプロジェクトルールに従う必要がある","実装にはテクニカルプロジェクトプラン（TPP）が必要"],"ko":["SQLite 데이터베이스에 대한 지식이 필요","TPP 스타일 가이드와 프로젝트 규칙을 따라야 함","구현을 위해서는 기술 프로젝트 계획（TPP）가 필요"],"es":["Requiere conocimiento de bases de datos SQLite","Debe adherirse a la guía de estilo de TPP y las reglas del proyecto","Se requiere un Plan de Proyecto Técnico (TPP) para la implementación"],"fr":["Nécessite des connaissances en bases de données SQLite","Doit se conformer au guide de style de TPP et aux règles du projet","Un Plan de Projet Technique (TPP) est requis pour la mise en œuvre"],"de":["Benötigt Kenntnisse von SQLite-Datenbanken","Muss den TPP-Stilguide und die Projektregeln einhalten","Ein technischer Projektplan (TPP) ist für die Implementierung erforderlich"],"pt":["Exige conhecimento de bases de dados SQLite","Deve aderir ao guia de estilo TPP e às regras do projeto","Plano de Projeto Técnico (TPP) necessário para implementação"],"ru":["Требует знания баз данных SQLite","Должно следовать руководству по стилю TPP и правилам проекта","Технический план проекта (TPP) необходим для реализации"],"ar":["يتطلب معرفة بقواعد بيانات SQLite","يجب الامتثال لدليل الأسلوب TPP وقواعد المشروع","خطة مشروع تقني (TPP) مطلوبة للتنفيذ"]},"version":4},"contentHash":"e7b4578bbdcad8cbaa6b9c2bcd9df9b47b853f141cc0d66b51af1a8de353db0b","qualityScore":42}');
